INSERT INTO `t_mode` VALUES (0, '1', '一年内到期的非流动资产在期末减少', 'ZCFZ_R - ZCFZ_R1 < 0', '一年内到期的非流动资产减少，考虑是否因为资金回笼还是对该资产进行处置。若为对资产进行处置，建议管理层关注处置的原因、必要性及所得情况。同时，需结合资金情况及资金预警，做好未来的资金投资规划，避免资金闲置或紧张情况的出现。', '', '', '10004', '', 20);
INSERT INTO `t_mode` VALUES (4, '2', '利润表-xx模块-xx功能', 'LR_Q >= 500000', '模板测试，利润表管理费用：{LR_Q}，管理费用+财务费用：{LR_Q+LR_R}', '{LR_Q},{LR_Q+LR_R}', '2代表报表类型中的利润表，这个应该是可以选择的，\r\n还有一个MODE_AREA字段未维护，该字段用来表示该模板放置的位置', '1', '该字段可以不用', 4);
INSERT INTO `t_mode` VALUES (12, '1', '应收利息增加', 'ZCFZ_L-ZCFZ_L1>0', '由于应收利息为购买债券的到期应收未收利息，因此，针对应收利息的增加，建议管理层需结合货币资金中的资金预警考虑，是否存在过度投资，导致现金不足的情况。建议针对债券进行专人专管，检查是否按要求设立备查薄，方便管理。同时，建议管理层使用本系统的在线咨询模块中的顾问咨询，由专业顾问提供针对性分析及建议。', '', '', '10001', '', 12);
INSERT INTO `t_mode` VALUES (13, '1', '应收利息减少', 'ZCFZ_L - ZCFZ_L1 < 0', '应收利息的减少，建议管理层结合债券的购买及到期情况做判断，如减少由债券购买的减少导致，或者因债券到期所导致，均属于正常情况，如出现相反趋势，建议管理层对其进行查询。建议针对债券进行专人专管，检查是否按要求设立备查薄，方便管理。可使用本系统在线咨询模块中的专项咨询服务，为企业设立完善的管理控制流程，提高管理效率。', '', '', '10001', '', 13);
INSERT INTO `t_mode` VALUES (15, '1', '应收股利增加', 'ZCFZ_M-ZCFZ_M1>0', '应收股利增加，建议结合长期股权投资、可供出售金融资产等科目情况，关注是否与股权投资收益情况相符，同时需关注后期股利资金发放。', '', '', '10002', '', 15);
INSERT INTO `t_mode` VALUES (16, '1', '应收股利减少', 'ZCFZ_M - ZCFZ_M1< 0', '应收股利减少，建议结合长期股权投资、可供出售金融资产等科目情况，关注是否与股权投资收益情况或处置股权资产相符。若因资产处置，则需重点关注处置原因、必要性及结果，以防不利于企业利益的情形出现。', '', '', '10002', '', 16);
INSERT INTO `t_mode` VALUES (17, '1', '以公允价值计量且其变动计入当期损益的金融资产在期末增加', 'ZCFZ_D-ZCFZ_D1>0', '由于以公允价值计量且其变动计入当期损益的金融资产核算的类别较为特殊，且此类资产为非经营类资产，因此期末值的增加提请管理层关注进行该资产交易的原因以及其增减值情况，注重风险控制。', '', '', '10003', '', 17);
INSERT INTO `t_mode` VALUES (18, '1', '以公允价值计量且其变动计入当期损益的金融资产在期末减少', 'ZCFZ_D - ZCFZ_D1< 0', '由于以公允价值计量且其变动计入当期损益的金融资产核算的类别较为特殊，且此类资产为非经营类资产，因此期末值的减少提请管理层考虑是有因减值还是资产处置导致期末值减少。若为减值造成，则需重点注意该资产的价值变动，注意风险控制。若为资产处置造成，则提醒管理层关注处置的原因、必要性及结果，以防做出不利于企业利益的行为。', '', '', '10003', '', 18);
INSERT INTO `t_mode` VALUES (19, '1', '一年内到期的非流动资产在期末增加', 'ZCFZ_R - ZCFZ_R1 > 0', '一年内到期的非流动资产增加，仍需持续关注该资产的回收可能性。此外，管理层需结合资金情况及资金预警，做好未来的资金投资规划，避免资金闲置或紧张情况的出现。', '', '', '10004', '', 19);
INSERT INTO `t_mode` VALUES (21, '1', '其他流动资产较上期浮动>=20%', 'ZCFZ_S==0&&ZCFZ_S1!=0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10005', '', 21);
INSERT INTO `t_mode` VALUES (22, '1', '其他流动资产较上期浮动<20%', '-0.2 < (ZCFZ_S-ZCFZ_S1)/ZCFZ_S1 && (ZCFZ_S-ZCFZ_S1)/ZCFZ_S1 < 0.2', '无预警。', '', '', '10005', '', 22);
INSERT INTO `t_mode` VALUES (23, '1', '持有待售的资产增加', 'ZCFZ_Q1!=0 && ZCFZ_Q - ZCFZ_Q1 > 0', '由于该科目核算的类别较为特殊，且此类资产为非经营类资产，因此期末值的增加提请管理层关注进行该资产交易的原因以及其增减值情况，注重风险控制。', '', '', '10006', '', 23);
INSERT INTO `t_mode` VALUES (24, '1', '持有待售的资产减少', 'ZCFZ_Q1!=0 && ZCFZ_Q - ZCFZ_Q1 < 0', '由于该科目核算的类别较为特殊，且此类资产为非经营类资产，因此期末值的减少提请管理层考虑是有因减值还是资产处置导致期末值减少。若为减值造成，则需重点注意该资产的价值变动，注意风险控制。若为资产处置造成，则提醒管理层关注处置的原因、必要性及结果，以防做出不利于企业利益的行为。', '', '', '10006', '', 24);
INSERT INTO `t_mode` VALUES (25, '1', '可供出售金融资产增加', 'ZCFZ_V > ZCFZ_V1', '由于可供出售金融资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上期有所增加，需查找原因并关注已实现的增值额，同时需注意核算时点、计量金额是否会计准则要求。且需警惕因期末可供出售金融资产市场价值变动产生的增值，存在变现的不确定性。', '', '', '10007', '', 25);
INSERT INTO `t_mode` VALUES (26, '1', '可供出售金融资产减少', 'ZCFZ_V < ZCFZ_V1', '由于可供出售金融资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末改科目余额比上期有所减少，需查找原因并关注已实现的减值额，且需警惕可供出售金融资产市场价值变动产生的损失，存在不确定性。同时，若存在处置该资产的情形，则需注意处置的原因、必要性及结果，以防不利于企业利益的行为发生。', '', '', '10007', '', 26);
INSERT INTO `t_mode` VALUES (27, '1', '持有至到期投资增加', 'ZCFZ_W > ZCFZ_W1', '建议管理层了解该科目的资产类别，如为理财类投资支出的增加引起，需考虑闲置资金较多，建议合理规划资金使用及流转速度，避免资金闲置引起的浪费。同时需注意核算时点、计量金额是否符合会计准则要求。', '', '', '10008', '', 27);
INSERT INTO `t_mode` VALUES (28, '1', '持有至到期投资减少', 'ZCFZ_W < ZCFZ_W1', '建议管理层了解该科目的资产类别，关注其减少的原因。同时，需考虑是否存在运营资金不充足而出售长期股权投资的情形，建议管理层合理规划资金使用及流转速度，避免资金不足影响生产经营。同时需注意核算时点、计量金额是否会计准则要求。', '', '', '10008', '', 28);
INSERT INTO `t_mode` VALUES (29, '1', '固定资产增加', 'ZCFZ_AA- ZCFZ_AA1>0', '固定资产有所增加，管理层应注意关注固定资产的转固时间及条件是否符合会计准则的要求，是否需要进行账务调整。另外，本期投入大量固定资产，建议管理层结合相关资产的付款期限考虑后期付款资金的充足性。', '', '', '10009', '', 29);
INSERT INTO `t_mode` VALUES (30, '1', '固定资产减少', 'ZCFZ_AA-ZCFZ_AA1>0', '固定资产有所减少，管理层需注意区分是因资产处置还是折旧年限已到期。若为资产处置，需关注处置的原因、必要性及所得情况；若为资产折旧年限已到期，则需注意是否有重要设备折旧年限已到期，需提前准备新设备的采购或对旧设备进一步维护维修，确保生产正产运作。', '', '', '10009', '', 30);
INSERT INTO `t_mode` VALUES (31, '1', '在建工程增加', 'ZCFZ_AB > ZCFZ_AB1', '在建工程的增加，需考虑在未来几年对工程需投入的资金，考虑未来期间对现金流可能产生的压力。', NULL, NULL, '10010', NULL, 31);
INSERT INTO `t_mode` VALUES (32, '1', '在建工程减少', 'ZCFZ_AB < ZCFZ_AB1', '在建工程的减少，需注意区分是转入固定资产还是资产处置原因。若为转入固定资产，则需关注转入的时点、条件以及计量金额是否符合会计准则的要求，确保账务核算准确；若为资产处置原因，则需关注处置的原因、必要性以及所得情况。', '', '', '10010', '', 32);
INSERT INTO `t_mode` VALUES (33, '1', '长期应收款增加', 'ZCFZ_X-ZCFZ_X1>0', '本期长期应收款较上期末有所增加，考虑是否存在期末大量发生融资租赁的情况而导致长期应收款的增加。由于融资租赁的特殊性，建议管理层对该部分资产进行专人管理，设立专门的登记薄记录相关情况，同时，考虑融资租赁业务对整个企业业务及收益的影响。', '', '', '10011', '', 33);
INSERT INTO `t_mode` VALUES (34, '1', '长期应收款减少', 'ZCFZ_X-ZCFZ_X1<0', '长期应收款在期末有所减少，考虑是因为资金回笼亦或是公司融资租赁业务的缩减。若因业务缩减引起长期应收款的期末减少，建议管理层联合市场部等相关部门，评判融资租赁业务对企业总体收益的影响，从而对融资租赁业务的发展做出合理规划。', '', '', '10011', '', 34);
INSERT INTO `t_mode` VALUES (35, '1', '长期股权投资增加', 'ZCFZ_Y-ZCFZ_Y1>0', '由于长期股权投资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上期有所增加，需查找原因，同时需注意核算时点、计量金额是否会计准则要求。注意按收益法核算的长期股权投资在期末根据被投资企业的经营结果调整长期股权投资的账面价值。同时，需关注按成本法核算的长期股权投资是否存在减值情况。此外，如果长期股权投资金额的增加是因为债务重组或非货币性资产交换获得，建议考虑评估该部分资产未来可能产生的收益，以及对企业利润的影响。', '', '', '10012', '', 35);
INSERT INTO `t_mode` VALUES (36, '1', '长期股权投资减少', 'ZCFZ_Y-ZCFZ_Y1<0', '由于长期股权投资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上期有所减少，需查找原因并关注已实现的减值额，同时需注意核算时点、计量金额等是否会计准则要求。注意按收益法核算的长期股权投资在期末根据被投资企业的经营结果调整长期股权投资的账面价值。同时，需关注按成本法核算的长期股权投资是否存在减值情况以及是否存在大量处置该资产情况，若存在处置资产情况，则需关注处置的原因、必要性及结果，以防不利于企业利益的情况发生。', '', '', '10012', '', 36);
INSERT INTO `t_mode` VALUES (37, '1', '投资性房地产增加', 'ZCFZ_Z-ZCFZ_Z1>0', '由于投资性房地产核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上期有所增加，需查找原因并关注已实现的增值额，同时需注意核算时点、计量金额是否会计准则要求。且需警惕因期末投资性房地产市场价值变动产生的增值，存在变现的不确定性。另外，建议管理层考虑目前房地产产业发展的减缓趋势，结合国家对房地产业的宏观政策，评判投资性房地产在企业利润中所占的份额，考虑是否需要调整对投资性房地产的投入。', '', '', '10013', '', 37);
INSERT INTO `t_mode` VALUES (38, '1', '投资性房地产减少', 'ZCFZ_Z-ZCFZ_Z1<0', '由于投资性房地产核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上期有所减少，需查找原因并关注已实现的减值额，同时需注意核算时点、计量金额是否会计准则要求。同时，需关注是否存在大量处置该资产情况，若存在处置资产情况，则需关注处置的原因、必要性及结果，以防不利于企业利益的情况发生。', '', '', '10013', '', 38);
INSERT INTO `t_mode` VALUES (39, '1', '工程物资增加', 'ZCFZ_AC-ZCFZ_AC1>0', '期末该科目余额比上期有所增加，需查找原因，关注与在建工程的关联关系。此外，管理层需考虑工程进度对工程物资的采购的影响，合理规划，避免工程物资的囤积，同时对采购工程物资需投入的资金进行合理规划，避免出现资金紧张的情况。', '', '', '10014', '', 39);
INSERT INTO `t_mode` VALUES (40, '1', '工程物资减少', 'ZCFZ_AC-ZCFZ_AC1<0', '期末该科目余额比上期有所减少，需查找原因，关注与在建工程的关联关系。同时，由于工程物资的特殊性，建议管理层关注。', '', '', '10014', '', 40);
INSERT INTO `t_mode` VALUES (41, '1', '固定资产清理增加', 'ZCFZ_AD > ZCFZ_AD1', '固定资产清理有所增加，需关注清理固定资产的原因及必要性，并预估清理所得及对企业造成的损失。同时，管理层需考虑是否需要投入资金重置相关固定资产以对清理资产进行置换，如需，则建议结合货币资金中的资金预测，分析对未来现金流的影响程度，合理规划资金使用及购置计划，避免资金紧张的情况出现。', '', '', '10015', '', 41);
INSERT INTO `t_mode` VALUES (42, '1', '固定资产清理减少', 'ZCFZ_AD < ZCFZ_AD1', '固定资产清理有所减少，建议管理层评估已清理的固定资产的所得。此外，鉴于固定资产清理科目的性质，建议管理层评估该科目波动的合理性。', '', '', '10015', '', 42);
INSERT INTO `t_mode` VALUES (43, '1', '无形资产增加', 'ZCFZ_AG-ZCFZ_AG1>0', '无形资产有所增加，应考虑是属于自主开发亦或购买形成，若为自主开发，应注意关注无形资产的确认时间及条件是否符合会计准则的要求，是否需要进行账务调整。同时，需持续关注无形资产对生产运营所带来的效益情况，注意重要技术的排他性和保密性。', '', '', '10016', '', 43);
INSERT INTO `t_mode` VALUES (44, '1', '无形资产减少', 'ZCFZ_AG-ZCFZ_AG1<0', '无形资产有所减少，需考虑是由于摊销导致的正常减少，亦或因为处置或减值造成。若因处置导致，需关注处置的原因、必要性和所得；若因减值导致，建议管理层评估因技术落后可能给企业未来运营及发展带来的风险，考虑是否需要重新投入研发，如需投入研发新技术，则需考虑研发支出对未来现金流的需求以及影响，合理规划。', '', '', '10016', '', 44);
INSERT INTO `t_mode` VALUES (45, '1', '开发支出增加', 'ZCFZ_AH-ZCFZ_AH1>0', '开发支出有所增加，应注意关注开发支出的确认时间及条件是否符合会计准则的要求，并相应进行账务调整。建议管理层就开发支出是否可以资本化的问题使用在线顾问模块中的企业顾问功能，咨询专业顾问具体支出的性质，达到企业利益最大化。', '', '', '10017', '', 45);
INSERT INTO `t_mode` VALUES (46, '1', '开发支出减少', 'ZCFZ_AH-ZCFZ_AH1<0', '开发支出有所减少，需考虑是由于转入无形资产、处置还是减值造成。若为处置情况，需关注处置的原因、必要性和所得；若为减值情况，建议管理层需重视企业的技术创新，评估技术风险。', '', '', '10017', '', 46);
INSERT INTO `t_mode` VALUES (47, '1', '商誉增加', 'ZCFZ_AI-ZCFZ_AI1>0', '商誉的增加，往往出现在资产并购情况中，需重点关注事项发生的全过程，注意商誉变动的原因，并合理判断商誉计量金额的准确性。', '', '', '10018', '', 47);
INSERT INTO `t_mode` VALUES (48, '1', '商誉减少', 'ZCFZ_AI-ZCFZ_AI1<0', '商誉的减少，需考虑是由于资产处置还是资产减值造成，若为资产处置，需关注处置事项的原因及、必要性及所得；若为资产减值，则需查明减值原因，并防范该减值所带来的不利影响。', '', '', '10018', '', 48);
INSERT INTO `t_mode` VALUES (49, '1', '长期待摊费用增加', 'ZCFZ_AJ - ZCFZ_AJ1 > 0', '长期待摊费用有所增加，需查明原因，并注意区分待摊费用和直接费用化情形，确保核算符合会计准则。', '', '', '10019', '', 49);
INSERT INTO `t_mode` VALUES (50, '1', '长期待摊费用减少', 'ZCFZ_AJ-ZCFZ_AJ1<0', '长期待摊费用有所减少，需查明原因，考虑是否因正常摊销引起，若非，则需关注减少原因。', '', '', '10019', '', 50);
INSERT INTO `t_mode` VALUES (51, '1', '递延所得税资产增加', 'ZCFZ_AK-ZCFZ_AK1>0', '递延所得税资产的产生，是因为资产的账面价值大于计税基础，或负债的账面价值小于计税基础，导致会计确认的所得税小于税法确认的所得税，从而产生递延所得税资产。递延所得税资产增加，需关注其确认条件、计量金额是否符合会计准则。建议管理层使用在线顾问模块中的专项顾问功能，为企业进行整体税收筹划，进行合理避税，减少企业利润不必要的损耗。同时，建议管理层检查是否已按要求设立备查薄。', '', '', '10020', '', 51);
INSERT INTO `t_mode` VALUES (52, '1', '递延所得税资产减少', 'ZCFZ_AK-ZCFZ_AK1<0', '递延所得税资产的产生，是因为资产的账面价值大于计税基础，或负债的账面价值小于计税基础，导致会计确认的所得税小于税法确认的所得税，从而产生递延所得税资产。递延所得税资产减少，需关注其确认条件、计量金额是否符合会计准则。建议管理层使用在线顾问模块中的专项顾问功能，为企业进行整体税收筹划，进行合理避税，减少企业利润不必要的损耗。同时，建议管理层检查是否已按要求设立备查薄。', '', '', '10020', '', 52);
INSERT INTO `t_mode` VALUES (53, '1', '其他非流动资产余额较上期浮动>=20%', 'ZCFZ_AL1!=0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1-0.2>0', '其他非流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10021', '', 53);
INSERT INTO `t_mode` VALUES (54, '1', '应收票据变动', 'ZCFZ_F != ZCFZ_F1', '企业应根据汇票的种类及规定及时行使提示承兑、提示付款等权利。否则，汇票未按照规定期限提示承兑的，持票人丧失对其前手的追索权；持票人超过提示付款期限提示付款的，持票人开户银行不予受理，此时企业需通过其他方式或途径追偿其应收款项。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10022', '', 54);
INSERT INTO `t_mode` VALUES (55, '1', '短期借款增加', 'ZCFZ_AO-ZCFZ_AO1>0', '短期借款的增加，说明企业现金流较为紧张，需要通过银行贷款缓解资金压力，建议合理规划资金使用情况，同时，查看应收账款的情况，对应收账款进行催收，亦可与供应商进行谈判，延长付款期，缓解资金压力。', '', '', '10023', '', 55);
INSERT INTO `t_mode` VALUES (56, '1', '短期借款减少', 'ZCFZ_AO-ZCFZ_AO1<0', '短期借款有所减少，考虑该借款是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，合理规划资金安排，控制资金压力。', '', '', '10023', '', 56);
INSERT INTO `t_mode` VALUES (57, '1', '应付票据变动', 'ZCFZ_AU-ZCFZ_AU1>0', '由于银行承兑汇票的付款期限最长为6个月，因此，使用票据实际上对企业来说可实现短期融资的目的，在短期现金流较为紧张的情况下，可考虑采取使用开具应付票据的方式减轻企业现金负担。然而，需注意以下可能产生的问题及风险：应付商业票据是购买企业在正常商业活动中向供应商承诺在将来特定时日、支付一笔固定货款的票据。与应付账款相比，应付商业票据由于提出了付款的书面承诺，因而更具有法律上的约束力。此外，企业应于汇票到期前将票款足额交存其开户银行，以免银行对企业进行计收利息及引起相关法律诉讼纠纷。同时建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10024', '', 57);
INSERT INTO `t_mode` VALUES (58, '1', '一年内到期的非流动负债增加', 'ZCFZ_BJ-ZCFZ_BJ1>0', '由于一年内到期的非流动负债主要为从长期借款转入的负债，长期借款即将到期，需考虑是否需要对长期借款进行续借或新借。建议分析未来5年资金需求，合理规划贷款金额。同时，如需新增长期借款，需考虑企业固定资产等是否有足够的抵押物进行抵押借款，或是否有足够的资信可进行其他类型的贷款。', '', '', '10025', '', 58);
INSERT INTO `t_mode` VALUES (59, '1', '一年内到期的非流动负债减少', 'ZCFZ_BJ-ZCFZ_BJ1<0', '由于一年内到期的非流动负债主要为一年内到期的长期借款等，对于企业来说，由于之前的资金需求产生的贷款在近期内需进行偿还，因此需分析资金状况在未来一年内是否可以满足其偿还需求。若资金紧张，则需考虑通过借款、延长支付期限等方式缓解资金压力。', '', '', '10025', '', 59);
INSERT INTO `t_mode` VALUES (60, '1', '应付职工薪酬增加', 'ZCFZ_AZ- ZCFZ_AZ1>0', '应付职工薪酬增加，考虑是否因正常人员增加所引起的。若员工大量增加，需关注企业的人工成本、人工效率。同时，若计划进行资本运作，则还需关注员工五险一金的缴纳是否按照相关规定执行，否则可能面临被主管单位要求补缴和处罚的情形。', '', '', '10026', '', 60);
INSERT INTO `t_mode` VALUES (61, '1', '应付职工薪酬减少', 'ZCFZ_AZ-ZCFZ_AZ1<0', '应付职工薪酬减少，考虑是否因正常人员减少引起的。若员工大量减少，需关注核心技术人员是否离职，人员减少后是否会对企业运营产生影响，需注意企业生产运营的稳定性。同时，若计划进行资本运作，则还需关注员工五险一金的缴纳是否按照相关规定执行，可能面临被主管单位要求补缴和处罚的情形。', '', '', '10026', '', 61);
INSERT INTO `t_mode` VALUES (62, '1', '应交税费增加', 'ZCFZ_BA>ZCFZ_BA1', '应交税费的有所增加，主要考虑是否因业务的增长造成。若与业务不匹配，则考虑是否存在税收政策变化等特殊情况。建议使用本系统顾问咨询中的专项咨询，由专业顾问为企业进行税收筹划，达到合理避税，利润最大化的目的。', '', '', '10027', '', 62);
INSERT INTO `t_mode` VALUES (63, '1', '应交税费减少', 'ZCFZ_BA<ZCFZ_BA1', '应交税费的有所减少，主要考虑是否因业务的减少造成。若与业务不匹配，则考虑是否存在税收政策变化等特殊情况。建议使用本系统顾问咨询中的专项咨询，由专业顾问为企业进行税收筹划，达到合理避税，利润最大化的目的。', '', '', '10027', '', 63);
INSERT INTO `t_mode` VALUES (64, '1', '应付利息变动', 'ZCFZ_BB != ZCFZ_BB1', '针对应付利息，提请管理层关注以下方面的问题：1、需查看借款合同，核查应付利息的确认时间和计量金额是否符合会计准则；2、关注付款期限及已支付金额，考虑自身资金压力；3、关注逾期未支付的违约责任及违约时间点。', NULL, NULL, '10028', NULL, 64);
INSERT INTO `t_mode` VALUES (65, '1', '应付股利变动', 'ZCFZ_BC-ZCFZ_BC1>0', '关注该科目的变动是否与企业宣告派发的股利相符合，同时需考虑支付能力，结合企业未来的生产经营计划关注资金压力问题。', '', '', '10029', '', 65);
INSERT INTO `t_mode` VALUES (66, '1', '其他流动负债浮动超过20%', 'ZCFZ_BK1!=0&&(ZCFZ_BK-ZCFZ_BK1)/ZCFZ_BK1-0.2>0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10030', '', 66);
INSERT INTO `t_mode` VALUES (67, '1', '长期借款增加', 'ZCFZ_BM1!=0&&ZCFZ_BM-ZCFZ_BM1>0', '长期借款的增加，需关注未来还本付息对现金流的影响，除此之外，建议管理层整理贷款明细表对贷款情况进行归纳统计，关注合同中对贷款使用的限定，并安排专人负责对资金使用情况等进行追踪，规避因违规使用资金可能产生的风险。', '', '', '10031', '', 67);
INSERT INTO `t_mode` VALUES (68, '1', '长期借款减少', 'ZCFZ_BM1!=0&&ZCFZ_BM-ZCFZ_BM1<0', '长期借款的减少，考虑该借款是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', '', '10031', '', 68);
INSERT INTO `t_mode` VALUES (69, '1', '应付债券增加', 'ZCFZ_BN-ZCFZ_BN1>0', '应付债券的增加，需关注未来还本付息对现金流的影响以及如未能按期支付利息或本金可能产生的法律风险。除此之外，提请管理层关注债券的募集说明书中赋予投资者的权利，避免因投资者根据募集说明书行使权利时双方可能产生的分歧。另外，建议管理层对债券设专人管理及专门的登记本，记录债券相关情况。', '', '', '10032', '', 69);
INSERT INTO `t_mode` VALUES (70, '1', '应付债券减少', 'ZCFZ_BN-ZCFZ_BN1<0', '应付债券的减少，考虑该债券是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', '', '10032', '', 70);
INSERT INTO `t_mode` VALUES (71, '1', '长期应付款变动', 'ZCFZ_BQ1!=0&&ZCFZ_BQ-ZCFZ_BQ1>0', '由于一般性经营较少使用此科目，建议管理层查看此科目核算的内容，关注发生的原因及合理性，看是否存在因记账错误导致的余额变动。如非上述原因，则需根据科目核算的性质，考虑未来分期付款或融资租赁时支付款项对现金流的影响。', '', '', '10033', '', 71);
INSERT INTO `t_mode` VALUES (73, '1', '递延所得税负债增加', 'ZCFZ_BV-ZCFZ_BV1>0', '递延所得税负债的产生，是因为资产的账面价值小于计税基础，或负债的账面价值大于计税基础而，导致会计确认的所得税大于税法确认的所得税，从而产生递延所得税负债。递延所得税负债有所增加，需关注其确认条件、计量金额是否符合会计准则。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10036', '', 73);
INSERT INTO `t_mode` VALUES (74, '1', '递延所得税负债减少', 'ZCFZ_BV < ZCFZ_BV1', '递延所得税负债的产生，是因为资产的账面价值小于计税基础，或负债的账面价值大于计税基础而，导致会计确认的所得税大于税法确认的所得税，从而产生递延所得税负债。递延所得税负债有所减少，需关注其确认条件、计量金额是否符合会计准则。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10036', '', 74);
INSERT INTO `t_mode` VALUES (75, '1', '其他非流动负债浮动超过20%', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1-0.2>0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', '', '', '10037', '', 75);
INSERT INTO `t_mode` VALUES (76, '1', '递延收益增加', 'ZCFZ_BU-ZCFZ_BU1>0', '递延收益的增加，需关注增加的原因及递延收益确认的条件是否合规。若为政府补贴产生的递延收益，则建议管理层重点关注补贴收入实现的相关条件，确保项目的开展符合政府相关规定。', '', '', '10038', '', 76);
INSERT INTO `t_mode` VALUES (77, '1', '递延收益减少', 'ZCFZ_BU-ZCFZ_BU1<0', '递延收益的减少，需关注减少的原因及转入收益的条件是否合规。特别是政府补贴产生的递延收益，管理层需重点关注补贴收入实现的相关条件，确保项目的开展符合政府相关规定。', '', '', '10038', '', 77);
INSERT INTO `t_mode` VALUES (78, '1', '长期应付职工薪酬增加', 'ZCFZ_BR > ZCFZ_BR1', '长期应付职工薪酬大幅度增加，管理层应关注其增长的原因。若是因现金流不足而长时间无法支付职工工资薪酬，则企业需努力扩大生产、节约成本及多渠道融资，开源节流渡过难关。若是因劳务纠纷而存在长期应付款增长，则建议管理层关注劳务纠纷的原因及法律后果。', NULL, NULL, '10039', NULL, 78);
INSERT INTO `t_mode` VALUES (79, '1', '长期应付职工薪酬减少', 'ZCFZ_BR < ZCFZ_BR1', '长期应付职工薪酬大幅度减少，若是因企业支付员工薪酬所导致，则需关注企业目前的资金流状况，以防出现资金流不足的情况。若是因劳务纠纷已解决，则需关注纠纷解决的过程及带来的法律后果。', NULL, NULL, '10039', NULL, 79);
INSERT INTO `t_mode` VALUES (80, '1', '实收资本增加', 'ZCFZ_BZ-ZCFZ_BZ1>0', '实收资本增加，需核查新增股东的股权比例、新增资金到位以及工商变更情况。若为资本公积转增实收资本，则需同税局确认是否需缴纳所得税，规避税务风险。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10040', '', 80);
INSERT INTO `t_mode` VALUES (81, '1', '实收资本减少', 'ZCFZ_BZ-ZCFZ_BZ1<0', '实收资本减少，需注意是否已经全体债权人同意，确保减资程序合规。同时，关注实收资本的减少是否导致现金流的支出，注意企业的资金情况。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10040', '', 81);
INSERT INTO `t_mode` VALUES (82, '1', '资本公积增加', 'ZCFZ_CD-ZCFZ_CD1>0', '资本公积增加，需核查新增股东的股权比例、新增资金到位以及工商变更情况。若为盈余公积转增实收资本，则需同税局确认是否需缴纳所得税，规避税务风险。', '', '', '10041', '', 82);
INSERT INTO `t_mode` VALUES (83, '1', '资本公积减少', 'ZCFZ_CD-ZCFZ_CD1<0', '资本公积减少，需考虑是否存在资本公积转入实收资本或进行股份制改革的情况，并同税局确认是否资本公积转实收资本或进行股改时股东是否需缴纳所得税，从而规避漏税风险。', '', '', '10041', '', 83);
INSERT INTO `t_mode` VALUES (84, '1', '盈余公积增加', 'ZCFZ_CH > ZCFZ_CH1', '盈余公积增加，需注意是否同净利润增加相符。', NULL, NULL, '10042', NULL, 84);
INSERT INTO `t_mode` VALUES (85, '1', '盈余公积减少', 'ZCFZ_CH < ZCFZ_CH1', '盈余公积减少，需考虑是否存在盈余公积转入实收资本或资本公积或进行股份制改革的情况，并同税局确认盈余公积转资本公积或实收资本或进行股改时股东是否需缴纳所得税，从而规避漏税风险', NULL, NULL, '10042', NULL, 85);
INSERT INTO `t_mode` VALUES (86, '1', '未分配利润增加', 'ZCFZ_CJ-ZCFZ_CJ1>0', '未分配利润增加，需注意是否同本期净利润相符。', '', '', '10043', '', 86);
INSERT INTO `t_mode` VALUES (87, '1', '未分配利润减少', 'ZCFZ_CJ-ZCFZ_CJ1<0', '未分配利润减少，需注意是否同本期净利润变动相符以及是否宣告分派了利润。同时，需考虑是否存在将未分配利润转入实收资本或资本公积或进行股份制改革的情况，需同税局确认未分配利润转实收资本或资本公积或进行股份制改革时股东是否需缴纳所得税，从而规避漏税风险。', '', '', '10043', '', 87);
INSERT INTO `t_mode` VALUES (91, '3', '现金流量预警2.2', 'XJLL_Y > 0 && XJLL_AM>0 && XJLL_AZ < 0 && XJLL_BB > 0 &&XJLL_Y- XJLL_AM>0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 91);
INSERT INTO `t_mode` VALUES (93, '3', '现金流量预警模板4', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ < 0 && XJLL_BB > 0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 93);
INSERT INTO `t_mode` VALUES (94, '3', '现金流量预警3.1', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB > 0 && XJLL_Y-XJLL_AZ<0', '尽管本期经营活动产生的现金流量净额为正数，但其金额小于筹资活动产生的现金流量净额，说明企业本期现金流主要由筹资活动支撑，建议管理层考虑后续还本付息对现金流的影响。除此以外，建议管理层改善经营活动现金流，考虑以下措施：1)对库存商品进行促销，增加收入，改善现金流入；2)加快应收款的催收，加速现金回笼；3)对成本及费用进行严格控制，减少不必要开支，从而做到开源节流。另外，投资活动产生的现金流量净额为负数，证明企业本期有大量的购置固定资产或投资性资金流出，建议管理层做投资回报的测算，查看是否达到预期，同时，如筹资活动的资金借入主要为支撑投资活动的支出而发生，建议评估两者的流入流出，考虑是否不必要的投资活动需要进行缩减。', '', '', '300001', '', 94);
INSERT INTO `t_mode` VALUES (95, '3', '现金流量预警3.2', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB > 0 && XJLL_Y - XJLL_AZ>0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 95);
INSERT INTO `t_mode` VALUES (96, '3', '现金流量预警5', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ > 0 && XJLL_BB > 0', '由于经营活动产生的现金流量净额为负数，但最终的现金及现金等价物净增加额为正数，说明企业的现金流实际上是依靠投资及筹资活动产生，并非健康的现金流状况。建议管理层做好现金流管理，查看经营活动现金流为负数的主要原因。', '', '', '300001', '', 96);
INSERT INTO `t_mode` VALUES (97, '3', '现金流量预警6', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB > 0', '由于经营活动和筹资活动产生的现金流量净额为负数，但最终的现金及现金等价物净增加额为正数，说明企业的现金流实际上是依靠投资活动产生，并非健康的现金流状况。建议管理层做好现金流管理，查看经营活动现金流为负数的主要原因。', '', '', '300001', '', 97);
INSERT INTO `t_mode` VALUES (98, '3', '现金流量预警7', 'XJLL_Y < 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB > 0', '由于经营活动及投资活动产生的现金流量净额均为负数，而最终的现金及现金等价物净增加额为正数，因此，企业本期的现金流由筹资活动支撑。建议管理层评估后续还本付息对现金流产生的压力，同时，需考虑如何改善现金流状况。如：加强市场开拓获取经营现金流入、加快销售款的回收并延长采购款的支付期限、延长借款期限缓解前期还本付息压力或引入新投资款用以偿还有息借款。', '', '', '300001', '', 98);
INSERT INTO `t_mode` VALUES (99, '3', '现金流量预警8', 'XJLL_Y > 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB < 0', '本期企业大量归还筹资活动借入的款项，导致总体现金及现金等价物净增加额为负数，建议管理层查看未来是否仍存在大量的归还筹资活动款项的支出，考虑对现金流的影响，避免资金链出现问题。', '', '', '300001', '', 99);
INSERT INTO `t_mode` VALUES (100, '3', '现金流量预警9', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB < 0', '本期现金及现金等价物净增加额为负数，主要是由于投资活动的大量现金流出引起。建议管理层查看投资活动的必需性，削减不必要的投资，同时，考虑投资回报率，进行投资测算，对投资款项的支出进行严格监控。对于使用贷款进行的投资活动，需考虑贷款合同对贷款用途的限定，查看是否存在违规使用贷款的情况。', '', '', '300001', '', 100);
INSERT INTO `t_mode` VALUES (101, '3', '现金流量预警10', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ < 0 && XJLL_BB < 0', '最终现金及现金等价物净增加额为负数说明经营活动产生的现金流不足以支撑投资及筹资活动所需要资金。建议管理层查看投资活动的必需性，削减不必要的投资，同时，考虑投资回报率，进行投资测算，对投资款项的支出进行严格监控。而且争取延长借款期限，缓解前期还本付息压力，或查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 101);
INSERT INTO `t_mode` VALUES (102, '3', '现金流量预警11', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ > 0 && XJLL_BB < 0', '本期现金及现金等价物净增加额为负数，管理层需高度警惕，预防现金流不足对未来经营肯可能产生的影响。经营活动产生的现金流量净额为负数，反映企业经营不善，对未来进行贷款及信用评级等均有可能受到影响。', '', '', '300001', '', 102);
INSERT INTO `t_mode` VALUES (103, '3', '现金流量预警12', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB < 0', '经营活动和筹资活动产生的现金流出大于投资活动产生的现金流入，且投资活动的现金流入不具有可持续性，因此，建议管理层做好现金流管理，考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）延长还款期限或进行贷款置换，缓解前期还本付息压力。', '', '', '300001', '', 103);
INSERT INTO `t_mode` VALUES (104, '3', '现金流量预警13', 'XJLL_Y < 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB < 0', '现金及现金等价物净增加额为负数，主要是由于经营活动和投资活动现金流量净额为负数造成，企业现金流状况较差，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力。', '', '', '300001', '', 104);
INSERT INTO `t_mode` VALUES (105, '3', '现金流量预警14', 'XJLL_Y < 0 && XJLL_AM < 0 && XJLL_AZ < 0 && XJLL_BB < 0', '由于经营活动、投资活动及筹资活动产生的现金流量净额均为负数，企业现金流状况十分差，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 105);
INSERT INTO `t_mode` VALUES (106, '3', '现金流量预警15', 'XJLL_Y > 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB == 0', '即使经营活动现金流量净额为正且投资回收，但因大量归还筹资活动借入的款项，导致总体现金及现金等价物净增加额为0，建议管理层查看未来是否仍存在大量的归还筹资活动款项的支出，考虑对现金流的影响，避免资金链出现问题。', '', '', '300001', '', 106);
INSERT INTO `t_mode` VALUES (107, '3', '现金流量预警16', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB == 0', '即使经营活动现金流量净额为正且通过筹资获取资金，但本期现金及现金等价物净增加额仍不增不减，主要是由于投资活动的大量现金流出引起。建议管理层查看投资活动的必需性，削减不必要的投资，同时，考虑投资回报率，进行投资测算，对投资款项的支出进行严格监控。对于使用贷款进行的投资活动，需考虑贷款合同对贷款用途的限定，查看是否存在违规使用贷款的情况。', '', '', '300001', '', 107);
INSERT INTO `t_mode` VALUES (108, '3', '现金流量预警17', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ < 0 && XJLL_BB == 0', '最终现金及现金等价物净增加额为0说明经营活动产生的现金流刚好支撑投资及筹资活动所需要资金。建议管理层查看投资活动的必需性，削减不必要的投资，同时，考虑投资回报率，进行投资测算，对投资款项的支出进行严格监控。而且争取延长借款期限，缓解前期还本付息压力，或查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 108);
INSERT INTO `t_mode` VALUES (109, '3', '现金流量预警18', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ > 0 && XJLL_BB == 0', '即使投资活动与融资活动产生了正现金流，但本期现金及现金等价物净增加额仍为0，因此管理层需高度警惕，预防现金流不足对未来经营肯可能产生的影响。经营活动产生的现金流量净额为负数，反映企业经营不善，对未来进行贷款及信用评级等均有可能受到影响。', '', '', '300001', '', 109);
INSERT INTO `t_mode` VALUES (110, '3', '现金流量预警19', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB == 0', '经营活动和筹资活动产生的现金流出刚好等于投资活动产生的现金流入，且投资活动的现金流入不具有可持续性，因此，建议管理层做好现金流管理，考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）延长还款期限或进行贷款置换，缓解前期还本付息压力。', '', '', '300001', '', 110);
INSERT INTO `t_mode` VALUES (113, '3', '现金流量预警20', 'XJLL_Y < 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB == 0', '虽然融资额为正数，但现金及现金等价物净增加额不增不减，主要是由于经营活动和投资活动现金流量净额为负数造成，企业现金流状况较差，建议管理层考虑以下措施对现金流进行改善：1)对库存商品进行促销，增加收入，改善现金流入；2)加快应收款的催收，加速现金回笼；3)对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4)股东考虑进行增资缓解企业资金压力。', '', '', '300001', '', 113);
INSERT INTO `t_mode` VALUES (136, '2', '财务费用预警', 'LR_R1!=0&&LR_R>LR_R1', '财务费用本期比上年同期增长 {(LR_R-LR_R1)/LR_R1 *100}%。财务费用的增加，主要是因为本期贷款金额的增加。建议管理层结合资金情况，贷款情况，做好资金用途的管理，同时评估未来还款付息对资金流产生的压力，评估资金状况是否足以承受未来的还本付息所需的现金流。', '{(LR_R-LR_R1)/LR_R1 *100}', '', '20010', '', 136);
INSERT INTO `t_mode` VALUES (137, '2', '财务费用预警', 'LR_R1!=0&&LR_R-LR_R1<0', '财务费用本期比上年同期减少{(LR_R1-LR_R)/LR_R1 *100}%，本期财务费用的减少，主要是因为利息支出的减少。建议管理层结合贷款及现金流情况，考虑是否需要更新融资计划或进行增资，如需进行股权或债权融资，需考虑未来还本付息等对现金流的压力。', '{(LR_R1-LR_R)/LR_R1 *100}', '', '20010', '', 137);
INSERT INTO `t_mode` VALUES (138, '2', '投资收益预警', 'LR_U1!=0&&LR_U-LR_U1>0', '投资收益本期比上年同期增长 {(LR_U-LR_U1)/Math.abs(LR_U1) *100}%，本期投资收益有所增加。由于投资收益为非经常性收益，剔除投资收益后，营业利润将大幅度下降。建议管理层考虑投资收益的性质，具体分析其增加原因，减少投资收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_U-LR_U1)/Math.abs(LR_U1) *100}', '', '20011', '', 138);
INSERT INTO `t_mode` VALUES (139, '2', '投资收益预警', 'LR_U1!=0&&LR_U-LR_U1<0', '投资收益本期比上年同期减少 {(LR_U1-LR_U)/Math.abs(LR_U1) *100}%，本期投资收益大幅度下降，管理层需关注投资收益下降原因，审慎评估投资风险。由于投资收益为非经营性收益，剔除投资收益后，营业利润将大幅度下降。建议管理层考虑投资收益的性质，减少投资收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_U1-LR_U)/Math.abs(LR_U1) *100}', '', '20011', '', 139);
INSERT INTO `t_mode` VALUES (140, '2', '营业外收入预警', 'LR_Z1!=0&&LR_Z-LR_Z1>0', '营业外收入本期比上年同期增长{(LR_Z-LR_Z1)/LR_Z1 *100}%，由于营业外收入为非经营性收入，不具有持续性，在融资、上市等接受尽调或者审计时，均将作为模拟调整的对象，因此，建议管理层查看以前年度营业外收入的性质，并剔除历史数据中营业外收入对净利润的影响后，再分析净利润的变动原因。', '{(LR_Z-LR_Z1)/LR_Z1 *100}', '', '20012', '', 140);
INSERT INTO `t_mode` VALUES (141, '2', '营业外收入预警', 'LR_Z-LR_Z1<0', '营业外收入本期比上年同期减少{(LR_Z1-LR_Z)/LR_Z1 *100}%，营业外收入的减少，管理层需警惕。由于营业外收入非经营性收入，不具有持续性，在融资、上市等接受尽调或者审计时，均将作为模拟调整的对象，因此，建议管理层查看以前年度营业外收入的性质，考虑主营业务的发展是否足以支撑企业未来的需求。', '{(LR_Z1-LR_Z)/LR_Z1 *100}', '', '20012', '', 141);
INSERT INTO `t_mode` VALUES (142, '2', '营业外支出预警', 'LR_AB1!=0&&LR_AB-LR_AB1>0', '营业外支出本期比上年同期增长{(LR_AB-LR_AB1)/LR_AB1 *100}%，营业外支出有所增加，建议管理层关注是否发生了大额的资产处置损失，资产处置是否履行了审批制度并关注大额资产处置的原因。另外，营业外支出为非经营性支出，不具有持续性。建议管理层剔除两期营业外支出后，重新评估净利润的变动情况及趋势，并相应做出管理决策。', '{(LR_AB-LR_AB1)/LR_AB1 *100}', '', '20013', '', 142);
INSERT INTO `t_mode` VALUES (143, '2', '营业外支出预警', 'LR_AB-LR_AB1<0', '营业外支出本期比上年同期减少{(LR_AB1-LR_AB)/LR_AB1 *100}%,由于营业外支出为非经营性支出，不具有持续性。建议管理层剔除两期营业外支出后，重新评估净利润的变动情况及趋势，并相应做出管理决策。', '{(LR_AB1-LR_AB)/LR_AB1 *100}', '', '20013', '', 143);
INSERT INTO `t_mode` VALUES (144, '2', '税金及附加预警', 'LR_O1!=0&&LR_O-LR_O1>0', '税金及附加本期比上年同期增长{(LR_O-LR_O1)/LR_O1 *100}%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收政策变化、进一步核查本期可抵扣税额，查看是否存在税率调增、不再享有免税政策以及大量发票不可抵扣的情况，从而规范发票管理及排查税务风险。', '(LR_O-LR_O1)/LR_O1 *100}', '', '20014', '', 144);
INSERT INTO `t_mode` VALUES (145, '2', '税金及附加预警', 'LR_O-LR_O1<0', '税金及附加本期比上年同期减少{(LR_O1-LR_O)/LR_O1 *100}%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收是否存在税率调减、享有免税政策的情况，确保税负降低的合理性。', '{(LR_O1-LR_O)/LR_O1 *100}', '', '20014', '', 145);
INSERT INTO `t_mode` VALUES (146, '2', '资产减值损失预警', 'LR_S1!=0&&LR_S-LR_S1>0', '资产减值损失本期比上年同期增长{(LR_S-LR_S1)/LR_S1 *100}%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施减少损失，同时，特别警惕因技术变革、行业创新导致公司资产大幅度减值的情况。', '{(LR_S-LR_S1)/LR_S1 *100}', '', '20015', '', 146);
INSERT INTO `t_mode` VALUES (147, '2', '资产减值损失预警', 'LR_S-LR_S1<0', '资产减值损失本期比上年同期减少{(LR_S1-LR_S)/LR_S1 *100}%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施进一步降低损失，提升利润空间，同时，需防范因技术变革、行业创新初步导致公司资产减值的情形。', '{(LR_S1-LR_S)/LR_S1 *100}', '', '20015', '', 147);
INSERT INTO `t_mode` VALUES (148, '2', '公允价值变动收益预警', 'LR_T1!=0&&LR_T-LR_T1>0', '公允价值变动本期比上年同期增长{(LR_T-LR_T1)/Math.abs(LR_T1) *100}%，由于公允价值变动为非经常性收益，剔除后，营业利润将下降。建议管理层考虑公允价值变动的性质，具体分析其增加原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_T-LR_T1)/Math.abs(LR_T1) *100}', '', '20016', '', 148);
INSERT INTO `t_mode` VALUES (149, '2', '公允价值变动收益预警', 'LR_T1!=0&&LR_T-LR_T1<0', '公允价值变动本期比上年同期减少{(LR_T1-LR_T)/Math.abs(LR_T1) *100}%，本期公允价值变动大幅度下降，管理层需关注变动原因，评估现有投资风险。由于公允价值变动为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑公允价值变动的性质及原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_T1-LR_T)/Math.abs(LR_T1) *100}', '', '20016', '', 149);
INSERT INTO `t_mode` VALUES (150, '2', '所得税费用预警', 'LR_AE1!=0&&LR_AE>LR_AE1', '所得税费用本期比上年同期增长{(LR_AE-LR_AE1)/LR_AE1 *100}%，建议管理层关注所得税申报中不得抵扣项的原因及金额，考虑是否需要聘请专业团队为企业进行税收筹划，达到合理避税，增加净利润的目的。', '{(LR_AE-LR_AE1)/LR_AE1 *100}', '', '20017', '', 150);
INSERT INTO `t_mode` VALUES (151, '2', '所得税费用预警', 'LR_AE<LR_AE1', '所得税费用本期比上年同期减少{(LR_AE1-LR_AE)/LR_AE1 *100}%，所得税费用的大幅度降低属于非经常性情况，建议管理层关注减少的原因，是否有享受优惠政策，注意优惠政策的可持续性。', '{(LR_AE1-LR_AE)/LR_AE1 *100}', '', '20017', '', 151);
INSERT INTO `t_mode` VALUES (166, '3', '现金流量表概述', 'XJLL_BB > 0', '本期现金及现金等价物净增加额为正数，企业现金流处于正常水平，其中经营活动产生的现金流量净额占{XJLL_Y/XJLL_BB*100}%，投资活动产生的现金流量净额占{XJLL_AM/XJLL_BB*100}%，筹资活动产生的现金流量净额占{XJLL_AZ/XJLL_BB*100}%，汇率变动对现金及现金等价物的影响占{XJLL_BA/XJLL_BB*100}%。', '{XJLL_Y/XJLL_BB*100},{XJLL_AM/XJLL_BB*100},{XJLL_AZ/XJLL_BB*100},{XJLL_BA/XJLL_BB*100}', '', 'G30001', '', 166);
INSERT INTO `t_mode` VALUES (167, '3', '现金流量表概述', 'XJLL_BB==0', '本期现金及现金等价物净增加额为0，企业现金收支平衡，其中经营活动产生的现金流量净额为Rmb{XJLL_Y/10000}万元，投资活动产生的现金流量净额为Rmb{XJLL_AM/10000}万元，筹资活动产生的现金流量净额为Rmb{XJLL_AZ/10000}万元，汇率变动对现金及现金等价物的影响为Rmb{XJLL_BA/10000}万元。', '{XJLL_Y/10000},{XJLL_AM/10000},{XJLL_AZ/10000},{XJLL_BA/10000}', '', 'G30001', '', 167);
INSERT INTO `t_mode` VALUES (168, '3', '现金流量表概述', 'XJLL_BB < 0', '本期现金及现金等价物净增加额为负数，企业现金流收不抵支，其中经营活动产生的现金流量净额占{XJLL_Y/XJLL_BB*100}%，投资活动产生的现金流量净额占{XJLL_AM/XJLL_BB*100}%，筹资活动产生的现金流量净额占{XJLL_AZ/XJLL_BB*100}%，汇率变动对现金及现金等价物的影响占{XJLL_BA/XJLL_BB*100}%。', '{XJLL_Y/XJLL_BB*100},{XJLL_AM/XJLL_BB*100},{XJLL_AZ/XJLL_BB*100},{XJLL_BA/XJLL_BB*100}', '', 'G30001', '', 168);
