INSERT INTO `t_mode` VALUES (562, '1', '衍生金融资产概述', 'ZCFZ_E1!=0&&ZCFZ_E-ZCFZ_E1<0', '衍生金融资产从上年同期的Rmb{ZCFZ_E1/10000}万元减少至本期的Rmb{ZCFZ_E/10000}万元', '{ZCFZ_E1/10000},{ZCFZ_E/10000}', '', 'G1067', '', 562);
INSERT INTO `t_mode` VALUES (563, '1', '衍生金融资产概述', 'ZCFZ_E1!=0&&ZCFZ_E-ZCFZ_E1<0', '，降幅为{(ZCFZ_E1- ZCFZ_E)*100/ZCFZ_E1}%', '{(ZCFZ_E1- ZCFZ_E)*100/ZCFZ_E1}', '', 'G1067', '', 563);
INSERT INTO `t_mode` VALUES (603, '1', '应收利息持平', 'ZCFZ_L-ZCFZ_L1==0', '对于应收利息不变的情况，管理层需区分是因购买的债券余额和利率未变还是因本金已收回的债券的剩余利息未能回收导致的。若是未能回收的剩余利息，则需加强回收力度。', '', '', '10001', '', 603);
INSERT INTO `t_mode` VALUES (604, '1', '应收股利持平', 'ZCFZ_M-ZCFZ_M1==0', '对于应收股利不变的情况，管理层需区分是因每年分红不变还是因上期分红一直未收到导致的。若是未收到上期分红，则需重点关注未收到的原因，并分析长期股权投资的减值风险。', '', '', '10002', '', 604);
INSERT INTO `t_mode` VALUES (605, '1', '以公允价值计量且其变动计入当期损益的金融资产持平', 'ZCFZ_D==ZCFZ_D1', '无预警', '', '', '10003', '', 605);
INSERT INTO `t_mode` VALUES (606, '1', '一年内到期的非流动资产持平', 'ZCFZ_R1!=0&&ZCFZ_R-ZCFZ_R1==0', '与上期相比，本期一年内到期的非流动资产与上期余额一致，变动为0，管理层需对整个融资规划进行核查，评估融资结构是否有产生变化，同时结合生产运营及投资计划，评估贷款金额是否足以支撑企业正常运营，并相应进行资金规划，合理安排资金归还即将到期的长期借款。', '', '', '10004', '', 606);
INSERT INTO `t_mode` VALUES (607, '1', '持有待售的资产持平', 'ZCFZ_Q1!=0&&ZCFZ_Q-ZCFZ_Q1==0', '由于该科目核算类别较为特殊，针对该科目当期及上期余额不变的情况，建议管理层关注资产性质，核查项目类别，考虑是否需要对该科目核算下的资产进行清理，注意风险控制。', '', '', '10006', '', 607);
INSERT INTO `t_mode` VALUES (608, '1', '可供出售金融资产持平', 'ZCFZ_V1!=0&&ZCFZ_V-ZCFZ_V1==0', '由于可供出售金融资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额与上期无任何变动，管理层需连同财务部查找原因，同时需注意核算时点、计量金额是否符合会计准则要求。且需警惕因期末可供出售金融资产市场价值变动存在变现的不确定性。', '', '', '10007', '', 608);
INSERT INTO `t_mode` VALUES (609, '1', '持有至到期投资持平', 'ZCFZ_W1!=0&&ZCFZ_W-ZCFZ_W1==0', '建议管理层了解该科目的资产类别，合理规划资金使用及流转速度，并结合现金流情况，考虑是否需要对该类资产进行增持或减持。', '', '', '10008', '', 609);
INSERT INTO `t_mode` VALUES (610, '1', '固定资产持平', 'ZCFZ_AA1!=0&&ZCFZ_AA-ZCFZ_AA1==0', '与上期相比，本期固定资产余额与上期一致，变动为0，建议管理层核查固定资产结构，并结合未来生产经营规划及布局，考虑固定资产是否需要添置或清理。', '', '', '10009', '', 610);
INSERT INTO `t_mode` VALUES (611, '1', '在建工程持平', 'ZCFZ_AB1!=0&&ZCFZ_AB-ZCFZ_AB1==0', '与上期相比，本期在建工程余额与上期一致，变动为0，此情况较为特殊，建议管理层与财务部核查余额是否正确，如无误，则需核查工程停滞的原因，并分析工程停滞对生产经营规划的影响，及早做出相应应对措施。', '', '', '10010', '', 611);
INSERT INTO `t_mode` VALUES (612, '1', '长期应收款持平', 'ZCFZ_X-ZCFZ_X1==0', '无预警。', '', '', '10011', '', 612);
INSERT INTO `t_mode` VALUES (613, '1', '长期股权投资持平', 'ZCFZ_Y-ZCFZ_Y1==0', '无预警。', '', '', '10012', '', 613);
INSERT INTO `t_mode` VALUES (614, '1', '投资性房地产持平', 'ZCFZ_Z1!=0&&ZCFZ_Z-ZCFZ_Z1==0', '由于投资性房地产核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，建议管理层在确保余额正确的情况下，结合企业生产经营布局及规划，评估继续持有或减持该类资产对企业可能产生的影响。', '', '', '10013', '', 614);
INSERT INTO `t_mode` VALUES (615, '1', '工程物资持平', 'ZCFZ_AC1!=0&&ZCFZ_AC-ZCFZ_AC1==0', '与上期相比，本期工程物资与上期余额一致，变动为0，建议管理层查看工程物资是否存在囤积或与相关工程所需不匹配的情况，对长期未领用或不适合工程所需的工程物资进行清理，结合工程建设计划，合理规划工程物资的采购及领用。', '', '', '10014', '', 615);
INSERT INTO `t_mode` VALUES (616, '1', '固定资产清理持平', 'ZCFZ_AD==ZCFZ_AD1', '无预警。', '', '', '10015', '', 616);
INSERT INTO `t_mode` VALUES (617, '1', '无形资产持平', 'ZCFZ_AG1!=0&&ZCFZ_AG-ZCFZ_AG1==0', '与上期相比，本期无形资产余额与上期一致，变动为0，此情况较为特殊，建议管理层在确保余额正确的情况下，分析无形资产构成，针对本期新增无形资产，查看其金额核算是否正确，是否符合会计准则对于无形资产确定的要求。', '', '', '10016', '', 617);
INSERT INTO `t_mode` VALUES (618, '1', '开发支出持平', 'ZCFZ_AH1!=0&&ZCFZ_AH-ZCFZ_AH1==0', '与上期相比，本期开发支出余额与上期一致，变动为0，此情况较为特殊，建议管理层在确保余额正确的情况下，分析开发支出构成，并核查开发支出的确认是否符合会计准则对于无形资产确定的要求。', '', '', '10017', '', 618);
INSERT INTO `t_mode` VALUES (619, '1', '商誉持平', 'ZCFZ_AI-ZCFZ_AI1==0', '无预警。', '', '', '10018', '', 619);
INSERT INTO `t_mode` VALUES (620, '1', '长期待摊费用持平', 'ZCFZ_AJ1!=0&&ZCFZ_AJ-ZCFZ_AJ1==0', '与上期相比，本期长期待摊费用与上期余额一致，变动为0，建议管理层在确保余额正确的情况下，核查长期待摊费用的构成，评估科目设置及核算是否符合会计准则的要求。对于本期计入的长期待摊费用，核查其金额正确性。', '', '', '10019', '', 620);
INSERT INTO `t_mode` VALUES (621, '1', '递延所得税资产持平', 'ZCFZ_AK1!=0&&ZCFZ_AK-ZCFZ_AK1==0', '递延所得税资产的产生，是因为资产的账面价值大于计税基础，或负债的账面价值小于计税基础，导致会计确认的所得税小于税法确认的所得税，从而产生递延所得税资产。递延所得税资产不变，需关注其确认条件、计量金额是否符合会计准则。建议管理层使用在线顾问模块中的专项顾问功能，为企业进行整体税收筹划，进行合理避税，减少企业利润不必要的损耗。同时，建议管理层检查是否已按要求设立备查薄。', '', '', '10020', '', 621);
INSERT INTO `t_mode` VALUES (622, '1', '其他非流动资产持平', 'ZCFZ_AL-ZCFZ_AL1==0', '无预警。', '', '', '10021', '', 622);
INSERT INTO `t_mode` VALUES (624, '1', '短期借款持平', 'ZCFZ_AO1!=0&&ZCFZ_AO-ZCFZ_AO1==0', '与上期相比，本期短期借款余额与上期保持一致，变动为0，建议管理层在确保余额核算无误的情况下，根据企业未来生产经营计划及融资规划，结合现金流情况，合理安排资金筹措及归还，避免出现资金紧张的情况。此外，管理层可考虑使用票据作为短期融资的途径，开拓不同类型的资金筹措方式，盘活现金流。', '', '', '10023', '', 624);
INSERT INTO `t_mode` VALUES (625, '1', '一年内到期的非流动负债持平', 'ZCFZ_BJ-ZCFZ_BJ1==0', '由于一年内到期的非流动负债主要为一年内到期的长期借款等，对于企业来说，由于之前的资金需求产生的贷款在近期内需进行偿还，因此需分析资金状况在未来一年内是否可以满足其偿还需求。若资金紧张，则需考虑通过借款、延长支付期限等方式缓解资金压力。', '', '', '10025', '', 625);
INSERT INTO `t_mode` VALUES (626, '1', '应付职工薪酬持平', 'ZCFZ_AZ-ZCFZ_AZ1==0', '无预警。', '', '', '10026', '', 626);
INSERT INTO `t_mode` VALUES (627, '1', '应交税费持平', 'ZCFZ_BA==ZCFZ_BA1', '与上期相比，本期应交税费余额与上期一致，变动为0，此情况较为特殊，建议管理层在确保余额正确的情况下，与财务部查看应交税费与收入的比例是否正常，此外，针对本期与上期应交税费一致的情况，建议管理层查看有无应缴未缴之税费，评估由此可能产生的滞纳金，行政处分等风险及影响。', '', '', '10027', '', 627);
INSERT INTO `t_mode` VALUES (628, '1', '其他流动负债上期为0的变动', 'ZCFZ_BK1==0&&ZCFZ_BK-ZCFZ_BK1>0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10030', '', 628);
INSERT INTO `t_mode` VALUES (629, '1', '长期借款持平', 'ZCFZ_BM1!=0&&ZCFZ_BM-ZCFZ_BM1==0', '与上期相比，本期长期借款余额与上期保持一致，变动为0，建议管理层在确保余额核算无误的情况下，根据企业未来生产经营计划及融资规划，结合现金流情况，合理安排资金筹措及归还，避免出现资金紧张的情况。', '', '', '10031', '', 629);
INSERT INTO `t_mode` VALUES (630, '1', '应付债券持平', 'ZCFZ_BN-ZCFZ_BN1==0', '无预警。', '', '', '10032', '', 630);
INSERT INTO `t_mode` VALUES (631, '1', '递延所得税负债持平', 'ZCFZ_BV-ZCFZ_BV1==0', '递延所得税负债的产生，是因为资产的账面价值小于计税基础，或负债的账面价值大于计税基础，而导致会计确认的所得税大于税法确认的所得税，从而产生递延所得税负债。建议管理层关注其确认条件、计量金额是否符合会计准则。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10036', '', 631);
INSERT INTO `t_mode` VALUES (632, '1', '其他非流动负债上期为0的情况', 'ZCFZ_BW1==0&&ZCFZ_BW!=0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', '', '', '10037', '', 632);
INSERT INTO `t_mode` VALUES (633, '1', '其他非流动负债变动在正负0.2以内', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1+0.2>0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1-0.2<0', '无预警。', '', '', '10037', '', 633);
INSERT INTO `t_mode` VALUES (634, '1', '递延收益持平', 'ZCFZ_BU-ZCFZ_BU1==0', '递延收益科目较为特殊，建议管理层关注其产生的原因及核算是否符合会计准则的要求，尤其是针对政府补贴产生的递延收益，管理层需重点关注补贴收入实现的相关条件，确保项目的开展符合政府相关规定。', '', '', '10038', '', 634);
INSERT INTO `t_mode` VALUES (635, '1', '长期应付职工薪酬', 'ZCFZ_BR==ZCFZ_BR1', '无预警。', '', '', '10039', '', 635);
INSERT INTO `t_mode` VALUES (636, '1', '实收资本持平', 'ZCFZ_BZ==ZCFZ_BZ1', '无', '', '', '10040', '', 636);
INSERT INTO `t_mode` VALUES (637, '1', '资本公积持平', 'ZCFZ_CD-ZCFZ_CD1==0', '无预警。', '', '', '10041', '', 637);
INSERT INTO `t_mode` VALUES (638, '1', '盈余公积持平', 'ZCFZ_CH==ZCFZ_CH1', '根据公司法的规定，公司分配当年税后利润时，应当提取利润的百分之十列入公司法定公积金。公司法定公积金累计额为公司注册资本的百分之五十以上的，可以不再提取。 \r\n公司从税后利润中提取法定公积金后，经股东会或者股东大会决议，还可以从税后利润中提取任意公积金。建议管理层结合CFO系统分析模块中年度净利润的情况，结合上述条款，查看企业是否已按公司法规定对盈余公积进行计提，对未按规定计提的，及时进行调整。', '', '', '10042', '', 638);
INSERT INTO `t_mode` VALUES (639, '1', '未分配利润持平', 'ZCFZ_CJ-ZCFZ_CJ1==0', '与上期相比，本期未分配利润与上期一致，变动为0，此情况较为特殊。建议管理层结合本期净利润及利润分配的情况，查看金额是否正确。', '', '', '10043', '', 639);
INSERT INTO `t_mode` VALUES (640, '1', '衍生金融资产变动', 'ZCFZ_E!=ZCFZ_E1', '无预警。', NULL, NULL, '50001', NULL, 640);
INSERT INTO `t_mode` VALUES (641, '1', '生产性生物资产变动', 'ZCFZ_AE>ZCFZ_AE1||ZCFZ_AE<ZCFZ_AE1', '无预警。', '', '', '50002', '', 641);
INSERT INTO `t_mode` VALUES (642, '1', '油气资产变动', 'ZCFZ_AF-ZCFZ_AF1>0||ZCFZ_AF-ZCFZ_AF1<0', '无预警。', '', '', '50003', '', 642);
INSERT INTO `t_mode` VALUES (643, '1', '以公允价值计量且其变动计入当期损益的金融负债增加', 'ZCFZ_AS-ZCFZ_AS1>0', '由于以公允价值计量且其变动计入当期损益的金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', '', '50004', '', 643);
INSERT INTO `t_mode` VALUES (644, '1', '以公允价值计量且其变动计入当期损益的金融负债减少', 'ZCFZ_AS-ZCFZ_AS1<0', '由于以公允价值计量且其变动计入当期损益的金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', '', '50004', '', 644);
INSERT INTO `t_mode` VALUES (645, '1', '以公允价值计量且其变动计入当期损益的金融负债持平', 'ZCFZ_AS-ZCFZ_AS1==0', '由于以公允价值计量且其变动计入当期损益的金融负债核算的类别较为特殊，且此类负债为非经营类负债，建议管理层在确保余额无误的情况下，结合市场情况，评估该类负债未来的市场价值变动对企业可能产生的影响，针对余额不变的类别，考虑是否需要进行清理等。', '', '', '50004', '', 645);
INSERT INTO `t_mode` VALUES (647, '1', '衍生金融负债增加', 'ZCFZ_AT-ZCFZ_AT1>0', '由于衍生金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', '', '50005', '', 647);
INSERT INTO `t_mode` VALUES (648, '1', '衍生金融负债减少', 'ZCFZ_AT-ZCFZ_AT1<0', '由于衍生金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', '', '50005', '', 648);
INSERT INTO `t_mode` VALUES (649, '1', '衍生金融负债不变', 'ZCFZ_AT-ZCFZ_AT1==0', '由于衍生金融负债核算的类别较为特殊，且此类负债为非经营类负债，建议管理层在确保余额无误的情况下，结合市场情况，评估该类负债未来的市场价值变动对企业可能产生的影响，针对余额不变的类别，考虑是否需要进行清理等。', '', '', '50005', '', 649);
INSERT INTO `t_mode` VALUES (650, '1', '预计负债增加', 'ZCFZ_BT-ZCFZ_BT1>0', '预计负债增加，企业需提高警惕，关于增加的原因。同时由于预计负债的特殊性，建议管理层针对预计负债专门进行实现程度的可能性分析，针对风险较高，较可能需要实际支付的预计负债，除考虑对现金流的影响外，还要考虑负债产生同时可能伴随的法律责任或风险，以及如未能承担负债偿还的情况下可能产生的法律责任及风险。尤其在股权转让中，受让方更应重视目标公司的预计负债问题。当发生债务追索时，将严重影响受让方的股份转让合同的利益和预期的收益。预计债务的承担问题建议列入风险负担条款在股权转让合同中予以约定。同时注意股权的转移并不影响到追索的对象，受让方在成为目标公司股东后，目标公司仍需对外承担相应责任，受让方再根据股权转让合同向出让方追偿。', '', '', '50006', '', 650);
INSERT INTO `t_mode` VALUES (651, '1', '预计负债减少', 'ZCFZ_BT-ZCFZ_BT1<0', '预计负债有所减少，需关注已支付负债的原因及数值，同时评估企业现有资金情况。同时由于预计负债的特殊性，建议管理层针对剩余预计负债专门进行实现程度的可能性分析，针对风险较高，较可能需要实际支付的预计负债，除考虑对现金流的影响外，还要考虑负债产生同时可能伴随的法律责任或风险，以及如未能承担负债偿还的情况下可能产生的法律责任及风险。尤其在股权转让中，受让方更应重视目标公司的预计负债问题。当发生债务追索时，将严重影响受让方的股份转让合同的利益和预期的收益。预计债务的承担问题建议列入风险负担条款在股权转让合同中予以约定。同时注意股权的转移并不影响到追索的对象，受让方在成为目标公司股东后，目标公司仍需对外承担相应责任，受让方再根据股权转让合同向出让方追偿。', '', '', '50006', '', 651);
INSERT INTO `t_mode` VALUES (652, '1', '预计负债持平', 'ZCFZ_BT-ZCFZ_BT1==0', '预计负债科目较为特殊，建议管理层针对预计负债专门进行实现程度的可能性分析，针对风险较高，较可能需要实际支付的预计负债，除考虑对现金流的影响外，还要考虑负债产生同时可能伴随的法律责任或风险，以及如未能承担负债偿还的情况下可能产生的法律责任及风险。尤其在股权转让中，受让方更应重视目标公司的预计负债问题。当发生债务追索时，将严重影响受让方的股份转让合同的利益和预期的收益。预计债务的承担问题建议列入风险负担条款在股权转让合同中予以约定。同时注意股权的转移并不影响到追索的对象，受让方在成为目标公司股东后，目标公司仍需对外承担相应责任，受让方再根据股权转让合同向出让方追偿。', '', '', '50006', '', 652);
INSERT INTO `t_mode` VALUES (653, '3', '现金流量表1.1', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AZ<0&&XJLL_AM-XJLL_AZ<0', '本期现金及现金等价物的增长主要靠筹资活动的现金流带动，经营活动产生的现金流非主要增长来源，管理层需警惕非经营性活动产生的现金流入的可持续性，同时，需加强经营活动现金流的管理，使现金流更健康。', '', '', '300001', '', 653);
INSERT INTO `t_mode` VALUES (654, '3', '现金流量表1.2', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AM<0&&XJLL_AZ-XJLL_AM<0', '本期现金及现金等价物的增长主要靠投资活动的现金流带动，经营活动产生的现金流非主要增长来源，管理层需警惕非经营性活动产生的现金流入的可持续性，同时，需加强经营活动现金流的管理，使现金流更健康。', '', '', '300001', '', 654);
INSERT INTO `t_mode` VALUES (655, '3', '现金流量表1.3', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AM>0&&XJLL_Y-XJLL_AZ>0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 655);
INSERT INTO `t_mode` VALUES (656, '3', '现金流量表1.4', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AM<0&&XJLL_AM-XJLL_AZ==0', '本期现金及现金等价物的增长主要靠投资活动及筹资活动的现金流带动，经营活动产生的现金流非主要增长来源，管理层需警惕非经营性活动产生的现金流入的可持续性，同时，需加强经营活动现金流的管理，使现金流更健康。', '', '', '300001', '', 656);
INSERT INTO `t_mode` VALUES (657, '3', '现金流量表1.5', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AZ==0&&XJLL_Y-XJLL_AM>0', '本期现金及现金等价物的增长主要靠经营活动及筹资活动产生的现金流带动，管理层需警惕筹资活动对现金流的影响是否将逐渐增大，关注未来的还本付息压力，同时考虑是否需要调整资金结构，从而达到增大经营活动现金流入的目的，使企业发展更为健康。', '', '', '300001', '', 657);
INSERT INTO `t_mode` VALUES (658, '3', '现金流量表1.6', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AM==0&&XJLL_Y-XJLL_AZ>0', '本期现金及现金等价物的增长主要靠经营活动及投资活动产生的现金流带动，管理层需警惕投资活动对现金流的影响是否将逐渐增大，并考虑是否需要调整资金结构，从而达到增大经营活动现金流入的目的，使企业发展更为健康。', '', '', '300001', '', 658);
INSERT INTO `t_mode` VALUES (659, '3', '现金流量表1.7', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AM==0&&XJLL_Y-XJLL_AZ==0', '本期现金及现金等价物的增长主要靠经营活动、投资活动及筹资活动产生的现金流带动，管理层需警惕非经营性活动产生的现金流入的可持续性及对净现金流的影响是否逐渐增大，关注投资效益及未来的还本付息压力，同时，需加强经营活动现金流的管理，使现金流更健康。', '', '', '300001', '', 659);
INSERT INTO `t_mode` VALUES (660, '3', '现金流量表2.1', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ<0&&XJLL_BB>0&&XJLL_Y-XJLL_AM<0', '本期现金及现金等价物的增长主要靠投资活动产生的现金流带动，经营活动产生的现金流非主要增长来源，管理层需警惕非经营性活动产生的现金流入的可持续性，同时，需加强经营活动现金流的管理，使现金流更健康。', '', '', '300001', '', 660);
INSERT INTO `t_mode` VALUES (661, '3', '现金流量表2.3', 'XJLL_Y>0&&XJLL_AM>0&&XJLL_AZ<0&&XJLL_BB>0&&XJLL_Y-XJLL_AM==0', '企业本期现金流由良好的经营活动支撑，但管理层需警惕投资活动对现金流的影响是否将逐渐增大，并考虑是否需要调整资金结构，从而达到增大经营活动现金流入的目的，使企业发展更为健康。', '', '', '300001', '', 661);
INSERT INTO `t_mode` VALUES (662, '3', '现金流量3.3', 'XJLL_Y>0&&XJLL_AM<0&&XJLL_AZ>0&&XJLL_BB>0&&XJLL_Y-XJLL_AZ==0', '筹资活动产生的现金流为企业现金流的重要支撑，管理层需警惕未来资金筹措是否将存在风险，从而导致影响企业现金流的健康发展。此外，筹资活动产生的现金流对企业现金流影响较大，管理层需高度警惕，尽量维持经营活动现金流对现金流量的良性引导，避免生产经营过于依赖筹资活动。', '', '', '300001', '', 662);
INSERT INTO `t_mode` VALUES (663, '3', '现金流量预警21', 'XJLL_Y == 0 && XJLL_AM > 0 && XJLL_AZ > 0 && XJLL_BB > 0', '尽管企业最终现金及现金等价物净增加额为正数，本期现金及现金等价物的增长完全依靠投资活动及筹资活动产生的现金流带动，经营活动产生的现金流为0，证明企业生产经营已处于危险状态，主要收入来源及现金流已非经营活动产生，对于投资者而言，释放危险信号，不利于企业未来融资规划及发展，建议管理层认真了解经营活动现金流量净额为0的原因，努力提高生产效率，降低成本，对业务板块或发展规划等进行重新调整，使企业尽快扭转经营活动现金流的不利状态。', '', '', '300001', '', 663);
INSERT INTO `t_mode` VALUES (664, '3', '现金流量预警22', 'XJLL_Y == 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB > 0', '尽管企业最终现金及现金等价物净增加额为正数，本期现金及现金等价物的增长完全依靠投资活动的现金流带动，经营活动产生的现金流为0，证明企业生产经营已处于危险状态，主要收入来源及现金流已非经营活动产生，对于投资者而言，释放危险信号，不利于企业未来融资规划及发展。同时，筹资活动产生的现金流量净额已为负数，企业存在巨大的资金链断裂的风险，建议管理层认真了解经营活动现金流量净额为0的原因，努力提高生产效率，降低成本，对业务板块或发展规划等进行重新调整，使企业尽快扭转经营活动现金流的不利状态。', '', '', '300001', '', 664);
INSERT INTO `t_mode` VALUES (666, '2', '财务费用预警', 'LR_R1!=0&&LR_R==LR_R1', '与上年同期相比，本期财务费用金额与上期一致，此情况较为特殊，建议管理层：1）与财务人员进行核查，确认金额是否正确；2）如金额无误，建议管理层查看本期及上期财务费用与长短期贷款，票据等各项融资措施的匹配关系，考虑比例是否正常；3）建议管理层可使用票据等作为短期融资途径，并积极开拓多种融资渠道，降低融资成本。', '', '', '20010', '', 666);
INSERT INTO `t_mode` VALUES (667, '2', '投资收益预警', 'LR_U-LR_U1==0', '无预警。', '', '', '20011', '', 667);
INSERT INTO `t_mode` VALUES (668, '2', '营业外收入预警', 'LR_Z-LR_Z1==0', '无预警。', '', '', '20012', '', 668);
INSERT INTO `t_mode` VALUES (669, '2', '营业外支出持平', 'LR_AB-LR_AB1==0', '无预警。', '', '', '20013', '', 669);
INSERT INTO `t_mode` VALUES (670, '2', '税金及附加预警', 'LR_O-LR_O1==0', '无预警。', '', '', '20014', '', 670);
INSERT INTO `t_mode` VALUES (671, '2', '资产减值损失预警', 'LR_S-LR_S1==0', '无预警。', '', '', '20015', '', 671);
INSERT INTO `t_mode` VALUES (672, '2', '公允价值变动收益预警', 'LR_T-LR_T1==0', '无预警。', '', '', '20016', '', 672);
INSERT INTO `t_mode` VALUES (673, '2', '所得税费用预警', 'LR_AE1!=0&&LR_AE==LR_AE1', '与上期相比，本期管理费用金额与上期一致，此情况较为特殊，建议管理层：1）与财务人员进行核查，确认金额是否正确；2）如金额无误，查看本期所得税费用与营业收入的占比关系，可考虑使用CFO系统中的咨询模块，聘请专业顾问进行税收筹划，合理避税，降低税赋成本。', '', '', '20017', '', 673);
INSERT INTO `t_mode` VALUES (674, '2', '其他收益预警', 'LR_X1!=0&&LR_X-LR_X1>0', '其他收益本期比上年同期增长{(LR_X-LR_X1)/Math.abs(LR_X1)*100}%，本期其他收益有所增加。由于其他收益为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑其他收益的性质，具体分析其增加原因，减少其他收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_X-LR_X1)/Math.abs(LR_X1)*100}', '', '50010', '', 674);
INSERT INTO `t_mode` VALUES (675, '2', '其他收益预警', 'LR_X1!=0&&LR_X-LR_X1<0', '其他收益本期比上年同期减少{(LR_X1-LR_X)/Math.abs(LR_X1)*100}%，本期其他收益有所下降。由于其他收益为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑其他收益的性质，具体分析其减少原因，减少其他收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_X1-LR_X)/Math.abs(LR_X1)*100}', '', '50010', '', 675);
INSERT INTO `t_mode` VALUES (676, '2', '其他收益预警', 'LR_X-LR_X1==0', '无预警。', '', '', '50010', '', 676);
INSERT INTO `t_mode` VALUES (677, '3', '现金流量预警23', 'XJLL_Y == 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB > 0', '企业现金流完全靠投资活动产生的现金流来支撑，整个企业已经处于资金链可能断裂以及生产经营可能存在巨大困难的状态，建议管理层调整发展规划，在开源节流的同时，考虑是否需要调整产品结构或销售布局及策略等，尽快扭转现金流的不健康状态。', '', '', '300001', '', 677);
INSERT INTO `t_mode` VALUES (678, '3', '现金流量预警24.1', 'XJLL_Y > 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB > 0 && XJLL_Y - XJLL_AM< 0', '本期现金及现金等价物的增长主要靠投资活动的现金流带动，经营活动产生的现金流非主要增长来源，管理层需警惕非经营性活动产生的现金流入的可持续性，同时，需加强经营活动现金流的管理，考虑筹资活动可能为企业带来的正向现金流，评估企业是否存在融资空间，并评估股权融资或债权融资的必要性，使现金流更健康。', '', '', '300001', '', 678);
INSERT INTO `t_mode` VALUES (679, '3', '现金流量预警24.2', 'XJLL_Y > 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB > 0 && XJLL_Y - XJLL_AM>0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 679);
INSERT INTO `t_mode` VALUES (680, '3', '现金流量预警25', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ == 0 && XJLL_BB > 0', '企业本期现金流由良好的经营活动支撑，然而，现金流完全由经营活动支撑，可能存在资金链断链的风险，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，针对不良投资项目，考虑止血出售。', '', '', '300001', '', 680);
INSERT INTO `t_mode` VALUES (681, '3', '现金流量预警26', 'XJLL_Y > 0 && XJLL_AM == 0 && XJLL_AZ > 0 && XJLL_BB > 0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑加大效益高项目的投资。', '', '', '300001', '', 681);
INSERT INTO `t_mode` VALUES (682, '3', '现金流量预警27', 'XJLL_Y > 0 && XJLL_AM == 0 && XJLL_AZ < 0 && XJLL_BB > 0', '即使经营活动现金流量净额为正，但因大量归还筹资活动借入的款项，未来可能出现现金流紧张的情况，建议管理层查看未来是否仍存在大量的归还筹资活动款项的支出，合理规划资金使用，考虑对现金流的影响，避免资金链出现问题。', '', '', '300001', '', 682);
INSERT INTO `t_mode` VALUES (683, '3', '现金流量预警28', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB > 0', '由于经营活动的现金流量净额为负数，但最终的现金及现金等价物净增加额为正数，说明企业的现金流实际上是依靠投资活动产生，并非健康的现金流状况。建议管理层做好现金流管理，查看经营活动现金流为负数的主要原因。同时，可考虑进行合理的债权或股权融资，增加现金流，使企业能更加快速健康的发展。', '', '', '300001', '', 683);
INSERT INTO `t_mode` VALUES (684, '3', '现金流量预警29', 'XJLL_Y < 0 && XJLL_AM == 0 && XJLL_AZ > 0 && XJLL_BB > 0', '由于经营活动的现金流量净额为负数，但最终的现金及现金等价物净增加额为正数，说明企业的现金流实际上是依靠筹资活动产生，并非健康的现金流状况。建议管理层做好现金流管理，查看经营活动现金流为负数的主要原因。同时，合理规划筹资活动产生的现金流的使用及未来归还规划，避免产生资金链断裂的可能，使企业发展更为健康。', '', '', '300001', '', 684);
INSERT INTO `t_mode` VALUES (685, '3', '现金流量预警30', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ == 0 && XJLL_BB < 0', '尽管经营活动产生的现金流为正数，企业生产经营运作较为正常，然而最终的现金及现金等价物为负数，企业生产活动产生的现金流全部被投资活动所消耗掉，管理层需警惕出现资金链断裂的可能。建议管理层分析投资可行性，考虑是否需要调整投资策略。', '', '', '300001', '', 685);
INSERT INTO `t_mode` VALUES (686, '3', '现金流量预警31', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB < 0', '即使投资活动产生了正现金流，但本期现金及现金等价物净增加额为负，经营活动的负现金流说明企业生产运营存在较大问题，管理层需高度警惕，预防现金流不足对未来经营肯可能产生的影响。经营活动产生的现金流量净额为负数，反映企业经营不善，对未来进行贷款及信用评级等均有可能受到影响。建议管理层考虑通过股权融资等方式增加现金流入，预防资金链断裂。', '', '', '300001', '', 686);
INSERT INTO `t_mode` VALUES (687, '3', '现金流量预警32', 'XJLL_Y == 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB < 0', '本期经营活动产生的现金流量净额为0，企业经营可能存在问题，同时，投资活动产生的正向现金流完全被筹资活动所消耗，导致期末现金及现金等价物为负数，说明企业正在大笔偿还银行贷款。建议管理层查看银行还贷情况，评估未来偿贷所需资金对生产经营可能产生的影响，合理分配规划资金利用。', '', '', '300001', '', 687);
INSERT INTO `t_mode` VALUES (688, '3', '现金流量预警33', 'XJLL_Y == 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB < 0', '本期经营活动产生的现金流量净额为0，企业经营可能存在问题，同时，筹资活动产生的正向现金流完全被投资活动所消耗，导致期末现金及现金等价物为负数，企业完全依靠融资支撑现金流，管理层需高度重视到期无法偿还贷款的风险。建议管理层在合理开源节流，引导生产经营良性发展的同时，评估投资风险及可行性等，考虑是否需要调整投资策略。', '', '', '300001', '', 688);
INSERT INTO `t_mode` VALUES (689, '3', '现金流量预警34', 'XJLL_Y > 0 && XJLL_AM == 0 && XJLL_AZ < 0 && XJLL_BB < 0', '尽管经营活动产生的现金流为正数，企业生产经营运作较为正常，然而最终的现金及现金等价物为负数，企业生产活动产生的现金流全部被筹资活动所消耗掉，管理层需警惕出现资金链断裂的可能。建议管理层查看贷款到期情况，合理进行资金规划及筹措，使现金流更为健康。', '', '', '300001', '', 689);
INSERT INTO `t_mode` VALUES (690, '3', '现金流量预警35', 'XJLL_Y < 0 && XJLL_AM == 0 && XJLL_AZ > 0 && XJLL_BB < 0', '即使筹资活动产生了正现金流，但本期现金及现金等价物净增加额为负，经营活动的负现金流说明企业生产运营存在较大问题，管理层需高度警惕，预防现金流不足对未来经营肯可能产生的影响。经营活动产生的现金流量净额为负数，反映企业经营不善，对未来进行贷款及信用评级等均有可能受到影响。建议管理层考虑通过股权融资等方式增加现金流入，预防资金链断裂，同时需合理规划贷款归还所需资金，避免出现资金紧张的情况。', '', '', '300001', '', 690);
INSERT INTO `t_mode` VALUES (691, '3', '现金流量预警36', 'XJLL_Y == 0 && XJLL_AM < 0 && XJLL_AZ < 0 && XJLL_BB < 0', '投资活动及筹资活动产生的现金流量净额均为负数，经营活动现金流量净额则为0，企业现金流状况十分差，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 691);
INSERT INTO `t_mode` VALUES (692, '3', '现金流量预警37', 'XJLL_Y < 0 && XJLL_AM == 0 && XJLL_AZ < 0 && XJLL_BB < 0', '经营活动及筹资活动产生的现金流量净额均为负数，投资活动现金流量净额则为0，企业现金流状况十分差，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 692);
INSERT INTO `t_mode` VALUES (693, '3', '现金流量预警38', 'XJLL_Y < 0 && XJLL_AM < 0 && XJLL_AZ== 0 && XJLL_BB < 0', '经营活动及投资活动产生的现金流量净额均为负数，筹资活动现金流量净额则为0，企业现金流状况十分差，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力；6）评估投资风险及可行性等，考虑是否需要调整投资策略，在必要情况下，对部分亏损投资进行止损处理。', '', '', '300001', '', 693);
INSERT INTO `t_mode` VALUES (694, '3', '现金流量预警39', 'XJLL_Y == 0 && XJLL_AM > 0 && XJLL_AZ < 0 && XJLL_BB == 0', '企业经营活动产生的现金流量净额为0，证明企业生产运作处于较危险状态，建议管理层考虑是否需要调整生产经营策略，清理库存，通过加快催收应收款项，与供应商针对数期进行谈判等方式，改善企业经营活动现金流。此外，筹资活动现金流量净额为负数，企业可能正在大量偿还贷款，建议管理层查看贷款到期情况，对资金进行合理规划，避免出现资金链断链的可能。', '', '', '300001', '', 694);
INSERT INTO `t_mode` VALUES (695, '3', '现金流量预警40', 'XJLL_Y == 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB == 0', '企业经营活动产生的现金流量净额为0，证明企业生产运作处于较危险状态，建议管理层考虑是否需要调整生产经营策略，清理库存，通过加快催收应收款项，与供应商针对数期进行谈判等方式，改善企业经营活动现金流。此外，期末现金及现金等价物净增加额为0，企业依靠债权及股权融资借入的款项完全被投资活动所消耗，建议管理层评估投资风险及项目投资可行性及必要性，考虑是否需要调整投资策略。', '', '', '300001', '', 695);
INSERT INTO `t_mode` VALUES (696, '3', '现金流量预警41', 'XJLL_Y > 0 && XJLL_AM < 0 && XJLL_AZ == 0 && XJLL_BB == 0', '尽管企业经营活动产生的现金流量净额为正数，生产经营状况良好，然而，期末现金及现金等价物净增加额为0，经营活动产生的正向现金流均被投资活动所消耗，建议管理层评估投资风险及项目投资可行性及必要性，考虑是否需要调整投资策略。此外，建议管理层通过以下方式增大筹资活动产生的现金流，舒缓目前现金流的紧张状态：1）股东考虑进行增资缓解企业资金压力；2）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 696);
INSERT INTO `t_mode` VALUES (697, '3', '现金流量预警42', 'XJLL_Y < 0 && XJLL_AM > 0 && XJLL_AZ == 0 && XJLL_BB == 0', '经营活动现金流量净额为负数，企业现金流状况十分差，此外，企业整个现金流由投资活动支撑，现金流处于不健康状态，建议管理层考虑以下措施对现金流进行改善：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 697);
INSERT INTO `t_mode` VALUES (698, '3', '现金流量预警43', 'XJLL_Y > 0 && XJLL_AM == 0 && XJLL_AZ < 0 && XJLL_BB == 0', '尽管经营活动产生的现金流为正数，企业生产经营运作较为正常，然而最终的现金及现金等价物为0，企业生产活动产生的现金流全部被筹资活动所消耗掉，管理层需警惕出现资金链断裂的可能。建议管理层查看贷款到期情况，合理进行资金规划及筹措，使现金流更为健康。', '', '', '300001', '', 698);
INSERT INTO `t_mode` VALUES (699, '3', '现金流量预警44', 'XJLL_Y < 0 && XJLL_AM == 0 && XJLL_AZ > 0 && XJLL_BB == 0', '即使筹资活动产生了正现金流，但本期现金及现金等价物净增加额为0，经营活动的负现金流说明企业生产运营存在较大问题，管理层需高度警惕，预防现金流不足对未来经营肯可能产生的影响。经营活动产生的现金流量净额为负数，反映企业经营不善，对未来进行贷款及信用评级等均有可能受到影响。建议管理层考虑通过股权融资或增资等方式增加现金流入，预防资金链断裂，同时需合理规划贷款归还所需资金，避免出现资金紧张的情况。', '', '', '300001', '', 699);
INSERT INTO `t_mode` VALUES (700, '3', '现金流量预警45', 'XJLL_Y == 0 && XJLL_AM == 0 && XJLL_AZ > 0 && XJLL_BB > 0', '企业整个现金流完全单纯依靠融资活动支撑，生产经营现金流状况不佳，建议管理层采取以下措施改善现金流状况：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力。此外，建议管理层查看贷款到期情况，合理进行资金规划及筹措，避免出现因大批量大额偿还贷款产生资金链断链的风险。', '', '', '300001', '', 700);
INSERT INTO `t_mode` VALUES (701, '3', '现金流量预警46', 'XJLL_Y > 0 && XJLL_AM == 0 && XJLL_AZ == 0 && XJLL_BB > 0', '企业本期现金流由良好的经营活动支撑，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。同时，在良好的经营现金流支撑下，可考虑通过外部融资进一步增强现金流，加大效益高项目的投资。', '', '', '300001', '', 701);
INSERT INTO `t_mode` VALUES (702, '3', '现金流量预警47', 'XJLL_Y == 0 && XJLL_AM == 0 && XJLL_AZ < 0 && XJLL_BB < 0', '本期现金及现金等价物净增加额为负数，管理层需高度警惕，防止出现资金链断链的风险。筹资活动现金流量净额为负数，说明企业可能正在大笔偿还贷款，建议管理层查看贷款到期情况，合理进行资金规划及筹措。此外，建议管理层采取以下措施改善现金流：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力。', '', '', '300001', '', 702);
INSERT INTO `t_mode` VALUES (704, '3', '现金流量预警48', 'XJLL_Y == 0 && XJLL_AM < 0 && XJLL_AZ == 0 && XJLL_BB < 0', '本期现金及现金等价物净增加额为负数，管理层需高度警惕，防止出现资金链断链的风险。投资活动现金流量净额为负数，建议管理层评估投资风险及项目投资可行性及必要性，考虑是否需要调整投资策略，对部分严重亏损项目，考虑止损出售。此外，建议管理层采取以下措施改善现金流：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 704);
INSERT INTO `t_mode` VALUES (705, '3', '现金流量预警49', 'XJLL_Y < 0 && XJLL_AM == 0 && XJLL_AZ == 0 && XJLL_BB < 0', '经营活动产生的现金流量净额为负数，证明企业生产经营现金流状况不佳，建议管理层采取以下措施改善现金流状况：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 705);
INSERT INTO `t_mode` VALUES (706, '3', '现金流量预警50', 'XJLL_Y == 0 && XJLL_AM == 0 && XJLL_AZ == 0 && XJLL_BB == 0', '本期企业无任何现金流净增加额，资金链处于较危险状态，建议管理层采取以下措施改善现金流状况：1）对库存商品进行促销，增加收入，改善现金流入；2）加快应收款的催收，加速现金回笼；3）对成本及费用进行严格控制，减少不必要开支，从而做到开源节流；4）股东考虑进行增资缓解企业资金压力；5）查看是否存在可抵押的固定资产进行抵押贷款，或进行股权质押，或进行收款权质押等，通过各种途径进行筹资，改善总体现金流状况，但需考虑未来还本付息的压力。', '', '', '300001', '', 706);
INSERT INTO `t_mode` VALUES (709, '3', '现金流量预警51', 'XJLL_Y == 0 && XJLL_AM < 0 && XJLL_AZ > 0 && XJLL_BB > 0', '尽管企业最终现金及现金等价物净增加额为正数，本期现金及现金等价物的增长完全依靠筹资活动的现金流带动，经营活动产生的现金流为0，证明企业生产经营已处于危险状态，主要收入来源及现金流已非经营活动产生，对于投资者而言，释放危险信号，不利于企业未来融资规划及发展。同时，靠筹资活动产生的现金流入用于固定资产投资，建议管理层认真考虑投资的必要性、可行性、盈利性以及借款带来的未来还本付息的压力，需尽量规避因投资不慎导致无法还本付息，从而带来资金流断裂的风险。', '', '', '300001', '', 709);
INSERT INTO `t_mode` VALUES (716, '1', '固定资产概述', 'ZCFZ_AA1!=0&&ZCFZ_AA-ZCFZ_AA1==0', '与上年同期相比，本期固定资产金额为Rmb{ZCFZ_AA/10000}万元，与上年同期一致，变动为0。', '{ZCFZ_AA/10000}', '', 'G1002', '', 716);
