INSERT INTO `t_mode` VALUES (834, '1', '衍生金融资产概述', 'ZCFZ_E1!=0&&ZCFZ_E-ZCFZ_E1==0', '本期衍生金融资产为Rmb{ZCFZ_E/10000}万元，与上年同期持平，变动率为0。', '{ZCFZ_E/10000}', '', 'G1067', '', 834);
INSERT INTO `t_mode` VALUES (835, '1', '其他流动资产预警', 'ZCFZ_S1==0&&ZCFZ_S>0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10005', '', 835);
INSERT INTO `t_mode` VALUES (836, '1', '其他非流动资产上期为0本期非0', 'ZCFZ_AL1==0&&ZCFZ_AL>0', '其他非流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10021', '', 836);
INSERT INTO `t_mode` VALUES (839, '1', '持有待售的负债增加', 'ZCFZ_BI-ZCFZ_BI1>0', '由于持有待售的负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', '', '50011', '', 839);
INSERT INTO `t_mode` VALUES (840, '1', '持有待售的负债减少', 'ZCFZ_BI-ZCFZ_BI1<0', '由于持有待售的负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', '', '50011', '', 840);
INSERT INTO `t_mode` VALUES (841, '1', '持有待售的负债持平', 'ZCFZ_BI-ZCFZ_BI1==0', '由于持有待售的负债核算的类别较为特殊，且此类负债为非经营类负债，建议管理层在确保余额无误的情况下，结合市场情况，评估该类负债未来的市场价值变动对企业可能产生的影响，针对余额不变的类别，考虑是否需要进行清理等。', '', '', '50011', '', 841);
INSERT INTO `t_mode` VALUES (842, '1', '其他综合收益', 'ZCFZ_CF-ZCFZ_CF1>0', '其他综合收益属于非经常性科目，若在期末发生变化，建议管理层关注该变化的原因', '', '', '50012', '', 842);
INSERT INTO `t_mode` VALUES (843, '1', '其他综合收益持平', 'ZCFZ_CF-ZCFZ_CF1==0', '无预警。哈哈', '', '', '50012', '', 843);
INSERT INTO `t_mode` VALUES (844, '1', '其他权益工具变动预警', 'ZCFZ_CA1!=0&&ZCFZ_CA-ZCFZ_CA1>0', '其他权益工具属于非经常性科目，若在期末发生变动，建议管理层关注该变化的原因。', '', '', '50013', '', 844);
INSERT INTO `t_mode` VALUES (845, '2', '资产处置收益预警', 'LR_W-LR_W1>0', '资产处置收益大幅度增加，建议管理层关注处置资产的金额、原因和必要性。由于资产处置收益为非经常性收益，剔除后，营业利润将下降。建议管理层考虑资产处置收益变动的性质及原因，减少其对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '', '', '7005', '', 845);
INSERT INTO `t_mode` VALUES (846, '2', '资产处置收益预警', 'LR_W-LR_W1<0', '资产处置收益大幅度减少，建议管理层关注减少的原因。由于资产处置收益为非经常性收益，剔除后，营业利润将下降。建议管理层考虑资产处置收益的性质，减少其对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '', '', '7005', '', 846);
INSERT INTO `t_mode` VALUES (847, '2', '资产处置收益预警', 'LR_W-LR_W1==0', '本期和上年同期的资产处置收益一致，若资产处置收益不为0，则建议管理层关注资产处置收益产生的原因。由于资产处置收益为非经常性收益，剔除后，营业利润将下降。建议管理层考虑资产处置收益的性质，减少其对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '', '', '7005', '', 847);
INSERT INTO `t_mode` VALUES (851, '1', '应付票据变动为0', 'ZCFZ_AU-ZCFZ_AU1==0', '由于银行承兑汇票的付款期限最长为6个月，因此，使用票据实际上对企业来说可实现短期融资的目的，在短期现金流较为紧张的情况下，可考虑采取使用开具应付票据的方式减轻企业现金负担。然而，需注意以下可能产生的问题及风险：应付商业票据是购买企业在正常商业活动中向供应商承诺在将来特定时日、支付一笔固定货款的票据。与应付账款相比，应付商业票据由于提出了付款的书面承诺，因而更具有法律上的约束力。此外，企业应于汇票到期前将票款足额交存其开户银行，以免银行对企业进行计收利息及引起相关法律诉讼纠纷。同时建议管理层检查是否按要求设立备查薄，方便管理。', '', '', '10024', '', 851);
INSERT INTO `t_mode` VALUES (855, '1', '应付利息持平的预警', 'ZCFZ_BB==ZCFZ_BB1', '针对应付利息，提请管理层关注以下方面的问题：1、需查看借款合同，核查应付利息的确认时间和计量金额是否符合会计准则；2、关注付款期限及已支付金额，考虑自身资金压力；3、关注逾期未支付的违约责任及违约时间点。', '', '', '10028', '', 855);
INSERT INTO `t_mode` VALUES (856, '1', '应付股利持平的预警', 'ZCFZ_BC-ZCFZ_BC1==0', '关注该科目的变动是否与企业宣告派发的股利相符合，同时需考虑支付能力，结合企业未来的生产经营计划关注资金压力问题。', '', '', '10029', '', 856);
INSERT INTO `t_mode` VALUES (858, '1', '长期应付款不变的预警', 'ZCFZ_BQ1!=0&&ZCFZ_BQ-ZCFZ_BQ1==0', '由于一般性经营较少使用此科目，建议管理层查看此科目核算的内容，关注发生的原因及合理性，看是否存在因记账错误导致的余额变动。如非上述原因，则需根据科目核算的性质，考虑未来分期付款或融资租赁时支付款项对现金流的影响。', '', '', '10033', '', 858);
INSERT INTO `t_mode` VALUES (859, '1', '专项应付款不变的预警', 'ZCFZ_BS-ZCFZ_BS1==0', '由于此科目的特殊性，建议管理层设置专人管理此科目的变动情况，并且针对用款进行专项审核及登记，做到专款专用，详细记录专款的增减情况。', '', '', '10034', '', 859);
