INSERT INTO `t_mode` VALUES (1158, '1', '其他流动资产预警', 'ZCFZ_AL1!=0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1+0.2>0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1-0.2<0', '无预警。', NULL, NULL, '10021', NULL, 1158);
INSERT INTO `t_mode` VALUES (1159, '1', '其他非流动资产预警', 'ZCFZ_AL1!=0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1-0.2==0', '其他非流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', NULL, NULL, '10021', NULL, 1159);
INSERT INTO `t_mode` VALUES (1160, '1', '其他非流动资产预警', 'ZCFZ_AL1!=0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1+0.2<0', '其他非流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10021', '', 1160);
INSERT INTO `t_mode` VALUES (1161, '1', '其他非流动资产预警', 'ZCFZ_AL1!=0&&(ZCFZ_AL-ZCFZ_AL1)/ZCFZ_AL1+0.2==0', '其他非流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', NULL, NULL, '10021', NULL, 1161);
INSERT INTO `t_mode` VALUES (1162, '1', '短期借款预警', 'ZCFZ_AO1==0&&ZCFZ_AO-ZCFZ_AO1==0', '建议管理层在确保余额核算无误的情况下，根据企业未来生产经营计划及融资规划，结合现金流情况，考虑是否需要合理安排进行短期借款，避免出现资金紧张的情况。此外，管理层可考虑使用票据作为短期融资的途径，开拓不同类型的资金筹措方式，盘活现金流。', NULL, NULL, '10023', NULL, 1162);
INSERT INTO `t_mode` VALUES (1163, '1', '应付票据预警', 'ZCFZ_AU-ZCFZ_AU1<0', '由于银行承兑汇票的付款期限最长为6个月，因此，使用票据实际上对企业来说可实现短期融资的目的，在短期现金流较为紧张的情况下，可考虑采取使用开具应付票据的方式减轻企业现金负担。然而，需注意以下可能产生的问题及风险：应付商业票据是购买企业在正常商业活动中向供应商承诺在将来特定时日、支付一笔固定货款的票据。与应付账款相比，应付商业票据由于提出了付款的书面承诺，因而更具有法律上的约束力。此外，企业应于汇票到期前将票款足额交存其开户银行，以免银行对企业进行计收利息及引起相关法律诉讼纠纷。同时建议管理层检查是否按要求设立备查薄，方便管理。', NULL, NULL, '10024', NULL, 1163);
INSERT INTO `t_mode` VALUES (1165, '1', '应付股利预警', 'ZCFZ_BC-ZCFZ_BC1<0', '关注该科目的变动是否与企业宣告派发的股利相符合，同时需考虑支付能力，结合企业未来的生产经营计划关注资金压力问题。', NULL, NULL, '10029', NULL, 1165);
INSERT INTO `t_mode` VALUES (1167, '1', '其他流动负债预警', 'ZCFZ_BK1!=0&&(ZCFZ_BK-ZCFZ_BK1)/ZCFZ_BK1-0.2==0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10030', '', 1167);
