INSERT INTO `t_mode` VALUES (1169, '1', '其他流动负债预警', 'ZCFZ_BK1!=0&&(ZCFZ_BK-ZCFZ_BK1)/ZCFZ_BK1+0.2==0', '其他流动资产若在期末发生大幅度的变动，建议管理层关注该变化的原因及合理性。', '', '', '10030', '', 1169);
INSERT INTO `t_mode` VALUES (1170, '1', '其他流动负债预警', 'ZCFZ_BK1!=0&&ZCFZ_BK-ZCFZ_BK1==0', '无预警。', '', '', '10030', '', 1170);
INSERT INTO `t_mode` VALUES (1171, '1', '其他流动负债预警', 'ZCFZ_BK1!=0&&(ZCFZ_BK-ZCFZ_BK1)/ZCFZ_BK1+0.2>0', '无预警。', '', '', '10030', '', 1171);
INSERT INTO `t_mode` VALUES (1172, '1', '其他流动负债预警', 'ZCFZ_BK1!=0&&(ZCFZ_BK-ZCFZ_BK1)/ZCFZ_BK1-0.2<0', '无预警。', '', '', '10030', '', 1172);
INSERT INTO `t_mode` VALUES (1176, '2', '资产处置收益概述', 'LR_W1!=0 && LR_W-LR_W1>0', '本期资产处置收益为Rmb{LR_W/10000}万元，上年同期为Rmb{LR_W1/10000}万元，增加了{(LR_W- LR_W1)*100/Math.abs(LR_W1)}%。', '{LR_W/10000},{LR_W1/10000},{(LR_W- LR_W1)*100/Math.abs(LR_W1)}', '', 'G2020', '', 1176);
INSERT INTO `t_mode` VALUES (1177, '2', '资产处置收益概述', 'LR_W1!=0 && LR_W1-LR_W>0', '本期资产处置收益为Rmb{LR_W/10000}万元，上年同期为Rmb{LR_W1/10000}万元，减少了{(LR_W1- LR_W)*100/Math.abs(LR_W1)}%。', '{LR_W/10000},{LR_W1/10000},{(LR_W1- LR_W)*100/Math.abs(LR_W1)}', '', 'G2020', '', 1177);
INSERT INTO `t_mode` VALUES (1178, '2', '资产处置收益概述', 'LR_W1!=0 && LR_W1-LR_W==0', '与上年同期相比，本期资产处置收益为Rmb{LR_W/10000}万元，与上年同期一致，变动为0。', '{LR_W/10000}', '', 'G2020', '', 1178);
INSERT INTO `t_mode` VALUES (1179, '2', '资产处置收益概述', 'LR_W1==0', '资产处置收益从上年同期的Rmb{LR_W1/10000}万元增长至本期的Rmb{LR_W/10000}万元，增长率为-%。', '{LR_W1/10000},{LR_W/10000}', '', 'G2020', '', 1179);
INSERT INTO `t_mode` VALUES (1180, '1', '长期借款预警', 'ZCFZ_BM1==0&&ZCFZ_BM-ZCFZ_BM1==0', '建议管理层在确保余额核算无误的情况下，根据企业未来生产经营计划及融资规划，结合现金流情况，考虑是否需要借入长期借款，避免出现资金紧张的情况。如有进行长期借款的计划，则需就抵押物、贷款期限、资金归还等进行合理规划。', NULL, NULL, '10031', NULL, 1180);
INSERT INTO `t_mode` VALUES (1183, '1', '长期应付款预警', 'ZCFZ_BQ1!=0&&ZCFZ_BQ-ZCFZ_BQ1<0', '由于一般性经营较少使用此科目，建议管理层查看此科目核算的内容，关注发生的原因及合理性，看是否存在因记账错误导致的余额变动。如非上述原因，则需根据科目核算的性质，考虑未来分期付款或融资租赁时支付款项对现金流的影响。', NULL, NULL, '10033', NULL, 1183);
INSERT INTO `t_mode` VALUES (1184, '1', '长期应付款预警', 'ZCFZ_BQ==0&&ZCFZ_BQ-ZCFZ_BQ1==0', '无预警。', '', '', '10033', '', 1184);
INSERT INTO `t_mode` VALUES (1185, '1', '专项应付款预警', 'ZCFZ_BS-ZCFZ_BS1!=0', '由于此科目的特殊性，建议管理层设置专人管理此科目的变动情况，并且针对用款进行专项审核及登记，做到专款专用，详细记录专款的增减情况。', '', '', '10034', '', 1185);
INSERT INTO `t_mode` VALUES (1188, '1', '其他非流动负债预警', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1-0.2==0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', '', '', '10037', '', 1188);
INSERT INTO `t_mode` VALUES (1189, '1', '其他非流动负债预警', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1+0.2<0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', NULL, NULL, '10037', NULL, 1189);
INSERT INTO `t_mode` VALUES (1190, '1', '其他非流动负债预警', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1+0.2==0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', NULL, NULL, '10037', NULL, 1190);
INSERT INTO `t_mode` VALUES (1191, '1', '其他非流动负债预警', 'ZCFZ_BW1!=0&&(ZCFZ_BW-ZCFZ_BW1)/ZCFZ_BW1+0.2==0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', NULL, NULL, '10037', NULL, 1191);
INSERT INTO `t_mode` VALUES (1192, '1', '其他非流动负债预警', 'ZCFZ_BW1==0&&ZCFZ_BW1-ZCFZ_BW==0', '无预警。', '', '', '10037', '', 1192);
INSERT INTO `t_mode` VALUES (1193, '1', '其他权益工具预警', 'ZCFZ_CA1!=0&&ZCFZ_CA-ZCFZ_CA1<0', '其他权益工具属于非经常性科目，若在期末发生变动，建议管理层关注该变化的原因。', NULL, NULL, '50013', NULL, 1193);
INSERT INTO `t_mode` VALUES (1194, '1', '其他权益工具预警', 'ZCFZ_CA-ZCFZ_CA1==0', '无预警。哈哈', '', '', '50013', '', 1194);
INSERT INTO `t_mode` VALUES (1195, '1', '其他综合收益预警', 'ZCFZ_CF-ZCFZ_CF1<0', '其他综合收益属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', NULL, NULL, '50012', NULL, 1195);
INSERT INTO `t_mode` VALUES (1198, '2', '所得税费用预警', 'LR_AE1==0&&LR_AE>LR_AE1', '所得税费用本期比上年同期增长-%，建议管理层关注所得税申报中不得抵扣项的原因及金额，考虑是否需要聘请专业团队为企业进行税收筹划，达到合理避税，增加净利润的目的。', '', '', '20017', '', 1198);
INSERT INTO `t_mode` VALUES (1200, '2', '所得税费用预警', 'LR_AE1==0&&LR_AE-LR_AE1==0', '无预警。', '', '', '20017', '', 1200);
INSERT INTO `t_mode` VALUES (1201, '1', '营运资本概述', 'YBLFX-A!=YBLFX-A1', 'haha', NULL, NULL, '8888', NULL, 1201);
INSERT INTO `t_mode` VALUES (1202, '5', '营运资本概述', 'YBLFX_A-YBLFX_A==0', '营运资本=流动资产-流动负债\r\n营运资本可以用来衡量公司的短期偿债能力。营运资本越多，说明公司对于短期支付义务的准备越充足，短期偿债能力越好。当运营资本为负数时，表明流动资产已不足以支撑短期债务，正常运营所需资金短缺，公司需缩短收入的回款期、加快应收款的回收或进行外部融资。\r\n一家企业的营运资本到底多少才算足够，各公司间因运营模式不同而差异大，因此，可对本公司不同历史时期的运营资本周转期进行比较，分析公司自身运营资本周转期的合理范围。', '', '', 'GBL8001', '', 1202);
INSERT INTO `t_mode` VALUES (1203, '5', '流动比率概述', 'YBLFX_B-YBLFX_B==0', '流动比率=流动资产/流动负债\r\n流动比率用来衡量企业流动资产在短期债务到期以前，可以变为现金用于偿还负债的能力。流动比率越高，公司的资产变现能力和短期偿债能力越强，反之越弱，但并非越高越好。流动比率太高，则可能存在资金闲置、存货积压等问题，说明企业经营管理不善。通常认为生产型公司比较合理的流动比率为2:1，但各公司可根据不同历史时期和同行业的数据，比较分析自身流动比率的合理范围，对不属于合理范围的流动比率需查明原因并采取相应措施。', NULL, NULL, 'GBL8002', NULL, 1203);
INSERT INTO `t_mode` VALUES (1204, '5', '速动比率概述', 'YBLFX_C-YBLFX_C==0', '速动比率=速动资产（流动资产-存货）/流动负债\r\n速动比率衡量企业流动资产中可以立即变现用于偿还流动负债的能力。速动比率越高，公司的资产较快变现能力和短期偿债能力越强，反之越弱，但并非越高越好。速动比率太高，则可能存在资金闲置问题。通常认为生产型公司的比较合理的速动比率为1:1，但各公司可根据不同历史时期和同行业的数据，比较分析自身速动比率的合理范围，对不属于合理范围的流动比率需查明原因并采取相应措施。', NULL, NULL, 'GBL8003', NULL, 1204);
INSERT INTO `t_mode` VALUES (1205, '5', '现金比率概述', 'YBLFX_D-YBLFX_D==0', '现金比率=(货币资金+交易性金融资产)/流动负债\r\n现金比率通过计算公司现金以及现金等价资产总量与当前流动负债的比率，来衡量公司资产的流动性。现金比率越高，企业即时付现能力越强，但并非越高越好。现金比率太高，则资金闲置、资金规划不合理。各公司可根据不同历史时期和同行业的数据，比较分析自身现金比率的合理范围，对不属于合理范围的现金比率需查明原因并采取相应措施。', NULL, NULL, 'GBL8004', NULL, 1205);
INSERT INTO `t_mode` VALUES (1206, '5', '现金流量比率概述', 'YBLFX_E-YBLFX_E==0', '现金流量比率=经营活动产生的现金净流量/期末流动负债\r\n现金流量比率用于衡量企业经营活动所产生的现金流量可以抵偿流动负债的程度，比率越高，说明企业的财务弹性越好。一般而言，当经营现金流量比率低于50%时，企业应该警惕。但各公司可根据不同历史时期和同行业的数据，比较分析自身现金流量比率的合理范围，对不属于合理范围的现金流量比率需查明原因并采取相应措施。', NULL, NULL, 'GBL8005', NULL, 1206);
INSERT INTO `t_mode` VALUES (1207, '5', '资产负债率概述', 'YBLFX_F-YBLFX_F==0', '资产负债率=总资产/总负债×100%\r\n资产负债率反映总资产中由债权人提供的资产所占比重的大小，可以用来衡量企业清算时对债权人利益的保护程度。一般认为，资产负债率的适宜水平是40%～60%，过高则企业举债经营能力越弱、偿债风险越高，过低则不能充分发挥财务杠杠作用。但各公司可根据不同历史时期和同行业的数据，比较分析自身资产负债率的合理范围，对不属于合理范围的资产负债率需查明原因并采取相应措施。\r\n资产负债比率高达100%时，公司已资不抵债，可能面临破产清算风险。即使公司资产负债率不高，但管理层也需关注潜在债务、担保风险等，以防突发性债务给企业造成巨大资金压力。', NULL, NULL, 'GBL8006', NULL, 1207);
INSERT INTO `t_mode` VALUES (1208, '5', '产权比率概述', 'YBLFX_G-YBLFX_G==0', '产权比率=负债总额/所有者权益×100%\r\n产权比率可用来评估资金结构的合理性。产权比率越低，表明企业自有资本占总资产的比重越大，长期偿债能力越强。比率越高，表明自有资金占总资产比率越小，基本财务结构越不稳定，长期偿债能力越低。同时，若产权比率偏高，管理层也需关注注册资本是否实缴。若未实缴，可要求股东进行缴纳，补充企业流动资金。各公司可根据不同历史时期和同行业的数据，比较分析自身产权比率的合理范围，对不属于合理范围的产权比率需查明原因并采取相应措施。', NULL, NULL, 'GBL8007', NULL, 1208);
INSERT INTO `t_mode` VALUES (1209, '5', '权益乘数概述', 'YBLFX_H-YBLFX_H==0', '权益乘数=资产总额/所有者权益总额\r\n权益乘数反映了企业财务杠杆的大小。权益乘数越小，表明所有者投入企业的资本占全部资产的比重越大，企业的负债程度越低，长期偿债能力越强。权益乘数越大，说明股东投入的资本在资产中所占的比重越小，长期偿债能力越低。同时，若权益乘数偏高，管理层也需关注注册资本是否实缴。若未实缴，可要求股东进行缴纳，补充企业流动资金。各公司可根据不同历史时期和同行业的数据，比较分析自身权益乘数的合理范围，对不属于合理范围的权益乘数需查明原因并采取相应措施。', NULL, NULL, 'GBL8008', NULL, 1209);
INSERT INTO `t_mode` VALUES (1210, '5', '长期资本负债率概述', 'YBLFX_I-YBLFX_I==0', '长期资本负债率=[非流动负债/(非流动负债+股东权益)]×100%\r\n长期资本负债率反映企业的长期资本的结构，且更为客观地反映企业的长期偿债能力。长期资本负债率越高，长期偿债能力越弱。同时，若该比率偏高，管理层也需关注注册资本是否实缴。若未实缴，可要求股东进行缴纳，补充企业流动资金。各公司可根据不同历史时期和同行业的数据，比较分析自身长期资本负债率的合理范围，对不属于合理范围的需查明原因并采取相应措施。', NULL, NULL, 'GBL8009', NULL, 1210);
INSERT INTO `t_mode` VALUES (1211, '5', '现金流量债务比概述', 'YBLFX_M-YBLFX_M==0', '现金流量利息保障倍数=经营活动产生的现金净流量/利息费用\r\n现金流量利息保障倍数是指经营现金净流量为利息费用的倍数。它比收益基础的利息保障倍数更可靠，因为实际用以支付利息的是现金，而非收益。比率越高，偿还债务总额的能力越强。比率大于等于1时，则意味着企业的经营现金净流量可完全覆盖全部债务，偿债能力高。', NULL, NULL, 'GBL8010', NULL, 1211);
INSERT INTO `t_mode` VALUES (1212, '5', '应收账款周转天数概述', 'YBLFX_L-YBLFX_L==0', '应收账款周转天数=平均应收账款余额/营业收入×天数\r\n应收账款周转天数表明从销售开始到收回现金平均需要的天数。应收账款周转天数越短，说明流动资金使用效率越好。大多数公司都存在信用销售，形成大量应收账款，如何快速将应收账款收回变成现金对公司持续运转至关重要。如果周转天数过长，公司将不得不通过借债等方式来补充营运资金，会造成财务费用的上涨和经营利润的压缩。在相同行业内，应收账款周转天数越短的公司通常有较强的竞争力。但值得指出的是，过短的应收账款周转天数，可能导致与客户的关系恶化。管理层需合理平衡延长付款期与维护客户关系之间的关系。\r\n一般情况下，建议企业应收账款周转天数不超过90天对企业运作较为有利。各公司可根据不同历史时期和同行业的数据，比较分析自身应收账款周转天数的合理范围，对不属于合理范围的需查明原因并采取相应措施。', NULL, NULL, 'GBL8011', NULL, 1212);
INSERT INTO `t_mode` VALUES (1213, '5', '存货周转天数概述', 'YBLFX_N-YBLFX_N==0', '存货周转天数=平均存货余额/营业成本×天数\r\n   存货周转天数是指企业从取得存货开始，至消耗、销售为止所经历的天数。存货周转天数越低，公司存货周转速度快，销售状况更好。周转天数越高，则存货过多积压，造成资金浪费，不利于企业运营。 \r\n一般情况下，建议企业存货周转天数不超过90天对企业运作较为有利。各公司可根据不同历史时期和同行业的数据，比较分析自身存货周转天数的合理范围，对不属于合理范围的需查明原因并采取相应措施。', NULL, NULL, 'GBL8012', NULL, 1213);
INSERT INTO `t_mode` VALUES (1214, '5', '应付账款周转天数概述', 'YBLFX_O-YBLFX_O==0', '应付账款周转天数=平均应付账款余额/营业成本×天数\r\n应付账款周转天数是衡量公司需要多长时间付清供应商的欠款。与应收账款周转天数不同的是，通常来说，应付账款周转天数越长越好。周转天数越长，企业可控制的现金越多，越有利于企业的资金利用。但值得指出的是，过长的应付账款周转天数，可能导致与供应商的关系恶化。管理层需合理平衡延长付款期与维护供应商关系之间的关系。各公司可根据不同历史时期和同行业的数据，比较分析自身应付账款周转天数的合理范围，对不属于合理范围的需查明原因并采取相应措施。', NULL, NULL, 'GBL8013', NULL, 1214);
INSERT INTO `t_mode` VALUES (1215, '5', '流动资产周转天数概述', 'YBLFX_P-YBLFX_P==0', '流动资产周转天数=平均流动资产总额/营业收入×天数\r\n流动资产周转天数表明流动资产周转一次需要的时间，也就是流动资产转换成现金平均需要的时间。流动资产周转天数越短，企业现金流越健康，运营效果更好。', NULL, NULL, 'GBL8014', NULL, 1215);
INSERT INTO `t_mode` VALUES (1216, '5', '营业资本周转天数概述', 'YBLFX_Q-YBLFX_Q==0', '营业资本周转天数=平均营运资本/营业收入×天数\r\n营运资本周转天数表明营业资本周转一次需要的时间。不存在衡量营运资本周转率的通用标准，只有将这一指标与企业历史水平，其他企业或同行业平均水平相比才有意义。如果营运资本周转率过低，表明营运资本使用率太低，即相对营运资本来讲，销售不足，有潜力可挖；如果营运资本周转率过高，则表明资本不足，业务清偿债务危机之中。', NULL, NULL, 'GBL8015', NULL, 1216);
INSERT INTO `t_mode` VALUES (1217, '5', '非流动资产周转天数概述', 'YBLFX_R-YBLFX_R==0', '非流动资产周转天数=平均非流动资产/营业收入×天数\r\n非流动资产周转天数反映非流动资产的管理效率，主要用于投资预算和项目管理分析，以确定投资于竞争战略是否一致，收购和剥离政策是否合理等。', NULL, NULL, 'GBL8016', NULL, 1217);
INSERT INTO `t_mode` VALUES (1218, '5', '总资产周转天数概述', 'YBLFX_S-YBLFX_S==0', '总资产周转天数=平均资产总额/营业收入×天数\r\n总资产周转天数反映企业经营期间全部资产从投入到产出的流转速度，反映了企业全部资产的管理质量和利用效率。总资产周转天数越小，说明总资产周转越快，销售能力越强，企业运营效率越高。\r\n如果企业的总资产周转天数突然下降，而企业的销售收入却无多大变化，则可能是企业本期报废了大量固定资产造成的，而不是企业的资产利用效率提高。\r\n如果企业的总资产天数较高，且长期处于较高的状态，企业应采取措施提高各项资产的利用效率，处置多余，闲置不用的资产，提高销售收入，从而提高总资产周转率。', NULL, NULL, 'GBL8017', NULL, 1218);
INSERT INTO `t_mode` VALUES (1219, '5', '销售净利润率概述', 'YBLFX_T-YBLFX_T==0', '销售净利润率=净利润/营业收入×100%\r\n销售净利润率表明企业每单位销售收入净额可实现的净利润。销售净利润率越高，说明企业的获利能力越强，但它受行业特点影响较大，在分析时应该结合不同行业具体情况进行分析。', '', '', 'GBL8018', '', 1219);
INSERT INTO `t_mode` VALUES (1220, '5', '总资产净利润率概述', 'YBLFX_W-YBLFX_W==0', '总资产净利润率=净利润/总资产×100%\r\n总资产净利润率是反映企业资产综合利用效果的指标，也是衡量企业利用债权人和所有者权益总额所取得盈利的重要指标。总资产净利润率越高，说明企业的每单位资产赚取的利润率越高。各公司可根据不同历史时期和同行业的数据，比较分析自身总资产净利润率的合理范围，并以此为依据制定预算并执行。', NULL, NULL, 'GBL8019', NULL, 1220);
INSERT INTO `t_mode` VALUES (1221, '5', '权益净利润率概述', 'YBLFX_Y-YBLFX_Y==0', '权益净利润率=所有者权益/总资产×100%\r\n权益净利润率反映所有者权益所获报酬的水平。比率越高，股东的投资获利越高。各公司可根据不同历史时期和同行业的数据，比较分析自身权益净利润率的合理范围，并以此为依据制定预算并执行。', NULL, NULL, 'GBL8020', NULL, 1221);
INSERT INTO `t_mode` VALUES (1222, '1', '经营报告偿债能力分析', 'YBLFX_F-YBLFX_F1>0&&ZCFZ_BY-ZCFZ_BY1<0&&ZXFZ_AN-ZXFZ_AN1<0', '本期资产负债率比上期有所上升，主要是因为负债的变动导致', '', '', 'GJYBG9001', '', 1222);
INSERT INTO `t_mode` VALUES (1223, '1', '经营报告营运情况分析', 'XJLL_Y>0&&XJLL_Y-XJLL_Y1>0', '本期经营活动产生的现金流量净额为正数，且较上期有所增长，说明企业经营较为良好，建议管理层在维持现经营状况的前提下积极开源节流，争取占领更大的市场份额。除此以为，建议企业结合投资活动现金流入、投资活动现金流出及筹资活动现金流入、筹资活动现金流出的总体情况，对现金流量表进行总体分析。', NULL, NULL, 'GJYBG9002', NULL, 1223);
INSERT INTO `t_mode` VALUES (1224, '1', '经营报告营运情况分析', 'XJLL_Y>0&&XJLL_Y-XJLL_Y1<0', '本期经营活动产生的现金流量净额为正数，说明企业经营较为良好，然而，目前企业经营活动产生的现金流仍存在以下问题：a)本期经营活动产生的现金流量净额比上期减少了Rmb{(XJLL_Y1-XJLL_Y)/10000}万元，说明企业本期经营活动未如上期理想。建议管理层结合应收账款周转期，应付账款周转期等指标，综合考虑本期经营活动产生的现金流量净额的减少的导因。如因应收账款回收期拖长导致现金流状况的改变，建议管理层与市场部讨论款项催收的措施，或考虑修改合同货期条款对企业可能产生的利益影响；如因付款周期变短引起现金流的波动，则考虑与供应商，尤其是主要供应商，讨论付款期的延长；如因内部开支等剧增导致经营性现金流出现下滑趋势，则需考虑调整绩效考核，评估人员配置等措施达到开源节流的目的，从而使现金流得到相应的改善。除此以为，建议企业结合投资活动现金流入、投资活动现金流出及筹资活动现金流入、筹资活动现金流出的总体情况，对现金流量表进行总体分析。', '{(XJLL_Y1-XJLL_Y)/10000}', NULL, 'GJYBG9002', NULL, 1224);
INSERT INTO `t_mode` VALUES (1225, '1', '经营报告营运情况分析', 'XJLL_Y<0', '本期经营活动产生的现金流量净额为负数，说明企业经营较为不理想，现金流管理存在较大问题。建议管理层结合应收账款及应付账款周转期等，综合分析经营活动现金流存在的问题，从以下方面着手进行整改：a)与供应商，尤其是主要供应商，就数期与供应商进行沟通，尽量延长付款期，以改善现金流出状况；b)与客户，尤其是前十大客户，就账期进行沟通，尽量缩短收款期，但是要注意收款期缩短可能导致的客户流失，管理层需分析收款期缩短对销售的敏感度，进行合理的调整；c)通过与绩效考核相挂钩等方式，控制日常经营活动中产生的费用支出以及人工支出，减少现金流出，从而达到使经营活动现金流净额扭负为正的目的。除此以为，建议企业结合投资活动现金流入、投资活动现金流出及筹资活动现金流入、筹资活动现金流出的总体情况，对现金流量表进行总体分析。', NULL, NULL, 'GJYBG9002', NULL, 1225);
INSERT INTO `t_mode` VALUES (1892, '1', '资产负债表首页概况', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_A-ZCFZ_A1>0&& ZCFZ_A1!=0&&(ZCFZ_A-ZCFZ_A1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AL-ZCFZ_AL1)>0', '本期总资产较上年同期有所增长，主要是因为货币资金从上年同期的Rmb{ZCFZ_A1/10000}万元增至本期的Rmb{ZCFZ_A/10000}万元，增长率达{(ZCFZ_A-ZCFZ_A1)/ZCFZ_A1*100}%，占总资产变动的{(ZCFZ_A-ZCFZ_A1)/(ZCFZ_AN-ZCFZ_AN1)*100}%。', '{ZCFZ_A1/10000},{ZCFZ_A/10000},{(ZCFZ_A-ZCFZ_A1)/ZCFZ_A1*100},{(ZCFZ_A-ZCFZ_A1)/(ZCFZ_AN-ZCFZ_AN1)*100}', NULL, 'G1001', NULL, 1892);
