INSERT INTO `t_mode` VALUES (2260, '2', '税金及附加预警', 'LR_O1==0&&LR_O-LR_O1>0', '税金及附加从上期的Rmb0.00万元增长至本期的Rmb{LR_O/10000}万元。税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入的比率变动关系，同时关注税收政策变化、进一步核查本期可抵扣税额，查看是否存在税率调增、不再享有免税政策以及大量发票不可抵扣的情况，从而规范发票管理及排查税务风险。', '{LR_O/10000}', NULL, '20014', NULL, 2260);
INSERT INTO `t_mode` VALUES (2261, '2', '财务费用预警', 'LR_R1==0&&LR_R-LR_R1>0', '财务费用从上期的Rmb0.00万元增长至本期的Rmb{LR_R/10000}万元，财务费用大幅度增加，成为净利润减少的主因。财务费用的大幅度增加，主要是因为本期贷款金额的增加。建议管理层结合资金情况，贷款情况，做好资金用途的管理，同时评估未来还款付息对资金流产生的压力，评估资金状况是否足以承受未来的还本付息所需的现金流。', '{LR_R/10000}', NULL, '20010', NULL, 2261);
INSERT INTO `t_mode` VALUES (2262, '2', '资产减值损失预警', 'LR_S1==0&&LR_S-LR_S1>0', '资产减值损失从上期的Rmb0.00万元增长至本期的Rmb{LR_S/10000}万元，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施减少损失，同时，特别警惕因技术变革、行业创新导致公司资产大幅度减值的情况。', '{LR_S/10000}', NULL, '20015', NULL, 2262);
INSERT INTO `t_mode` VALUES (2263, '2', '公允价值变动收益预警', 'LR_T1==0&&LR_T-LR_T1>0', '公允价值变动收益从上期的Rmb0.00万元增长至本期的Rmb{LR_T/10000}万元。由于公允价值变动为非经常性收益，剔除后，营业利润将下降。建议管理层考虑公允价值变动的性质，具体分析其增加原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{LR_T/10000}', NULL, '20016', NULL, 2263);
INSERT INTO `t_mode` VALUES (2264, '2', '投资收益预警', 'LR_U1==0&&LR_U-LR_U1>0', '投资收益从上期的Rmb0.00万元增长至本期的Rmb{LR_U/10000}万元，本期投资收益大幅度增加。由于投资收益为非经常性收益，剔除投资收益后，营业利润将大幅度下降。建议管理层考虑投资收益的性质，具体分析其增加原因，减少投资收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{LR_U/10000}', '', '20011', '', 2264);
INSERT INTO `t_mode` VALUES (2265, '2', '其他收益预警', 'LR_X1==0&&LR_X-LR_X1>0', '其他收益从上期的Rmb0.00万元增长至本期的Rmb{LR_X/10000}万元，本期其他收益大幅度增加。由于其他收益为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑其他收益的性质，具体分析其增加原因，减少其他收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{LR_X/10000}', NULL, '50010', NULL, 2265);
INSERT INTO `t_mode` VALUES (2266, '2', '营业外收入预警', 'LR_Z1==0&&LR_Z-LR_Z1>0', '营业外收入从上期的Rmb0.00万元增长至本期的Rmb{LR_Z/10000}万元，由于营业外收入为非经营性收入，不具有持续性，在融资、上市等接受尽调或者审计时，均将作为模拟调整的对象，因此，建议管理层查看以前年度营业外收入的性质，并剔除历史数据中营业外收入对净利润的影响后，再分析净利润的变动原因。', '{LR_Z/10000}', NULL, '20012', NULL, 2266);
INSERT INTO `t_mode` VALUES (2267, '2', '营业外支出预警', 'LR_AB1==0&&LR_AB-LR_AB1>0', '营业外支出从上期的Rmb0.00万元增长至本期的Rmb{LR_AB/10000}万元，营业外支出大幅增加，建议管理层关注是否发生了大额的资产处置损失，资产处置是否履行了审批制度并关注大额资产处置的原因。另外，营业外支出为非经营性支出，不具有持续性。建议管理层剔除两期营业外支出后，重新评估净利润的变动情况及趋势，并相应做出管理决策。', '{LR_AB/10000}', NULL, '20013', NULL, 2267);
INSERT INTO `t_mode` VALUES (2268, '2', '财务费用预警', 'LR_R1==0&&LR_R==LR_R1', '本期与上期一致，财务费用为0，此情况较为异常。且若企业货币资金非0，财务费用不应为0，建议管理层查看详细账务记录，进行相应调整。此外，可考虑适当进行长期或短期贷款筹借，减少企业现金流负担，但需考虑未来还本付息对现金流可能产生的影响。', '', '', '20010', '', 2268);
INSERT INTO `t_mode` VALUES (2391, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1>0&&YBLFX_L>90&&YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '应收账款期末较上年同期有所上涨，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。应收账款周转天数>90天，企业收账速度较慢、平均收账期较长，产生坏账损失的可能性较高。建议管理层需加强账款的催收，保障资产的流动性，有利于企业的正常生产运营。在应收账款中，账龄超过360日的应收账款余额为Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元。针对账龄超1年的应收账款，建议管理层分析其回收可能性以及出售的可能性，择优选择对自身最有利的方案，并相应进行账务调整。同时，查看与相关客户的合同，针对合同提及的违约责任等，考虑是否追究其法律责任。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}', NULL, '11002', NULL, 2391);
