INSERT INTO `t_mode` VALUES (2398, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1<0&&YBLFX_L<=90&&YSZKZL_D+YSZKZL_E+YSZKZL_F==0', '应收账款期末较上年同期有所减少，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。', '', NULL, '11002', NULL, 2398);
INSERT INTO `t_mode` VALUES (2399, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1==0&&YBLFX_L>90&&YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '应收账款期末与上年同期持平，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。应收账款周转天数>90天，企业收账速度较慢、平均收账期较长，产生坏账损失的可能性较高。建议管理层需加强账款的催收，保障资产的流动性，有利于企业的正常生产运营。在应收账款中，账龄超过360日的应收账款余额为Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元。针对账龄超1年的应收账款，建议管理层分析其回收可能性以及出售的可能性，择优选择对自身最有利的方案，并相应进行账务调整。同时，查看与相关客户的合同，针对合同提及的违约责任等，考虑是否追究其法律责任。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}', NULL, '11002', NULL, 2399);
INSERT INTO `t_mode` VALUES (2400, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1==0&&YBLFX_L>90&&YSZKZL_D+YSZKZL_E+YSZKZL_F==0', '应收账款期末与上年同期持平，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。应收账款周转天数>90天，企业收账速度较慢、平均收账期较长，产生坏账损失的可能性较高。建议管理层需加强账款的催收，保障资产的流动性，有利于企业的正常生产运营。', '', NULL, '11002', NULL, 2400);
INSERT INTO `t_mode` VALUES (2401, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1==0&&YBLFX_L<=90&&YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '应收账款期末与上年同期持平，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。在应收账款中，账龄超过360日的应收账款余额为Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元。针对账龄超1年的应收账款，建议管理层分析其回收可能性以及出售的可能性，择优选择对自身最有利的方案，并相应进行账务调整。同时，查看与相关客户的合同，针对合同提及的违约责任等，考虑是否追究其法律责任。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}', NULL, '11002', NULL, 2401);
INSERT INTO `t_mode` VALUES (2402, '1', '应收账款预警', 'ZCFZ_G-ZCFZ_G1==0&&YBLFX_L<=90&&YSZKZL_D+YSZKZL_E+YSZKZL_F==0', '应收账款期末与上年同期持平，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。', '', NULL, '11002', NULL, 2402);
INSERT INTO `t_mode` VALUES (2403, '1', '预付款项预警', 'ZCFZ_H-ZCFZ_H1>0&&YFKXZL_D+YFKXZL_E+YFKXZL_F>0', '预付款项在期末较上年同期有所增加，建议管理层查看增加情况，考虑是否属于年底正常业务增长需求，若不属于，则建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付比例。本期账龄超过360日的预付款项金额为Rmb{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}万元，建议管理层查看预付账款的账龄分析，对账龄超过1年的预付账款确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}', NULL, '11003', NULL, 2403);
INSERT INTO `t_mode` VALUES (2404, '1', '预付款项预警', 'ZCFZ_H-ZCFZ_H1>0&&YFKXZL_D+YFKXZL_E+YFKXZL_F==0', '预付款项在期末较上年同期有所增加，建议管理层查看增加情况，考虑是否属于年底正常业务增长需求，若不属于，则建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付比例。', '', NULL, '11003', NULL, 2404);
