INSERT INTO `t_mode` VALUES (2406, '1', '预付款项预警', 'ZCFZ_H-ZCFZ_H1<0&&YFKXZL_D+YFKXZL_E+YFKXZL_F==0', '预付款项在期末较上年同期有所减少，建议管理层查看减少情况，考虑是否属于年底正常业务减少需求，若不属于，则建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付形式。', '', NULL, '11003', NULL, 2406);
INSERT INTO `t_mode` VALUES (2407, '1', '预付款项预警', 'ZCFZ_H-ZCFZ_H1==0&&YFKXZL_D+YFKXZL_E+YFKXZL_F>0', '预付款项在期末与上年同期持平，建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付比例。本期账龄超过360日的预付款项金额为Rmb{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}万元，建议管理层查看预付账款的账龄分析，对账龄超过1年的预付账款确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}', NULL, '11003', NULL, 2407);
INSERT INTO `t_mode` VALUES (2408, '1', '预付款项预警', 'ZCFZ_H-ZCFZ_H1==0&&YFKXZL_D+YFKXZL_E+YFKXZL_F==0', '预付款项在期末与上年同期持平，建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付比例。', '', NULL, '11003', NULL, 2408);
INSERT INTO `t_mode` VALUES (2409, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1>0&&QTYSZL_D+QTYSZL_E+QTYSZL_F>0', '其他应收款在期末较上年同期有所增加，此现象较为异常，考虑是否因股东间拆借或他方违约引起。建议管理层查看其他应收款明细及相应信息。其他应收款期末的异常变动为年度审计、IPO审计、银行贷款的重点关注情况，建议管理层高度重视。其他应收款中有Rmb{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}万元账龄已超360日，对账龄超过1年的其他应收款需引起管理层的重视，建议管理层查看该部分较长账龄的其他应收款是否属于关联交易，并确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}', NULL, '11004', NULL, 2409);
INSERT INTO `t_mode` VALUES (2410, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1>0&&QTYSZL_D+QTYSZL_E+QTYSZL_F==0', '其他应收款在期末较上年同期有所增加，此现象较为异常，考虑是否因股东间拆借或他方违约引起。建议管理层查看其他应收款明细及相应信息。其他应收款期末的异常变动为年度审计、IPO审计、银行贷款的重点关注情况，建议管理层高度重视。', '', NULL, '11004', NULL, 2410);
INSERT INTO `t_mode` VALUES (2411, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1<0&&QTYSZL_D+QTYSZL_E+QTYSZL_F>0', '其他应收款在期末较上年同期有所减少，考虑是否因为资金回收、坏账处置引起。若因处置引起，则建议管理层重点关注处置的原因、必要性及结果，是否损害公司利益。同时，需关注剩余的其他应收款是否属于关联交易，若是，需考虑企业短期内是否有IPO计划，如有，则可能对企业的IPO造成不利影响。其他应收款中有Rmb{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}万元账龄已超360日，对账龄超过1年的其他应收款需引起管理层的重视，建议管理层查看该部分较长账龄的其他应收款是否属于关联交易，并确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}', NULL, '11004', NULL, 2411);
INSERT INTO `t_mode` VALUES (2412, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1<0&&QTYSZL_D+QTYSZL_E+QTYSZL_F==0', '其他应收款在期末较上年同期有所减少，考虑是否因为资金回收、坏账处置引起。若因处置引起，则建议管理层重点关注处置的原因、必要性及结果，是否损害公司利益。同时，需关注剩余的其他应收款是否属于关联交易，若是，需考虑企业短期内是否有IPO计划，如有，则可能对企业的IPO造成不利影响。', '', NULL, '11004', NULL, 2412);
INSERT INTO `t_mode` VALUES (2413, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1==0&&QTYSZL_D+QTYSZL_E+QTYSZL_F>0', '其他应收款在期末与上年同期持平，建议管理层查看其他应收款明细及相应信息。其他应收款为年度审计、IPO审计、银行贷款的重点关注科目，建议管理层高度重视。其他应收款中有Rmb{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}万元账龄已超360日，对账龄超过1年的其他应收款需引起管理层的重视，建议管理层查看该部分较长账龄的其他应收款是否属于关联交易，并确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}', NULL, '11004', NULL, 2413);
INSERT INTO `t_mode` VALUES (2414, '1', '其他应收款预警', 'ZCFZ_N-ZCFZ_N1==0&&QTYSZL_D+QTYSZL_E+QTYSZL_F==0', '其他应收款在期末与上年同期持平，建议管理层查看其他应收款明细及相应信息。其他应收款为年度审计、IPO审计、银行贷款的重点关注科目，建议管理层高度重视。', '', NULL, '11004', NULL, 2414);
INSERT INTO `t_mode` VALUES (2415, '1', '存货预警', 'ZCFZ_P-ZCFZ_P1>0&&YBLFX_N>60&&CHKL_D+CHKL_E+CHKL_F>0', '本期末存货有所增加，考虑是否存在存货积压情况。建议管理层扩大销售渠道，增大销售额，同时合理安排原材料的采购时间和生产计划时间，通过设立安全库存等方式，尽量做到库存不积压，优化现金流管理。存货周转天数>60天，资金占用水平较高，流动性偏弱，存货转化为现金或应收帐款的速度就较慢，削弱了企业的短期偿债能力及获利能力。建议管理层关注存货管理中存在的问题，结合生产销售计划，尽可能降低存货的资金占用水平。期末存货中库龄超360日的存货有Rmb{(CHKL_D+CHKL_E+CHKL_F)/10000}万元。库龄超过1年的存货需引起管理层的重视，建议管理层查看该部分较长账龄的存货是否属于滞销产品和相关原材料，并确认其出售可能性，根据市场动态择优选择对自身最有利的方案，并进行相应账务处理。', '{(CHKL_D+CHKL_E+CHKL_F)/10000}', NULL, '11005', NULL, 2415);
INSERT INTO `t_mode` VALUES (2416, '1', '存货预警', 'ZCFZ_P-ZCFZ_P1>0&&YBLFX_N>60&&CHKL_D+CHKL_E+CHKL_F==0', '本期末存货有所增加，考虑是否存在存货积压情况。建议管理层扩大销售渠道，增大销售额，同时合理安排原材料的采购时间和生产计划时间，通过设立安全库存等方式，尽量做到库存不积压，优化现金流管理。存货周转天数>60天，资金占用水平较高，流动性偏弱，存货转化为现金或应收帐款的速度就较慢，削弱了企业的短期偿债能力及获利能力。建议管理层关注存货管理中存在的问题，结合生产销售计划，尽可能降低存货的资金占用水平。', '', NULL, '11005', NULL, 2416);
INSERT INTO `t_mode` VALUES (2417, '1', '存货预警', 'ZCFZ_P-ZCFZ_P1>0&&YBLFX_N<=60&&CHKL_D+CHKL_E+CHKL_F>0', '本期末存货有所增加，考虑是否存在存货积压情况。建议管理层扩大销售渠道，增大销售额，同时合理安排原材料的采购时间和生产计划时间，通过设立安全库存等方式，尽量做到库存不积压，优化现金流管理。期末存货中库龄超360日的存货有Rmb{(CHKL_D+CHKL_E+CHKL_F)/10000}万元。库龄超过1年的存货需引起管理层的重视，建议管理层查看该部分较长账龄的存货是否属于滞销产品和相关原材料，并确认其出售可能性，根据市场动态择优选择对自身最有利的方案，并进行相应账务处理。', '{(CHKL_D+CHKL_E+CHKL_F)/10000}', NULL, '11005', NULL, 2417);
INSERT INTO `t_mode` VALUES (2418, '1', '存货预警', 'ZCFZ_P-ZCFZ_P1>0&&YBLFX_N<=60&&CHKL_D+CHKL_E+CHKL_F==0', '本期末存货有所增加，考虑是否存在存货积压情况。建议管理层扩大销售渠道，增大销售额，同时合理安排原材料的采购时间和生产计划时间，通过设立安全库存等方式，尽量做到库存不积压，优化现金流管理。', '', NULL, '11005', NULL, 2418);
INSERT INTO `t_mode` VALUES (2419, '1', '存货预警', 'ZCFZ_P-ZCFZ_P1<0&&YBLFX_N>60&&CHKL_D+CHKL_E+CHKL_F>0', '存货大幅度减少，考虑是否存在因销售额降低从而导致原材料的采购量降低或因销售额大增而导致产成品不足情形。若销售额降低，则建议管理层扩大销售渠道，增大销售额；若产成品不足，则建议管理层合理安排原材料的采购时间和生产计划时间，保障库存充足。存货周转天数>60天，资金占用水平较高，流动性偏弱，存货转化为现金或应收帐款的速度就较慢，削弱了企业的短期偿债能力及获利能力。建议管理层关注存货管理中存在的问题，结合生产销售计划，尽可能降低存货的资金占用水平。期末存货中库龄超360日的存货有Rmb{(CHKL_D+CHKL_E+CHKL_F)/10000}万元。账龄超过1年的存货需引起管理层的重视，建议管理层查看该部分较长账龄的存货是否属于滞销产品和相关原材料，并确认其出售可能性，根据市场动态择优选择对自身最有利的方案，并进行相应账务处理。', '{(CHKL_D+CHKL_E+CHKL_F)/10000}', NULL, '11005', NULL, 2419);
