INSERT INTO `t_mode` VALUES (2427, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1>0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层相对提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。但要留意，过度集中的采购，对企业存在风险，管理层需在两者之间取得平衡。在应付账款中，账龄超360日的应付账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}万元。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任及确认违约时间点等问题，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, '11006', NULL, 2427);
INSERT INTO `t_mode` VALUES (2428, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1>0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层相对提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。但要留意，过度集中的采购，对企业存在风险，管理层需在两者之间取得平衡。', '', NULL, '11006', NULL, 2428);
INSERT INTO `t_mode` VALUES (2429, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1>0&&YBLFX_O>=60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。在应付账款中，账龄超360日的应付账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}万元。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任及确认违约时间点等问题，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, '11006', NULL, 2429);
INSERT INTO `t_mode` VALUES (2430, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1>0&&YBLFX_O>=60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。', '', NULL, '11006', NULL, 2430);
INSERT INTO `t_mode` VALUES (2431, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1<0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '应付账款有所减少，管理层需关注减少原因及还款后企业现金流是否充足。此外，建议管理层与采购部查看针对主要供应商的付款数期变化，如应付账款的减少是因为数期缩短导致，管理层需考虑与供应商就数期问题进行协商，尽量延长付款周期。同时，建议管理层检查是否按要求设立备查薄，方便管理。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。在应付账款中，账龄超360日的应收账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任等，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, '11006', NULL, 2431);
