INSERT INTO `t_mode` VALUES (2435, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1==0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '应付账款与上年同期持平。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。在应付账款中，账龄超360日的应收账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任等，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, '11006', NULL, 2435);
INSERT INTO `t_mode` VALUES (2436, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1==0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '应付账款与上年同期持平。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。', '', NULL, '11006', NULL, 2436);
INSERT INTO `t_mode` VALUES (2437, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1==0&&YBLFX_O>=60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '应付账款与上年同期持平。在应付账款中，账龄超360日的应收账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任等，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, '11006', NULL, 2437);
INSERT INTO `t_mode` VALUES (2438, '1', '应付账款预警', 'ZCFZ_AV-ZCFZ_AV1==0&&YBLFX_O>=60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '应付账款与上年同期持平。', '', NULL, '11006', NULL, 2438);
INSERT INTO `t_mode` VALUES (2439, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F>0', '预收款项有所增加，建议管理层结合本系统的收入分析及应收账款分析等模块，如呈反趋势增长，需与销售部门分析预收账款增加的原因，是否有合同条款的调整，同时分析调整收款条件对维护客户关系可能产生的影响。此外，在同等销售规模前提下，改应收为预收，实际上对企业现金流有良性作用，建议管理层在不影响客户关系的前提下，适当增加销售预收。在预收账款中，账龄超360日的预收账款余额为Rmb{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}万元。针对账龄超1年的预收账款，建议管理层结合销售合同，关注是否存在收入核算时点、计量金额不准确的问题。此外，建议管理层评估款该部分账龄较长之应收款项是否仍需发货或支付返还，并进行相应的账务处理。', '{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}', NULL, '11007', NULL, 2439);
INSERT INTO `t_mode` VALUES (2440, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F==0', '预收款项有所增加，建议管理层结合本系统的收入分析及应收账款分析等模块，如呈反趋势增长，需与销售部门分析预收账款增加的原因，是否有合同条款的调整，同时分析调整收款条件对维护客户关系可能产生的影响。此外，在同等销售规模前提下，改应收为预收，实际上对企业现金流有良性作用，建议管理层在不影响客户关系的前提下，适当增加销售预收。', '', NULL, '11007', NULL, 2440);
INSERT INTO `t_mode` VALUES (2441, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1<0&&YSKXZL_D+YSKXZL_E+YSKXZL_F>0', '预收款项有所减少，首先需考虑是否与收入变动趋势一致，在不一致的情况下，需重点分析其减少原因。建议管理层与销售部门查看销售合同，并结合市场大环境，考虑预收款项的减少是否因产业经济环境下滑导致下游客户转嫁资金时间成本，合同收款条款进行了修改引起。在预收款项中，账龄超360日的预收款项余额为Rmb{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}万元。针对账龄超1年的预收款项，建议管理层结合销售合同，关注是否存在收入核算时点、计量金额不准确的问题。若不存在核算问题，则建议管理层关注是否因逾期1年的预收账款减少导致预收账款整体减少。若是，则建议继续跟进逾期1年预收账款减少是因转入收入还是因我司无法发货导致退款，若因我司无法发货导致退款，则需重点关注违约风险以及退款对我司资金流的影响。若否，则建议管理层重点关注逾期1年预收账款涉及的销售合同中收款方式、发货时点、违约责任等相关条款，若我司存在收到预收款后违约发货问题，则需评估违约风险对公司的不利影响。', '{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}', NULL, '11007', NULL, 2441);
INSERT INTO `t_mode` VALUES (2442, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1<0&&YSKXZL_D+YSKXZL_E+YSKXZL_F==0', '预收款项有所减少，首先需考虑是否与收入变动趋势一致，在不一致的情况下，需重点分析其减少原因。建议管理层与销售部门查看销售合同，并结合市场大环境，考虑预收款项的减少是否因产业经济环境下滑导致下游客户转嫁资金时间成本，合同收款条款进行了修改引起。', '', NULL, '11007', NULL, 2442);
INSERT INTO `t_mode` VALUES (2443, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1==0&&YSKXZL_D+YSKXZL_E+YSKXZL_F>0', '预收款项与上年同期持平。在预收款项中，账龄超360日的预收款项余额为Rmb{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}万元。针对账龄超1年的预收款项，建议管理层结合销售合同，关注是否存在收入核算时点、计量金额不准确的问题。此外，建议管理层评估款该部分账龄较长之应收款项是否仍需发货或支付返还，并进行相应的账务处理。', '', NULL, '11007', NULL, 2443);
INSERT INTO `t_mode` VALUES (2444, '1', '预收款项预警', 'ZCFZ_AW-ZCFZ_AW1==0&&YSKXZL_D+YSKXZL_E+YSKXZL_F==0', '预收款项与上年同期持平。', '', NULL, '11007', NULL, 2444);
INSERT INTO `t_mode` VALUES (2445, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F>0', '其他应付款的有所增加，需考虑对未来偿还款项的资金风险。建议管理层查看增长幅度较大的其他应付款的合同，留意其中的偿还条款，根据本系统货币资金模块中的货币资金预警分析未来期间内是否会对资金造成影响。如为关联企业之间的资金拆借，需与企业未来发展相结合，如在短期内有上市计划，则需对其进行清理，如无，则需考虑关联企业之间的资金拆解是否符合相关的法律及监管条例的约束，例如：借款利率是否符合法律法规的要求；如为无息贷款，是否符合税法的要求。其他应付款中，账龄超360日的其他应付款余额为Rmb{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}万元。针对账龄超1年的其他应付款，建议管理层分析其是否属于关联方往来，并预估需付款的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流等方式，择优选择对自身最有利的方案，以防出现现金断流情况。', '{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}', NULL, '11008', NULL, 2445);
INSERT INTO `t_mode` VALUES (2446, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F==0', '其他应付款的有所增加，需考虑对未来偿还款项的资金风险。建议管理层查看增长幅度较大的其他应付款的合同，留意其中的偿还条款，根据本系统货币资金模块中的货币资金预警分析未来期间内是否会对资金造成影响。如为关联企业之间的资金拆借，需与企业未来发展相结合，如在短期内有上市计划，则需对其进行清理，如无，则需考虑关联企业之间的资金拆解是否符合相关的法律及监管条例的约束，例如：借款利率是否符合法律法规的要求；如为无息贷款，是否符合税法的要求。', '', NULL, '11008', NULL, 2446);
INSERT INTO `t_mode` VALUES (2447, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1<0&&QTYFZL_D+QTYFZL_E+QTYFZL_F>0', '其他应付款有所减少，需关注当前的资金状况是否充裕。此外，其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。在其他应付账款中，账龄超360日的其他应付款余额为Rmb{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}万元。针对账龄超1年的其他应付款，建议管理层分析其是否属于关联交易，并预估需付款的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流等方式，择优选择对自身最有利的方案，以防出现现金断流情况。', '{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}', NULL, '11008', NULL, 2447);
INSERT INTO `t_mode` VALUES (2448, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1<0&&QTYFZL_D+QTYFZL_E+QTYFZL_F==0', '其他应付款有所减少，需关注当前的资金状况是否充裕。此外，其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。', '', NULL, '11008', NULL, 2448);
INSERT INTO `t_mode` VALUES (2449, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1==0&&QTYFZL_D+QTYFZL_E+QTYFZL_F>0', '其他应付款与上年同期持平。其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。在其他应付账款中，账龄超360日的其他应付款余额为Rmb{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}万元。针对账龄超1年的其他应付款，建议管理层分析其是否属于关联交易，并预估需付款的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流等方式，择优选择对自身最有利的方案，以防出现现金断流情况。', '{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}', NULL, '11008', NULL, 2449);
INSERT INTO `t_mode` VALUES (2450, '1', '其他应付款', 'ZCFZ_BD-ZCFZ_BD1==0&&QTYFZL_D+QTYFZL_E+QTYFZL_F==0', '其他应付款与上年同期持平。其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。', '', NULL, '11008', NULL, 2450);
INSERT INTO `t_mode` VALUES (2451, '2', '营业收入预警', 'LR_A1!=0&& LR_A-LR_A1>0&&LR_A/XSSL_A-LR_A1/XSSL_A1>0&& (LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '营业收入本期比上年同期增长{(LR_A-LR_A1)/LR_A1*100}%，主要是因为平均销售单价的上升。建议管理层与销售部分析销售单价上涨的产品及地区，评估产品群对价格上涨的接受程度，考虑是否所有产品均可涨价，抑或存在一定的局限性。如果单价上涨主要由于针对某一大产品，需考虑单价上涨对双方长期合作关系可能产生的影响。评估竞争对手的价格与企业相比是否具有较强的价格竞争力，企业的涨价行为是否会因此造成客源的流失。', '{(LR_A-LR_A1)/LR_A1*100}', NULL, '20001', NULL, 2451);
INSERT INTO `t_mode` VALUES (2452, '2', '营业收入预警', 'LR_A1!=0&& LR_A-LR_A1>0&&XSSL_A-XSSL_A1>0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)>0', '营业收入本期比上年同期增长{(LR_A-LR_A1)/LR_A1*100}%，主要是因为销售量的大幅度增加。建议管理层与销售部分析销售量增长幅度最大的区域及产品，与市场部研究其增长模式是否可以在其他区域或产品中进行复制。同时，考虑销售量的增长是否具有可持续性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长。', '{(LR_A-LR_A1)/LR_A1*100}', NULL, '20001', NULL, 2452);
INSERT INTO `t_mode` VALUES (2453, '2', '营业收入预警', 'LR_A1==0&& LR_A-LR_A1>0&&LR_A/XSSL_A-LR_A1/XSSL_A1>0&& (LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '营业收入本期比上年同期增长-%，主要是因为平均销售单价的上升。建议管理层与销售部分析销售单价上涨的产品及地区，评估产品群对价格上涨的接受程度，考虑是否所有产品均可涨价，抑或存在一定的局限性。如果单价上涨主要由于针对某一大产品，需考虑单价上涨对双方长期合作关系可能产生的影响。评估竞争对手的价格与企业相比是否具有较强的价格竞争力，企业的涨价行为是否会因此造成客源的流失。', '', NULL, '20001', NULL, 2453);
INSERT INTO `t_mode` VALUES (2454, '2', '营业收入预警', 'LR_A1==0&& LR_A-LR_A1>0&&XSSL_A-XSSL_A1>0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)>0', '营业收入本期比上年同期增长-%，主要是因为销售量的大幅度增加。建议管理层与销售部分析销售量增长幅度最大的区域及产品，与市场部研究其增长模式是否可以在其他区域或产品中进行复制。同时，考虑销售量的增长是否具有可持续性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长。', '', NULL, '20001', NULL, 2454);
INSERT INTO `t_mode` VALUES (2455, '2', '营业收入预警', 'LR_A-LR_A1<0&&LR_A/XSSL_A-LR_A1/XSSL_A1<0&& (LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '营业收入本期比上年同期减少{(LR_A1-LR_A)/LR_A1*100}%，主要是因为平均销售单价的降低。建议管理层与销售部分析销售单价降低的产品及地区，评估产品群对价格的敏感性，考虑是否所有产品均可适当涨价，提高企业利润。如果单价降低主要由于针对某一大产品，需考虑单价降低对双方长期合作关系可能产生的影响及评估该措施的利弊。同时，评估竞争对手的价格与企业相比是否具有较强的价格竞争力，后期企业的涨价行为是否会因此造成客源的流失。', '{(LR_A1-LR_A)/LR_A1*100}', NULL, '20001', NULL, 2455);
INSERT INTO `t_mode` VALUES (2456, '2', '营业收入预警', 'LR_A-LR_A1<0&&XSSL_A-XSSL_A1<0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)<0', '营业收入本期比上年同期减少{(LR_A1-LR_A)/LR_A1*100}%，主要是因为销售量的大幅度降低。建议管理层与销售部分析销售量降低幅度最大的区域及产品，与市场部研究其降低原因，考虑销售量的降低是否具有不可逆转性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长，维持市场份额。', '{(LR_A1-LR_A)/LR_A1*100}', NULL, '20001', NULL, 2456);
INSERT INTO `t_mode` VALUES (2457, '2', '营业收入预警', 'LR_A-LR_A1==0', '营业收入本期与上期持平，此情况较为特殊，建议管理层核对数据是否正确，如无误，需结合本系统中具体科目的详细分析，考虑以下问题：1. 营业收入与应收账款变动趋势是否一致，如存在应收账款仍然不断增加，但是营业收入则两期不变的情况，管理层需高度重视现金流状况，结合本系统中未来6个月货币资金的预测图，查看未来是否存在资金紧缺的情况，相应对应收账款进行催收，增大现金流。', '', NULL, '20001', NULL, 2457);
INSERT INTO `t_mode` VALUES (2674, '2', '销售费用预警', 'LR_A!=0&&LR_A1!=0', '本期销售费用占营业收入的比率为{LR_P/LR_A*100}%，上年同期该比率为{LR_P1/LR_A1*100}%。', '{LR_P/LR_A*100},{LR_P1/LR_A1*100}', NULL, 'G20004', NULL, 2674);
INSERT INTO `t_mode` VALUES (2675, '2', '销售费用预警', 'LR_A!=0&&LR_A1==0', '本期销售费用占营业收入的比率为{LR_P/LR_A*100}%，上年同期该比率为-%。', '{LR_P/LR_A*100}', NULL, 'G20004', NULL, 2675);
INSERT INTO `t_mode` VALUES (2676, '2', '销售费用预警', 'LR_A==0&&LR_A1!=0', '本期销售费用占营业收入的比率为-%，上年同期该比率为{LR_P1/LR_A1*100}%。', '{LR_P1/LR_A1*100}', NULL, 'G20004', NULL, 2676);
INSERT INTO `t_mode` VALUES (2677, '2', '销售费用预警', 'LR_A==0&&LR_A1==0', '本期销售费用占营业收入的比率为-%，上年同期该比率为-%。', '', NULL, 'G20004', NULL, 2677);
INSERT INTO `t_mode` VALUES (2678, '2', '销售费用预警', '1-1==0', '建议管理层关注销售费用的变动趋势是否与收入变化趋势一致，从而考虑目前的销售部门的激励政策、市场策略、销售政策是否达到预期的效果。建议管理层与销售部门研讨市场开拓的投入是否将在未来体现，同时，研究市场开拓的成本控制问题，可考虑将市场开拓成本与销售情况的匹配程度作为销售人员的工资调整KPI ，以达到控制市场开拓成本的目的。同时，对于不必要的市场开拓及广告费用等，进行缩减。', '', NULL, 'G20004', NULL, 2678);
INSERT INTO `t_mode` VALUES (2679, '2', '销售费用预警', 'LR_P1!=0&&                            LR_P-LR_P1>0&& XSFY_RG-XSFY_RG1>0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为销售人工成本的增加。建议管理层查看人工成本增加的原因。如为员工人数增加导致的总体人工金额增加，需考虑销售团队人员数量与销售计划的匹配性；如为销售人员工资构成的调整等因素引起的人工成本的增加，需考虑销售人员的薪酬机制是否合理，是否与市场水平挂钩，薪酬的增加是否达到预期的市场开拓效果。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G20004', NULL, 2679);
INSERT INTO `t_mode` VALUES (2680, '2', '销售费用预警', 'LR_P1!=0&&                            LR_P-LR_P1>0&& XSFY_CL-XSFY_CL1>0&& (XSFY_CL-XSFY_CL1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为差旅费用的大幅度增加。建议管理层查看差旅费用增加幅度与人工成本、销售收入等的总体趋势是否一致，考虑是否需要加强成本费用的控制。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G20004', NULL, 2680);
INSERT INTO `t_mode` VALUES (2681, '2', '销售费用预警', 'LR_P1!=0&&                            LR_P-LR_P1>0&& XSFY_TG-XSFY_TG1>0&& (XSFY_TG-XSFY_TG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为广告费、促销费、推广费、设计费支出的增加。建议管理层查看广告及促销费用增加的趋势与销售收入的变动趋势是否一致，评估费用增加对收入的影响，是否带来了预期的市场效果，从而考虑是否需要调整市场开拓方针。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G20004', NULL, 2681);
INSERT INTO `t_mode` VALUES (2682, '2', '销售费用预警', 'LR_P1!=0&&                            LR_P-LR_P1>0&& XSFY_ZD-XSFY_ZD1>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为业务招待费的增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G20004', NULL, 2682);
INSERT INTO `t_mode` VALUES (2683, '2', '销售费用预警', 'LR_P1!=0&&                            LR_P-LR_P1>0&& XSFY_QT-XSFY_QT1>0&& (XSFY_QT-XSFY_QT1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_RG-XSFY_RG1)>0', '销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要由除人工、差旅、市场推广、业务招待等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后的费用增长。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G20004', NULL, 2683);
INSERT INTO `t_mode` VALUES (2684, '2', '销售费用预警', 'LR_P1==0&&                            LR_P-LR_P1>0&& XSFY_RG-XSFY_RG1>0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长-%，主要是因为销售人工成本的增加。建议管理层查看人工成本增加的原因。如为员工人数增加导致的总体人工金额增加，需考虑销售团队人员数量与销售计划的匹配性；如为销售人员工资构成的调整等因素引起的人工成本的增加，需考虑销售人员的薪酬机制是否合理，是否与市场水平挂钩，薪酬的增加是否达到预期的市场开拓效果。', '', NULL, 'G20004', NULL, 2684);
INSERT INTO `t_mode` VALUES (2685, '2', '销售费用预警', 'LR_P1==0&&                            LR_P-LR_P1>0&& XSFY_CL-XSFY_CL1>0&& (XSFY_CL-XSFY_CL1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长-%，主要是因为差旅费用的大幅度增加。建议管理层查看差旅费用增加幅度与人工成本、销售收入等的总体趋势是否一致，考虑是否需要加强成本费用的控制。', '', NULL, 'G20004', NULL, 2685);
INSERT INTO `t_mode` VALUES (2686, '2', '销售费用预警', 'LR_P1==0&&                            LR_P-LR_P1>0&& XSFY_TG-XSFY_TG1>0&& (XSFY_TG-XSFY_TG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长-%，主要是因为广告费、促销费、推广费、设计费支出的增加。建议管理层查看广告及促销费用增加的趋势与销售收入的变动趋势是否一致，评估费用增加对收入的影响，是否带来了预期的市场效果，从而考虑是否需要调整市场开拓方针。', '', NULL, 'G20004', NULL, 2686);
INSERT INTO `t_mode` VALUES (2687, '2', '销售费用预警', 'LR_P1==0&&                            LR_P-LR_P1>0&& XSFY_ZD-XSFY_ZD1>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_QT-XSFY_QT1)>0', '销售费用本期比上年同期增长-%，主要是因为业务招待费的增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '', NULL, 'G20004', NULL, 2687);
INSERT INTO `t_mode` VALUES (2688, '2', '销售费用预警', 'LR_P1==0&&                            LR_P-LR_P1>0&& XSFY_QT-XSFY_QT1>0&& (XSFY_QT-XSFY_QT1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_RG-XSFY_RG1)>0', '销售费用本期比上年同期增长-%，主要由除人工、差旅、市场推广、业务招待等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后的费用增长。', '', NULL, 'G20004', NULL, 2688);
INSERT INTO `t_mode` VALUES (2689, '2', '销售费用预警', 'LR_P-LR_P1<0&& XSFY_RG-XSFY_RG1<0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)<0', '销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要是因为销售人工成本的减少。建议管理层查看人工成本减少的原因。如为员工人数减少导致的总体人工金额减少，需考虑销售团队人员的调整对销售计划已经未来销售收入的总体影响；如为销售人员工资构成的调整等因素引起的人工成本的减少，需考虑销售人员对薪酬机制的满意程度以及可能引起的人员流动，从而评估销售人员流动对销售收入及增长可能产生的影响。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G20004', NULL, 2689);
INSERT INTO `t_mode` VALUES (2690, '2', '销售费用预警', 'LR_P-LR_P1<0&& XSFY_CL-XSFY_CL1<0&& (XSFY_CL-XSFY_CL1)-(XSFY_RG-XSFY_RG1)<0&& (XSFY_CL-XSFY_CL1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_CL-XSFY_CL1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_CL-XSFY_CL1)-(XSFY_QT-XSFY_QT1)<0', '销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要是因为差旅费用的大幅度减少。建议管理层查看差旅费用减少幅度与人工成本、销售收入等的总体趋势是否一致，考虑是否需要加大市场开拓的力度，调整市场开拓的方式。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G20004', NULL, 2690);
INSERT INTO `t_mode` VALUES (2691, '2', '销售费用预警', 'LR_P-LR_P1<0&& XSFY_TG-XSFY_TG1<0&& (XSFY_TG-XSFY_TG1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_TG-XSFY_TG1)-(XSFY_RG-XSFY_RG1)<0&& (XSFY_TG-XSFY_TG1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_TG-XSFY_TG1)-(XSFY_QT-XSFY_QT1)<0', '销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要是因为广告费、促销费、推广费、设计费支出的减少。建议管理层查看广告及促销费用减少的趋势与销售收入的变动趋势是否一致，评估费用缩减对收入的影响，从而考虑是否需要调整市场开拓方针。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G20004', NULL, 2691);
INSERT INTO `t_mode` VALUES (2692, '2', '销售费用预警', 'LR_P-LR_P1<0&& XSFY_ZD-XSFY_ZD1<0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_RG-XSFY_RG1)<0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_QT-XSFY_QT1)<0', '销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要是因为业务招待费的减少。建议管理层关注业务招待费降低的主要原因，如外部形势好，无需大量的公共支出或内部费用控制合理，并评估费用进一步压缩的可能性。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G20004', NULL, 2692);
INSERT INTO `t_mode` VALUES (2693, '2', '销售费用预警', 'LR_P-LR_P1<0&& XSFY_QT-XSFY_QT1<0&& (XSFY_QT-XSFY_QT1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_RG-XSFY_RG1)<0', '销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要由除人工、差旅、市场推广、业务招待等主要项目外的剩余支出减少所导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后的费用减少。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G20004', NULL, 2693);
INSERT INTO `t_mode` VALUES (2694, '2', '销售费用预警', 'LR_P-LR_P1==0', '销售费用本期与上期持平，此现象较为特殊，建议管理层在确认数据无误的情况下，分析两期费用构成的变动，对于波动较大的明细科目，需重点关注其变动原因，其存在风险，可通过本系统咨询模块向专业顾问进行沟通咨询。', '', NULL, 'G20004', NULL, 2694);
INSERT INTO `t_mode` VALUES (2695, '2', '管理费用预警', 'LR_A!=0&&LR_A1!=0', '本期管理费用占营业收入的比率为{LR_Q/LR_A*100}%，上年同期该比率为{LR_Q1/LR_A1*100}%。建议管理层关注管理费用的变动趋势是否与收入变化趋势一致，从而考虑目前的管理部门的成本控制是否合理。', '{LR_Q/LR_A*100},{LR_Q1/LR_A1*100}', NULL, 'G20007', NULL, 2695);
INSERT INTO `t_mode` VALUES (2696, '2', '管理费用预警', 'LR_A!=0&&LR_A1==0', '本期管理费用占营业收入的比率为{LR_Q/LR_A*100}%，上年同期该比率为-%。建议管理层关注管理费用的变动趋势是否与收入变化趋势一致，从而考虑目前的管理部门的成本控制是否合理。', '{LR_Q/LR_A*100}', NULL, 'G20007', NULL, 2696);
INSERT INTO `t_mode` VALUES (2697, '2', '管理费用预警', 'LR_A==0&&LR_A1!=0', '本期管理费用占营业收入的比率为-%，上年同期该比率为{LR_Q1/LR_A1*100}%。建议管理层关注管理费用的变动趋势是否与收入变化趋势一致，从而考虑目前的管理部门的成本控制是否合理。', '{LR_Q1/LR_A1*100}', NULL, 'G20007', NULL, 2697);
INSERT INTO `t_mode` VALUES (2698, '2', '管理费用预警', 'LR_A==0&&LR_A1==0', '本期管理费用占营业收入的比率为-%，上年同期该比率为-%。建议管理层关注管理费用的变动趋势是否与收入变化趋势一致，从而考虑目前的管理部门的成本控制是否合理。', '', NULL, 'G20007', NULL, 2698);
INSERT INTO `t_mode` VALUES (2699, '2', '管理费用预警', 'LR_Q1!=0&&LR_Q-LR_Q1>0&& GLFY_RG-GLFY_RG1>0&&(GLFY_RG-GLFY_RG1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是因为管理人员人工成本增加。建议管理层查看工资上涨的原因，与人力资源部门讨论控制工资上涨的方式。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G20007', NULL, 2699);
INSERT INTO `t_mode` VALUES (2700, '2', '管理费用预警', 'LR_Q1!=0&&LR_Q-LR_Q1>0&& GLFY_ZJ-GLFY_ZJ1>0&&(GLFY_ZJ-GLFY_ZJ1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是因为办公用固定资产大幅度增加，导致折旧金额相应增加，建议管理层做好固定资产管理，包括固定资产卡片，台账等的管理等。此外，建议管理层评估大幅度增加管理用固定资产的必要性，做好支出管理。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G20007', NULL, 2700);
INSERT INTO `t_mode` VALUES (2701, '2', '管理费用预警', 'LR_Q1!=0&&LR_Q-LR_Q1>0&& GLFY_ZD-GLFY_ZD1>0&&(GLFY_ZD-GLFY_ZD1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是因为业务招待费增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G20007', NULL, 2701);
INSERT INTO `t_mode` VALUES (2702, '2', '管理费用预警', 'LR_Q1!=0&&LR_Q-LR_Q1>0&& GLFY_QT-GLFY_QT1>0&&(GLFY_QT-GLFY_QT1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZD-GLFY_ZD1)>0', '管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是由于除人工、折旧、业务招待外的剩余支出的增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层采用本系统在线顾问服务模块中的顾问咨询功能，对可能存在或延续的问题咨询专家意见。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G20007', NULL, 2702);
INSERT INTO `t_mode` VALUES (2703, '2', '管理费用预警', 'LR_Q1==0&&LR_Q-LR_Q1>0&& GLFY_RG-GLFY_RG1>0&&(GLFY_RG-GLFY_RG1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长-%，主要是因为管理人员人工成本增加。建议管理层查看工资上涨的原因，与人力资源部门讨论控制工资上涨的方式。', '', NULL, 'G20007', NULL, 2703);
INSERT INTO `t_mode` VALUES (2704, '2', '管理费用预警', 'LR_Q1==0&&LR_Q-LR_Q1>0&& GLFY_ZJ-GLFY_ZJ1>0&&(GLFY_ZJ-GLFY_ZJ1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长-%，主要是因为办公用固定资产大幅度增加，导致折旧金额相应增加，建议管理层做好固定资产管理，包括固定资产卡片，台账等的管理等。此外，建议管理层评估大幅度增加管理用固定资产的必要性，做好支出管理。', '', NULL, 'G20007', NULL, 2704);
INSERT INTO `t_mode` VALUES (2705, '2', '管理费用预警', 'LR_Q1==0&&LR_Q-LR_Q1>0&& GLFY_ZD-GLFY_ZD1>0&&(GLFY_ZD-GLFY_ZD1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_QT-GLFY_QT1)>0', '管理费用本期比上年同期增长-%，主要是因为业务招待费增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '', NULL, 'G20007', NULL, 2705);
INSERT INTO `t_mode` VALUES (2706, '2', '管理费用预警', 'LR_Q1==0&& LR_Q-LR_Q1>0&&GLFY_QT-GLFY_QT1>0&&(GLFY_QT-GLFY_QT1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZD-GLFY_ZD1)>0', '管理费用本期比上年同期增长-%，主要是由于除人工、折旧、业务招待外的剩余支出的增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层采用本系统在线顾问服务模块中的顾问咨询功能，对可能存在或延续的问题咨询专家意见。', '', NULL, 'G20007', NULL, 2706);
INSERT INTO `t_mode` VALUES (2707, '2', '管理费用预警', 'LR_Q-LR_Q1<0&& GLFY_RG-GLFY_RG1<0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZJ-GLFY_ZJ1)<0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZD-GLFY_ZD1)<0&& (GLFY_RG-GLFY_RG1)-(GLFY_QT-GLFY_QT1)<0', '管理费用本期比上年同期减少{(LR_Q1-LR_Q)/LR_Q1*100}%，主要是因为管理人员人工成本减少。建议管理层查看人工减少的原因，考虑未来人员配置的调整，并评估对净利润以及现金流的影响。', '{(LR_Q1-LR_Q)/LR_Q1*100}', NULL, 'G20007', NULL, 2707);
INSERT INTO `t_mode` VALUES (2708, '2', '管理费用预警', 'LR_Q-LR_Q1<0&& GLFY_ZJ-GLFY_ZJ1<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_RG-GLFY_RG1)<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_ZD-GLFY_ZD1)<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_QT-GLFY_QT1)<0', '管理费用本期比上年同期减少{(LR_Q1-LR_Q)/LR_Q1*100}%，主要是因为折旧减少。建议管理层查看折旧减少原因，如本年内大量报废办公设备，需考虑未来的固定资产购置计划，以及办公设备的购置对现金流以及净利润的影响。', '{(LR_Q1-LR_Q)/LR_Q1*100}', NULL, 'G20007', NULL, 2708);
INSERT INTO `t_mode` VALUES (2709, '2', '管理费用预警', 'LR_Q-LR_Q1<0&& GLFY_ZD-GLFY_ZD1<0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_RG-GLFY_RG1)<0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_ZJ-GLFY_ZJ1)<0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_QT-GLFY_QT1)<0', '管理费用本期比上年同期减少{(LR_Q1-LR_Q)/LR_Q1*100}%，主要是因为业务招待费减少。建议管理层关注业务招待费降低的主要原因，如外部形势好，无需大量的公共支出或内部费用控制合理，并评估费用进一步压缩的可能性。', '{(LR_Q1-LR_Q)/LR_Q1*100}', NULL, 'G20007', NULL, 2709);
INSERT INTO `t_mode` VALUES (2710, '2', '管理费用预警', 'LR_Q-LR_Q1<0&& GLFY_QT-GLFY_QT1<0&& (GLFY_QT-GLFY_QT1)-(GLFY_RG-GLFY_RG1)<0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZJ-GLFY_ZJ1)<0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZD-GLFY_ZD1)<0', '管理费用本期比上年同期减少{(LR_Q1-LR_Q)/LR_Q1*100}%，主要是由于除人工、折旧、业务招待外的剩余支出的减少导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，应扣除这一事项后进行分析。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。', '{(LR_Q1-LR_Q)/LR_Q1*100}', NULL, 'G20007', NULL, 2710);
INSERT INTO `t_mode` VALUES (2711, '2', '管理费用预警', 'LR_Q-LR_Q1==0', '管理费用本期与上期一致，此情况较为特殊，建议管理层在确认数据无误的情况下，重点关注以下问题：1. 本期与上期是否存在“咨询费用”或者“顾问费用”支出。此类支出为审计重点关注对象，可能涉及因诉讼等产生的支出，因此，如存在此类支出，尤其是在本期比上期支出增长的情况下，管理层需就其增长合理性及可能存在的风险进行分析，如：诉讼是否会产生预计负债等，均为投资者、审计师重点关注问题；2. 针对两期对比变动较大支出类别，需查找原因，了解变动合理性，减少可能存在的风险。建议使用本系统中咨询模块，聘请专业顾问就潜在风险及应对措施等进行咨询。', '', '', 'G20007', '', 2711);
