INSERT INTO `t_mode` VALUES (2756, '2', '营业利润概述', 'LR_Y1-LR_Y>0&&LR_U1-LR_U>0&&(LR_U1-LR_U)-(LR_F-LR_F1)>0&&(LR_U1-LR_U)-(LR_O-LR_O1)>0&&(LR_U1-LR_U)-(LR_P-LR_P1)>0&&(LR_U1-LR_U)-(LR_Q-LR_Q1)>0&&(LR_U1-LR_U)-(LR_R-LR_R1)>0&&(LR_U1-LR_U)-(LR_S-LR_S1)>0&&(LR_U1-LR_U)-(LR_A1-LR_A)>0&&(LR_U1-LR_U)-(LR_T1-LR_T)>0&&(LR_U1-LR_U)-(LR_W1-LR_W)>0&&(LR_U1-LR_U)-(LR_X1-LR_X)>0', '营业利润从上期的Rmb{LR_Y1/10000}万元下降至本期的Rmb{LR_Y/10000}万元，主要是因为投资收益的减少导致。', '{LR_Y1/10000},{LR_Y/10000}', NULL, 'G2016', NULL, 2756);
INSERT INTO `t_mode` VALUES (2757, '2', '营业利润概述', 'LR_Y-LR_Y1>0&&LR_W-LR_W1>0&&(LR_W-LR_W1)-(LR_F1-LR_F)>0&&(LR_W-LR_W1)-(LR_O1-LR_O)>0&&(LR_W-LR_W1)-(LR_P1-LR_P)>0&&(LR_W-LR_W1)-(LR_Q1-LR_Q)>0&&(LR_W-LR_W1)-(LR_R1-LR_R)>0&&(LR_W-LR_W1)-(LR_S1-LR_S)>0&&(LR_W-LR_W1)-(LR_A-LR_A1)>0&&(LR_W-LR_W1)-(LR_T-LR_T1)>0&&(LR_W-LR_W1)-(LR_U-LR_U1)>0&&(LR_W-LR_W1)-(LR_X-LR_X1)>0', '营业利润从上期的Rmb{LR_Y1/10000}万元增长至本期的Rmb{LR_Y/10000}万元，主要是因为汇兑收益的增长导致。', '{LR_Y1/10000},{LR_Y/10000}', NULL, 'G2016', NULL, 2757);
INSERT INTO `t_mode` VALUES (2758, '2', '营业利润概述', 'LR_Y1-LR_Y>0&&LR_W1-LR_W>0&&(LR_W1-LR_W)-(LR_F-LR_F1)>0&&(LR_W1-LR_W)-(LR_O-LR_O1)>0&&(LR_W1-LR_W)-(LR_P-LR_P1)>0&&(LR_W1-LR_W)-(LR_Q-LR_Q1)>0&&(LR_W1-LR_W)-(LR_R-LR_R1)>0&&(LR_W1-LR_W)-(LR_S-LR_S1)>0&&(LR_W1-LR_W)-(LR_A1-LR_A)>0&&(LR_W1-LR_W)-(LR_T1-LR_T)>0&&(LR_W1-LR_W)-(LR_U1-LR_U)>0&&(LR_W1-LR_W)-(LR_X1-LR_X)>0', '营业利润从上期的Rmb{LR_Y1/10000}万元下降至本期的Rmb{LR_Y/10000}万元，主要是因为汇兑收益的减少导致。', '{LR_Y1/10000},{LR_Y/10000}', NULL, 'G2016', NULL, 2758);
INSERT INTO `t_mode` VALUES (2759, '2', '营业利润概述', 'LR_Y-LR_Y1>0&&LR_X-LR_X1>0&&(LR_X-LR_X1)-(LR_F1-LR_F)>0&&(LR_X-LR_X1)-(LR_O1-LR_O)>0&&(LR_X-LR_X1)-(LR_P1-LR_P)>0&&(LR_X-LR_X1)-(LR_Q1-LR_Q)>0&&(LR_X-LR_X1)-(LR_R1-LR_R)>0&&(LR_X-LR_X1)-(LR_S1-LR_S)>0&&(LR_X-LR_X1)-(LR_A-LR_A1)>0&&(LR_X-LR_X1)-(LR_T-LR_T1)>0&&(LR_X-LR_X1)-(LR_U-LR_U1)>0&&(LR_X-LR_X1)-(LR_W-LR_W1)>0', '营业利润从上期的Rmb{LR_Y1/10000}万元增长至本期的Rmb{LR_Y/10000}万元，主要是因为其他收益的增长导致。', '{LR_Y1/10000},{LR_Y/10000}', NULL, 'G2016', NULL, 2759);
INSERT INTO `t_mode` VALUES (2760, '2', '营业利润概述', 'LR_Y1-LR_Y>0&&LR_X1-LR_X>0&&(LR_X1-LR_X)-(LR_F-LR_F1)>0&&(LR_X1-LR_X)-(LR_O-LR_O1)>0&&(LR_X1-LR_X)-(LR_P-LR_P1)>0&&(LR_X1-LR_X)-(LR_Q-LR_Q1)>0&&(LR_X1-LR_X)-(LR_R-LR_R1)>0&&(LR_X1-LR_X)-(LR_S-LR_S1)>0&&(LR_X1-LR_X)-(LR_A1-LR_A)>0&&(LR_X1-LR_X)-(LR_T1-LR_T)>0&&(LR_X1-LR_X)-(LR_U1-LR_U)>0&&(LR_X1-LR_X)-(LR_W1-LR_W)>0', '营业利润从上期的Rmb{LR_Y1/10000}万元下降至本期的Rmb{LR_Y/10000}万元，主要是因为其他收益的减少导致。', '{LR_Y1/10000},{LR_Y/10000}', NULL, 'G2016', NULL, 2760);
INSERT INTO `t_mode` VALUES (2761, '2', '营业利润概述', 'LR_Y-LR_Y1==0', '本期营业利润与上期一致，为Rmb{LR_Y/10000}万元。', '{LR_Y/10000}', NULL, 'G2016', NULL, 2761);
INSERT INTO `t_mode` VALUES (2765, '2', '营业利润预警', 'LR_Y-LR_Y1>0&&LR_Y1<0&&LR_Y>0', '营业利润反映公司正常经营情况下产生的利润，本期营业利润有较大改进，从上期的亏损改善至盈利状态，管理层可维持目前的经营战略，但应注意与现金流情况结合分析，如单纯出现盈利，但现金流仍处于紧张状态，需高度关注，通过改善应收款回收等方式，改善现金流，防止因资金链断裂导致经营困难。', '', NULL, '20018', NULL, 2765);
INSERT INTO `t_mode` VALUES (2766, '2', '营业利润预警', 'LR_Y-LR_Y1>0&&LR_Y1<0&&LR_Y<0', '尽管本期营业利润较上期有所增长，但仍处于亏损状态，建议管理层参考分析模块中各科目存在的重点问题，可就相关问题通过本系统咨询模块咨询专家顾问。', '', NULL, '20018', NULL, 2766);
INSERT INTO `t_mode` VALUES (2767, '2', '营业利润预警', 'LR_Y-LR_Y1>0&&LR_Y1>0', '营业利润本期较上期有所增长，呈较好发展势头，管理层可维持目前的经营策略，但应注意与现金流情况结合分析，避免账面出现利润，但因资金链断链导致无法持续经营的情况出现。建议结合分析模块现金流量表的分析结果，咨询专业顾问，为企业健康发展出谋划策。', '', NULL, '20018', NULL, 2767);
INSERT INTO `t_mode` VALUES (2768, '2', '营业利润预警', 'LR_Y-LR_Y1>0&&LR_Y1==0', '营业利润本期较上期有所增长，呈较好发展势头，管理层可维持目前的经营策略，但应注意与现金流情况结合分析，避免账面出现利润，但因资金链断链导致无法持续经营的情况出现。建议结合分析模块现金流量表的分析结果，咨询专业顾问，为企业健康发展出谋划策。', '', NULL, '20018', NULL, 2768);
INSERT INTO `t_mode` VALUES (2769, '2', '营业利润预警', 'LR_Y1-LR_Y>0&&LR_Y1>0&&LR_Y<0', '营业利润从上期盈利下降至本期亏损状态，管理层需高度警惕，同时结合现金流分析以及分析模块中货币资金的未来6个月现金流情况预测，判断未来短期内现金流是否足以支撑经营，是否需要通过债权或股权融资改善现金流，结合营业收入及营业成本、存货等的分析结果，考虑是否需要调整库存结构，市场开拓方向及策略等。', '', NULL, '20018', NULL, 2769);
INSERT INTO `t_mode` VALUES (2770, '2', '营业利润预警', 'LR_Y1-LR_Y>0&&LR_Y1<0&&LR_Y<0', '营业利润本期及上期均处于亏损状态，且呈下降趋势，管理层需高度警惕。建议在利润表首页分析结果查看变动最大科目及其原因，并进入具体科目查看分析结果，结合现金流分析情况，考虑是否需要通过债权或股权融资改善现金流，并结合营业收入、营业成本等重点科目，以及应收款项等的周转期情况，判断是否需要调整市场及生产策略，建议使用本系统咨询模块向专业顾问进行咨询。', '', NULL, '20018', NULL, 2770);
INSERT INTO `t_mode` VALUES (2771, '2', '营业利润预警', 'LR_Y1-LR_Y>0&&LR_Y>0', '营业利润出现下滑，尽管本期仍维持在盈利状态，但需警惕下滑趋势，建议结合分析模块的各科目具体分析情况，并结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20018', NULL, 2771);
INSERT INTO `t_mode` VALUES (2772, '2', '营业利润预警', 'LR_Y1-LR_Y>0&&LR_Y1==0', '营业利润出现下滑，且本期营业利润变为亏损状态，管理层需高度警惕，建议结合分析模块中收入、成本、费用各科目的分析预警结果，分析出现亏损状态的原因，考虑是否需要调整经营策略，同时结合现金流状况，避免出现因现金流紧张出现资金断链的可能。', '', NULL, '20018', NULL, 2772);
INSERT INTO `t_mode` VALUES (2773, '2', '营业利润预警', 'LR_Y-LR_Y1==0&&LR_Y1>0', '营业利润两期持平，且为盈利状态，建议管理层结合未来经营策略，分析利润的变动趋势与销售费用中市场支出的变动趋势是否一致，如不一致，需考虑市场推广效果是否达预期，是否需要调整市场拓展策略及方式等。', '', NULL, '20018', NULL, 2773);
INSERT INTO `t_mode` VALUES (2774, '2', '营业利润预警', 'LR_Y-LR_Y1==0&&LR_Y1<0', '营业利润两期持平，且为亏损状态，管理层需警惕利润持续下滑的可能性，结合主要科目，如营业收入、营业成本、应收款项、存货等的分析结果，如为销售单价或成本上涨导致利润下滑亏损，需考虑产品结构或市场分布是否需要调整。此外，营业利润为负数，管理层需结合现金流分析结果，结合货币资金中未来6个月的现金流状况预测图，考虑是否需要进行债权或股权融资以减轻现金流负担，支撑企业在亏损状态下改善经营及发展。', '', NULL, '20018', NULL, 2774);
INSERT INTO `t_mode` VALUES (2775, '2', '营业利润预警', 'LR_Y-LR_Y1==0&&LR_Y1==0', '营业利润两期持平，均为0，此情况较为特殊，建议管理层在确保数字正确的前提下，根据分析模块的预警，结合企业生产经营实际情况，考虑是否需要调整生产经营策略，此外，件内衣管理层结合现金流状况，避免出现资金链断链的情况。', '', NULL, '20018', NULL, 2775);
INSERT INTO `t_mode` VALUES (2776, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_AD>0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0', '利润总额呈增长趋势，且营业利润为正数，企业呈良性发展，建议管理层结合现金流分析，判断现金流是否充裕，是否足以支撑未来发展规划。如货币资金中未来6个月资金预测图显示未来可能有闲置资金，可考虑适当进行投资或业务扩张。', '', NULL, '20019', NULL, 2776);
INSERT INTO `t_mode` VALUES (2777, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD>0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '利润总额呈增长趋势，且营业利润、利润总额均体现为盈利，企业发展较为良性；但营业外收支净额对利润总额的增加形成较大影响，由于营业外收支为非经营性科目，不具备可持续性，建议管理层剔除其对利润的影响，重点关注营业利润的分析情况，及时调整经营策略等，结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20019', NULL, 2777);
INSERT INTO `t_mode` VALUES (2778, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD==0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '利润总额呈增长趋势，且营业利润为正数，企业呈良性发展，建议管理层结合现金流分析，判断现金流是否充裕，是否足以支撑未来发展规划。如货币资金中未来6个月资金预测图显示未来可能有闲置资金，可考虑适当进行投资或业务扩张。', '', NULL, '20019', NULL, 2778);
INSERT INTO `t_mode` VALUES (2779, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD==0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '利润总额呈增长趋势，且营业利润体现为盈利，企业发展较为良性；但营业外收支净额对利润总额的增加形成较大影响，由于营业外收支为非经营性科目，不具备可持续性，建议管理层剔除其对利润的影响，重点关注营业利润的分析情况，及时调整经营策略等，结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20019', NULL, 2779);
