INSERT INTO `t_mode` VALUES (2781, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD>0&&LR_Y==0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '利润总额呈增长趋势，且利润总额体现为盈利，企业发展较为良性；但营业外收支净额对利润总额的增加形成较大影响，由于营业外收支为非经营性科目，不具备可持续性，建议管理层剔除其对利润的影响，重点关注营业利润的分析情况，及时调整经营策略等，结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20019', NULL, 2781);
INSERT INTO `t_mode` VALUES (2782, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_AD<0&&LR_Y>0', '利润总额呈增长趋势，且主要业务活动已实现盈利，但由于营业外收支项目的影响，利润总额仍为亏损，建议予以关注并加以管控，以降低其对利润的不良影响。', '', NULL, '20019', NULL, 2782);
INSERT INTO `t_mode` VALUES (2783, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_AD==0&&LR_Y>0', '利润总额呈增长趋势，且主要业务活动已实现盈利，但由于营业外收支项目的影响，利润总额仍为亏损，建议予以关注并加以管控，以降低其对利润的不良影响。', '', NULL, '20019', NULL, 2783);
INSERT INTO `t_mode` VALUES (2784, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_AD<0&&LR_Y==0', '利润总额呈增长趋势，但由于营业外收支项目的影响，利润总额仍为亏损，建议予以关注并加以管控，以降低其对利润的不良影响。', '', NULL, '20019', NULL, 2784);
INSERT INTO `t_mode` VALUES (2785, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_Y<0&&LR_AD>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0  ', '利润总额呈增长趋势，且主要由营业利润增长主导其变动，企业呈良性发展。然而，营业利润仍处于亏损状态，建议管理层结合现金流分析，判断现金流是否充裕，是否足以支撑未来发展规划。考虑是否需要通过债权或股权融资补充现金流。', '', NULL, '20019', NULL, 2785);
INSERT INTO `t_mode` VALUES (2786, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD>0&&LR_Y<0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '尽管利润总额有所上涨，但该上涨主要是因为营业外收支净额的增加导致，营业利润实际为负数，在此情况下，由非日常经营产生的利润主导了利润总额的上涨，整个企业利润构成呈不健康状态。由于营业外收入为非经营性收入，为不可持续性收入，管理层应剔除此部分利润来分析整个企业的利润构成，建议管理层查看营业利润的分析结果，分析企业存在问题及调整方向。', '', NULL, '20019', NULL, 2786);
INSERT INTO `t_mode` VALUES (2787, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1>0&&LR_Y<0&&LR_AD==0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0  ', '利润总额呈增长趋势，且主要由营业利润增长主导其变动，企业呈良性发展。然而，营业利润仍处于亏损状态，建议管理层结合现金流分析，判断现金流是否充裕，是否足以支撑未来发展规划。考虑是否需要通过债权或股权融资补充现金流。', '', NULL, '20019', NULL, 2787);
INSERT INTO `t_mode` VALUES (2788, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD==0&&LR_Y<0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '尽管利润总额有所上涨，但该上涨主要是因为营业外收支净额的增加导致，营业利润实际为负数，在此情况下，由非日常经营产生的利润主导了利润总额的上涨，整个企业利润构成呈不健康状态。由于营业外收入为非经营性收入，为不可持续性收入，管理层应剔除此部分利润来分析整个企业的利润构成，建议管理层查看营业利润的分析结果，分析企业存在问题及调整方向。', '', NULL, '20019', NULL, 2788);
INSERT INTO `t_mode` VALUES (2789, '2', '利润总额预警', 'LR_AD-LR_AD1>0&&LR_Y-LR_Y1>0&&LR_AD<0&&LR_Y1<0', '本期亏损状况虽有所缓解，但营业利润、利润总额均未能实现扭亏，建议管理层结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2789);
INSERT INTO `t_mode` VALUES (2790, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD>0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，且体现企业日常经营业绩的营业利润的下降成为利润下降的主导因素，这是一个危险信号，应引起充分关注，建议管理层查看营业利润的分析结果，并结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2790);
INSERT INTO `t_mode` VALUES (2791, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD==0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，且体现企业日常经营业绩的营业利润的下降成为利润下降的主导因素，这是一个危险信号，应引起充分关注，建议管理层查看营业利润的分析结果，并结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2791);
INSERT INTO `t_mode` VALUES (2792, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD>0&&LR_Y==0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)<0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，且体现企业日常经营业绩的营业利润的下降成为利润下降的主导因素，这是一个危险信号，应引起充分关注，建议管理层查看营业利润的分析结果，并结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2792);
INSERT INTO `t_mode` VALUES (2793, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD>0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，营业外收支净额的变动对利润总额的下滑产生较大影响。由于营业外收支为非经营性收支，建议管理层在剔除营业外收支净额的影响后，结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2793);
INSERT INTO `t_mode` VALUES (2794, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD==0&&LR_Y>0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，营业外收支净额的变动对利润总额的下滑产生较大影响。由于营业外收支为非经营性收支，建议管理层在剔除营业外收支净额的影响后，结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2794);
INSERT INTO `t_mode` VALUES (2795, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD>0&&LR_Y==0&&(LR_Y-LR_Y1)-(LR_Z-LR_AB-LR_Z1+LR_AB1)>0', '企业虽实现盈利，但营业利润、利润总额均呈下降趋势，营业外收支净额的变动对利润总额的下滑产生较大影响。由于营业外收支为非经营性收支，建议管理层在剔除营业外收支净额的影响后，结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2795);
INSERT INTO `t_mode` VALUES (2796, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD>0&&LR_Y<0', '利润总额呈下降趋势，虽仍维持在盈利状态，但主要由营业外收支净额支撑其利润空间，营业外收支为非经营性收支，缺乏持续性；而能够反映企业日常经营业绩的营业利润已出现亏损且呈下降趋势。因此，建议管理层从剔除非经营性收支后的营业利润角度出发分析利润下降趋势，结合系统对主要科目，如：营业收入、营业成本、应收款项、存货等的变动分析，综合判断企业需调整改善的地方，制定相应策略。', '', NULL, '20019', NULL, 2796);
