INSERT INTO `t_mode` VALUES (2799, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD<0&&LR_Y>0', '利润总额持续下降，且处于亏损状态，营业利润虽为盈利但呈现下降趋势，建议管理层结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2799);
