INSERT INTO `t_mode` VALUES (2801, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD<0&&LR_Y==0', '利润总额持续下降，且处于亏损状态，营业利润虽为盈利但呈现下降趋势，建议管理层结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2801);
INSERT INTO `t_mode` VALUES (2802, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1<0&&LR_AD<0&&LR_Y<0', '利润总额持续下降，且处于亏损状态，营业利润亦为负数，建议管理层结合本系统主要科目，如：营业收入、营业成本、应收款项、存货等的分析结果，结合货币资金中未来6个月的资金状况预测，判断是否需要进行融资，同时考虑是否需要根据具体科目分析结果调整经营策略或方向等。', '', NULL, '20019', NULL, 2802);
INSERT INTO `t_mode` VALUES (2803, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1>0&&LR_Y<0&&LR_AD>0', '尽管本期利润总额为正数，但利润总额呈现下滑趋势，且营业利润实际为负数，证明企业利润总额的主要变动因素为营业外收支净额的影响，使得从经营类收入所得为负变为利润总额转盈利。由于营业外收支净额属于非经营性所得，不具有持续性，因此，管理层需对此情况高度警惕。建议结合分析模块的主要科目分析结果，了解实际经营亏损的原因，并评估是否需要调整生产经营策略。', '', NULL, '20019', NULL, 2803);
INSERT INTO `t_mode` VALUES (2804, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1>0&&LR_Y<0&&LR_AD>0', '受营业外收支项目的影响，尽管营业利润为亏损状态，但利润总额显示出盈利情况。由于营业外收支为非经营性科目，不具备可持续性，建议管理层剔除其对利润的影响，重点关注营业利润的分析情况，及时调整经营策略等，结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20019', NULL, 2804);
INSERT INTO `t_mode` VALUES (2805, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1>0&&LR_Y<0&&LR_AD==0&&(LR_Z-LR_AB)-(LR_Y1-LR_Y)>0', '受营业外收支项目的影响，尽管营业利润为亏损状态，但利润总额为0，证明营业外收支净额使得利润总额有所增加。由于营业外收支为非经营性科目，不具备可持续性，建议管理层剔除其对利润的影响，重点关注营业利润的分析情况，及时调整经营策略等，结合现金流分析结果，避免出现资金链断裂的情况。', '', NULL, '20019', NULL, 2805);
INSERT INTO `t_mode` VALUES (2806, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1>0&&LR_Y>0&&LR_AD>0', '本期营业利润有所上升，但利润总额有所下降，主要受营业外支出较上年同期有大幅度增加的影响。由于营业外收支属于非经营性收支，不具有可持续性，对后续期间的生产经营所得产生的影响可能不复存在，因此，本期利润的下滑，建议管理层在撇除非经营性支出的影响后再做评估。', '', NULL, '20019', NULL, 2806);
INSERT INTO `t_mode` VALUES (2807, '2', '利润总额预警', 'LR_AD-LR_AD1<0&& LR_Y-LR_Y1>0&&LR_Y==0&&LR_AD>0', '本期营业利润有所上升，但利润总额有所下降，受营业外收支净额影响较大。由于营业外收支属于非经营性收支，不具有可持续性，对后续期间的生产经营所得产生的影响可能不复存在，因此，本期利润的下滑，建议管理层在撇除非经营性支出的影响后再做评估。', '', NULL, '20019', NULL, 2807);
