INSERT INTO `t_mode` VALUES (2819, '2', '利润总额预警', 'LR_AD-LR_AD1>0&& LR_Y-LR_Y1<0&&LR_Y<0&&LR_AD<0', '本期利润总额由于营业外收支项目的影响较大。由于营业外收支属非经营性项目，对生产经营所得不具有持续性影响，因此，建议查看营业利润的分析结果，结合营业收入、营业成本、应收款项、存货等的分析结果，分析企业存在问题及调整方向；并对营业外收支项目予以关注并加以管控，以降低其对利润的不良影响。', '', NULL, '20019', NULL, 2819);
INSERT INTO `t_mode` VALUES (2820, '2', '利润总额预警', 'LR_AD-LR_AD1==0&&LR_AD1!=0', '利润总额两期相等，此情况较为特殊，建议管理层在确认数据无误的情况下，撇除营业外收支等非经营性项目对利润总额的影响，对利润总额再进行分析，根据分析结果，结合现金流分析状况，考虑是否需要扩大市场开拓或调整经营管理策略。', '', NULL, '20019', NULL, 2820);
INSERT INTO `t_mode` VALUES (2821, '2', '利润总额预警', 'LR_AD-LR_AD1==0&&LR_AD1==0', '利润总额两期相等，且均为0，此情况较为特殊，建议管理层在确认数据无误的情况下，撇除营业外收支等非经营性项目对利润总额的影响，对利润总额再进行分析，根据分析结果，结合现金流分析状况，考虑是否需要扩大市场开拓或调整经营管理策略。', '', NULL, '20019', NULL, 2821);
INSERT INTO `t_mode` VALUES (2822, '2', '净利润预警', 'LR_AF-LR_AF1>0&&LR_AD>0&&LR_AE!=0&&LR_AF1!=0', '净利润有所增长，且利润总额为正数。建议管理层剔除非经营性收支，如：营业外收支等科目的影响后，重新评估净利润状况，使其真实反应主体业务实际运营状态。可使用本系统咨询模块向专家顾问进行咨询。', '', '', '20020', '', 2822);
INSERT INTO `t_mode` VALUES (2823, '2', '净利润预警', 'LR_AF-LR_AF1>0&&LR_AD>0&&LR_AE==0&&LR_AF1!=0', '净利润有所增长，且所得税为0，企业仍处于税收优惠期。建议管理层结合所在地区税收政策，考虑在税收优惠期结束后，税金对净利润的影响。可使用本系统咨询模块，向专家进行咨询，通过税务筹划，进行合理避税，降低企业经营成本，实现利润最大化。', '', '', '20020', '', 2823);
INSERT INTO `t_mode` VALUES (2824, '2', '净利润预警', 'LR_AF1-LR_AF>0&&LR_AD<0&&LR_AF1!=0', '净利润有所下降，且利润总额为负数。建议管理层剔除非经营性收支，如：营业外收支等科目的影响后，重新评估净利润状况，使其真实反应主体业务实际运营状态。可使用本系统咨询模块向专家顾问进行咨询。', '', '', '20020', '', 2824);
INSERT INTO `t_mode` VALUES (2825, '2', '净利润预警', 'LR_AF-LR_AF1==0&&LR_AF1!=0', '净利润两期相等，建议管理层在确认数据无误的情况下，分别对比分析两期净利润构成，针对变动较大科目，查看系统分析结果，考虑是否存在管理漏洞，评估经营发展规划及策略是否存在调整空间内。', '', NULL, '20020', NULL, 2825);
INSERT INTO `t_mode` VALUES (2826, '2', '净利润预警', 'LR_AF1==0', '净利润上期为0，建议管理层在确认数据无误的情况下，分别对比分析两期净利润构成，针对变动较大科目，查看系统分析结果，考虑是否存在管理漏洞，评估经营发展规划及策略是否存在调整空间内。此外，需关注现金流状况，防止出现资金链断链的可能。', '', '', '20020', '', 2826);
INSERT INTO `t_mode` VALUES (2827, '2', '净利润预警', 'LR_AF1-LR_AF>0&&LR_AD>0&&LR_AF1!=0', '净利润有所下降，且利润总额为正数。建议管理层剔除非经营性收支，如：营业外收支等科目的影响后，重新评估净利润状况，使其真实反应主体业务实际运营状态。可使用本系统咨询模块向专家顾问进行咨询。', NULL, NULL, '20020', NULL, 0);
