INSERT INTO `t_mode` VALUES (2873, '2', '企业经营报告净利润', 'LR_AF1!=0&&LR_AF-LR_AF1==0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_A-LR_A1)/LR_A1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_F-LR_F1)/LR_F1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_O-LR_O1)/LR_O1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_P-LR_P1)/LR_P1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_Q-LR_Q1)/LR_Q1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_R-LR_R1)/LR_R1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_S-LR_S1)/LR_S1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_T-LR_T1)/LR_T1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_U-LR_U1)/LR_U1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_W-LR_W1)/LR_W1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_X-LR_X1)/LR_X1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_Z-LR_Z1)/LR_Z1)>0&&Math.abs((LR_AE-LR_AE1)/LR_AE1)-Math.abs((LR_AB-LR_AB1)/LR_AB1)>0', '本期净利润与上期一致，此情况较为特殊。其中，两期相比波动最大的为所得税费用，建议进入相应科目分析，查看异常变动原因及存在的问题。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2874, '2', '企业经营报告净利润', 'LR_AF==0', '净利润为0，企业处于收支临界点你，此时现金流状况尤为关键，直接影响是否会出现因资金链断裂而导致企业无法持续经营的情况，企业需结合现金流分析情况，考虑是否需要进行新一轮债权或股权融资。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2876, '2', '企业经营报告营业收入', 'LR_A1!=0&&LR_A!=0&&LR_A1-LR_A>0&&LR_A1/XSSL_A1-LR_A/XSSL_A>0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '本期营业收入存在以下问题：销售单价较同期比有所下滑，是收入下降的主导因素。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2877, '2', '企业经营报告营业收入', 'LR_A1!=0&&LR_A!=0&&LR_A1-LR_A>0&&XSSL_A1-XSSL_A>0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '本期营业收入存在以下问题：销售数量较同期比有所下滑，是收入下降的主导因素。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2878, '2', '企业经营报告营业收入', 'LR_A1!=0&&LR_A!=0&&LR_A1-LR_A<0&&LR_A1/XSSL_A1-LR_A/XSSL_A<0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '本期营业收入存在以下问题：本期营业收入较同期比有所上涨，销售单价的上升是主导因素，需提防单价上涨导致的收入上升的可持续性。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2879, '2', '企业经营报告营业收入', 'LR_A1!=0&&LR_A!=0&&LR_A/XSSL_A-LR_A1/XSSL_A1<0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '本期营业收入存在以下问题：本期营业收入较同期比有所上涨，销售数量的上升是主导因素，同时销售单价同比有所下滑，因此需考虑降价攻占市场的方式是否具有可持续性，根据市场反馈情况调整库存结构及销售策略。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2880, '2', '企业经营报告营业收入', 'LR_A1!=0&&LR_A!=0&&LR_A/XSSL_A-LR_A1/XSSL_A1>0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '本期营业收入存在以下问题：本期营业收入较同期比有所上涨，销售数量的上升是主导因素，同时销售单价较同期比亦有所上升，需考虑单价上涨对拉升营业收入的可持续性。应以增加销售数量，占领市场为主要增收措施。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2881, '2', '企业经营报告营业收入', 'LR_A==0', '本期营业收入存在以下问题：本期营业收入为0，企业未能产生任何收入，如为筹建期或市场开拓期，需考虑控制费用支出，可参考分析模块中成本及费用构成分析，考虑如何节省成本及开支。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2883, '2', '企业经营报告营业成本', 'LR_F1!=0&&LR_F-LR_F1>0&&(LR_F/XSSL_A)/(LR_F1/XSSL_A1)-XSSL_A/XSSL_A1>0', '本期营业收入存在以下问题：单位成本较同期比有所上涨，是营业成本上涨的主导因素。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2884, '2', '企业经营报告营业成本', 'LR_F1!=0&&LR_F-LR_F1>0&&(LR_F/XSSL_A)/(LR_F1/XSSL_A1)-XSSL_A/XSSL_A1>0&&LR_F/XSSL_A-LR_F1/XSSL_A1==0', '本期营业收入存在以下问题：单位成本不变，但销售数量较同期比有所下降，固定成本开支不变，是导致成本上涨的主导因素。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2885, '2', '企业经营报告营业成本', 'LR_F1-LR_F>0&&(LR_F/XSSL_A)/(LR_F1/XSSL_A1)-XSSL_A/XSSL_A1<0', '本期营业收入存在以下问题：营业成本有所下降，销售数量的下降为主导因素，注意市场占有率持续下降，管理层需就销售策略进行调整。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2886, '2', '企业经营报告营业成本', 'LR_F1-LR_F>0&&(LR_F/XSSL_A)/(LR_F1/XSSL_A1)-XSSL_A/XSSL_A1>0&&XSSL_A1-XSSL_A>0', '本期营业收入存在以下问题：营业成本有所下降，单位成本的下降为主导因素。同时，销售数量的下降亦对营业成本下降造成一定影响，管理层在维持压缩成本的情况下，需同时注意市场开拓的重要性，考虑降价促销、开拓新市场等方式减少市场占有率的流失。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2887, '2', '企业经营报告营业成本', 'LR_F==0', '本期营业收入存在以下问题：本期营业成本为0，无法进行数据分析。如因企业仍在产品研发或市场推广期，未产生任何营业收入及相应结转营业成本，则需考虑加快市场开拓力度，建议聘请专业销售团队进行销售策划。如为数据缺失，建议管理层补充完整数据以便进行相应分析。', '', '', 'G20030', '', 0);
INSERT INTO `t_mode` VALUES (2888, '3', '企业经营报告现金流量表', 'XJLL_BB>0', '本期现金流较好，现金及现金等价物净增加额为正数，主要是因为', '', NULL, 'G30002', NULL, 0);
INSERT INTO `t_mode` VALUES (2889, '3', '企业经营报告现金流量表', 'XJLL_BB>0&&XJLL_N-XJLL_AF>0&&XJLL_N-XJLL_AT>0', '经营活动产生的现金流量净额的增长所引起，现金流较为健康。', '', '', 'G30002', '', 0);
INSERT INTO `t_mode` VALUES (2890, '3', '企业经营报告现金流量表', 'XJLL_BB>0&&XJLL_AM-XJLL_Y>0&&XJLL_AM-XJLL_AZ>0', '投资活动产生的现金流量净额的增长所引起。主要现金流非主营业务产生，需警惕。投资者及银行在查看现金流量表时，重点关注现金流的产生是否健康，即是否由经营活动产生的现金流为主导，因此，现金流量表反应的该种情况，可能对未来引入投资者或者进行银行贷款产生一定的影响。', '', NULL, 'G30002', NULL, 0);
INSERT INTO `t_mode` VALUES (2891, '3', '企业经营报告现金流量表', 'XJLL_BB>0&&XJLL_AZ-XJLL_Y>0&&XJLL_AZ-XJLL_AM>0', '筹资活动产生的现金流量净额的增长所引起。单纯考虑企业因经营活动产生的现金流，实际为负数，说明企业实际生产运营存在问题，管理层需高度重视，充分利用本次融资或贷款流入的资金，盘活企业。', '', NULL, 'G30002', NULL, 0);
INSERT INTO `t_mode` VALUES (2892, '3', '企业经营报告现金流量表', 'XJLL_BB<0', '本期现金流存在较大问题，现金及现金等价物净增加额为负数，主要是因为', '', NULL, 'G30002', NULL, 0);
INSERT INTO `t_mode` VALUES (2893, '3', '企业经营报告现金流量表', 'XJLL_BB<0&&XJLL_X-XJLL_AL>0&&XJLL_X-XJLL_AY>0', '与经营活动相关的现金大量流出所引起。需考虑进行股权或债权融资，减轻现金流负担，避免出现资金链断裂的可能。同时，管理层需查看本期大量支付经营活动所需款项的原因，同时改善销售回款，尽量缩小目前经营活动现金流入与流出的较大差异。', '', '', 'G30002', '', 0);
INSERT INTO `t_mode` VALUES (2894, '3', '企业经营报告现金流量表', 'XJLL_BB<0&&XJLL_AL-XJLL_X>0&&XJLL_AL-XJLL_AY>0', '大量与投资活动相关的现金流出所引起。需进行企业未来现金流状况预测，考虑投资对未来现金流的影响程度，从而判断是否需要进一步进行贷款或股权融资以缓解大额投资对现金流产生的巨大压力。', '', '', 'G30002', '', 0);
INSERT INTO `t_mode` VALUES (2895, '3', '企业经营报告现金流量表', 'XJLL_BB<0&&XJLL_AY-XJLL_AL>0&&XJLL_AY-XJLL_X>0', '大量与筹资活动相关的现金流出所引起。需考虑该情况的出现是因短期归还贷款引起亦或会有长期影响，考虑续借或者再融资的可能性，以减轻大量归还贷款对现金流产生的影响。', '', '', 'G30002', '', 0);
INSERT INTO `t_mode` VALUES (2896, '3', '企业经营报告现金流量表', 'XJLL_BB==0', '本期现金及现金等价物净增加额为0，说明企业现金流处于临界点，管理层需高度关注，避免出现资金链断裂的情况。建议管理层结合分析模块中货币资金的现金流预测图，评估未来6个月内现金流情况，并进行相应的融资规划。', NULL, NULL, 'G30002', NULL, 0);
INSERT INTO `t_mode` VALUES (2898, '1', '企业经营报告资产负债表', 'ZCFZ_G!=0', '1、应收账款：本期前五大应收款客户占总应收的{YSQWD_C/ZCFZ_G*100}%，占比较高，需提防失去其中某一客户对生产经营所产生的较大影响。', '{YSQWD_C/ZCFZ_G*100}', '', 'G10045', '', 0);
INSERT INTO `t_mode` VALUES (2899, '1', '企业经营报告资产负债表', 'ZCFZ_G!=0&&YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '1、应收账款：本期应收账款账龄超1年的款项余额为Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元，占应收账款余额的{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/ZCFZ_G*100}%。建议分析收回可能性，并尽力进行催收，以保障企业利益。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000},{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/ZCFZ_G*100}', '', 'G10045', '', 0);
INSERT INTO `t_mode` VALUES (2900, '1', '企业经营报告资产负债表', 'ZCFZ_G!=0&&YBLFX_L-90>0', '1、应收账款：应收账款周转期超过90天，收款较慢，需警惕收款期长对企业现金流的影响，避免出现因资金紧张导致企业运转困难的情况。', '', '', 'G10045', '', 0);
INSERT INTO `t_mode` VALUES (2901, '1', '企业经营报告资产负债表', 'ZCFZ_G==0', '1、应收账款：本期应收账款为0，此情况较为特殊，建议管理层在确保数字无误及非数据缺失导致应收账款数据为0的情况下，结合现金流情况分析，在现金流状况良好及允许的情况下，可适当加大应收账款周转开拓及占据。', '', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2903, '1', '企业经营报告资产负债表', 'ZCFZ_AV!=0', '2、应付账款：本期前五大应付供应商占总应付款项的{YFQWD_S/ZCFZ_AV*100}%，占比较高，需提放供应商过度集中对企业生产经营的影响。一旦上游主要供应商出现问题，则可能连带影响企业的生产经营，建议分散采购，减少供应商过度集中的情况。', '{YFQWD_S/ZCFZ_AV*100}', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2904, '1', '企业经营报告资产负债表', 'ZCFZ_AV!=0&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '2、应付账款：本期应付账款账龄超1年的款项余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}万元，占应付账款余额的{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/ZCFZ_AV*100}%。建议查看相关合同条款，评估是否存在付款违约等法律风险。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000},{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/ZCFZ_AV*100}', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2905, '1', '企业经营报告资产负债表', 'ZCFZ_AV!=0&&YBLFX_O-60<0&&YBLFX_L-90<=0', '2、应付账款：应付账款周转期短于60天，企业支付供应商款项速度较快，可考虑与供应商洽谈延长付款期，优化企业现金流。', '', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2906, '1', '企业经营报告资产负债表', 'ZCFZ_AV!=0&&YBLFX_O-60<0&&YBLFX_L-90>0', '2、应付账款：应付账款周转期短于60天，且应收账款周转期超过90天，可能导致企业资金周转困难，应加大应收款催收力度，同时与供应商洽谈付款期的延长，或者利用票据进行短期融资，优化现金流。', '', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2907, '1', '企业经营报告资产负债表', 'ZCFZ_AV==0', '2、应付账款：本期应付账款为0，此情况较为特殊，建议管理层在确保数据无误及非数据缺失的情况下，与供应商谈判，适当延长付款周期，以使现金流状况更为健康。', '', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2909, '1', '企业经营报告资产负债表', 'ZCFZ_P!=0&&RM_D+RM_E+RM_F>0', '3、存货：原材料中库龄超1年的原材料金额为Rmb{(RM_D+RM_E+RM_F)/10000}万元，占原材料总库存的{(RM_D+RM_E+RM_F)/YCLKC_B*100}%，建议管理层查看该部分材料是否仍可用于生产，如否，则需考虑将其进行处理。', '{(RM_D+RM_E+RM_F)/10000},{(RM_D+RM_E+RM_F)/ZCFZ_P*100}', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2910, '1', '企业经营报告资产负债表', 'ZCFZ_P!=0&&CHKL_D+CHKL_E+CHKL_F>0', '3、存货：产成品中库龄超1年的产成品金额为Rmb{(FG_D+FG_E+FG_F)/10000}万元，占产成品总库存的{(FG_D+FG_E+FG_F)/CCPKC_B*100}%，建议管理层查看该部分产成品是否有销售的可能性，如产品具有时效性、季节性或已过时，需进行进行降价销售处理。', '{(FG_D+FG_E+FG_F)/10000},{(FG_D+FG_E+FG_F)/CCPKC_B*100}', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (2911, '1', '企业经营报告资产负债表', 'ZCFZ_P==0', '3、存货：本期存货金额为0，此情况较为特殊，建议管理层在确保数字无误或非数据缺失的情况下，结合生产所需，适当储备生产用材料。同时，结合分析模块中的单价分析结果，针对部分有季节性或预测未来期间有涨价可能的生产所需原材料，进行适当调整储备，以达到降低成本，规避经营风险的目的。', '', NULL, 'G10045', NULL, 0);
INSERT INTO `t_mode` VALUES (3411, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_A-ZCFZ_A1>0&&  (ZCFZ_A-ZCFZ_A1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_A-ZCFZ_A1)-(ZCFZ_AL-ZCFZ_AL1)>0', '待添加', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3412, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_D-ZCFZ_D1>0&&  (ZCFZ_D-ZCFZ_D1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_D-ZCFZ_D1)-(ZCFZ_AL-ZCFZ_AL1)>0', '由于以公允价值计量且其变动计入当期损益的金融资产核算的类别较为特殊，且此类资产为非经营类资产，因此期末值的增加提请管理层关注进行该资产交易的原因以及其增减值情况，注重风险控制。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3413, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_E-ZCFZ_E1>0&&   (ZCFZ_E-ZCFZ_E1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_E-ZCFZ_E1)-(ZCFZ_AL-ZCFZ_AL1)>0', '无预警。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3414, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_F-ZCFZ_F1>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_F-ZCFZ_F1)-(ZCFZ_AL-ZCFZ_AL1)>0', '企业应根据汇票的种类及规定及时行使提示承兑、提示付款等权利。否则，汇票未按照规定期限提示承兑的，持票人丧失对其前手的追索权；持票人超过提示付款期限提示付款的，持票人开户银行不予受理，此时企业需通过其他方式或途径追偿其应收款项。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3415, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_G-ZCFZ_G1>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_G-ZCFZ_G1)-(ZCFZ_AL-ZCFZ_AL1)>0&&YBLFX_L>90&& YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '本期总资产较上期有所增加，主要是因为应收账款的增加。应收账款期末较上年同期有所上涨，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。应收账款周转天数>90天，企业收账速度较慢、平均收账期较长，产生坏账损失的可能性较高。建议管理层需加强账款的催收，保障资产的流动性，有利于企业的正常生产运营。在应收账款中，账龄超过360日的应收账款余额为Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元。针对账龄超1年的应收账款，建议管理层分析其回收可能性以及出售的可能性，择优选择对自身最有利的方案，并相应进行账务调整。同时，查看与相关客户的合同，针对合同提及的违约责任等，考虑是否追究其法律责任。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}', NULL, 'G100001', NULL, 0);
