INSERT INTO `t_mode` VALUES (3419, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_H-ZCFZ_H1>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_H-ZCFZ_H1)-(ZCFZ_AL-ZCFZ_AL1)>0&& YFKXZL_D+YFKXZL_E+YFKXZL_F>0', '本期总资产较上期有所增长，主要是因为预付账款的增加。预付款项在期末较上年同期有所增加，建议管理层查看增加情况，考虑是否属于年底正常业务增长需求，若不属于，则建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付比例。本期账龄超过360日的预付款项金额为Rmb{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}万元，建议管理层查看预付账款的账龄分析，对账龄超过1年的预付账款确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}', NULL, 'G100001', NULL, 0);
