INSERT INTO `t_mode` VALUES (3422, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_M-ZCFZ_M1>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_M-ZCFZ_M1)-(ZCFZ_AL-ZCFZ_AL1)>0', '应收股利增加，建议结合长期股权投资、可供出售金融资产等科目情况，关注是否与股权投资收益情况相符，同时需关注后期股利资金发放。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3423, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_N-ZCFZ_N1>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_N-ZCFZ_N1)-(ZCFZ_AL-ZCFZ_AL1)>0&&QTYSZL_D+QTYSZL_E+QTYSZL_F>0', '本期总资产较上期有所增长，主要是因为其他应收款的增加。其他应收款在期末较上年同期有所增加，此现象较为异常，考虑是否因股东间拆借或他方违约引起。建议管理层查看其他应收款明细及相应信息。其他应收款期末的异常变动为年度审计、IPO审计、银行贷款的重点关注情况，建议管理层高度重视。其他应收款中有Rmb{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}万元账龄已超360日，对账龄超过1年的其他应收款需引起管理层的重视，建议管理层查看该部分较长账龄的其他应收款是否属于关联交易，并确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}', NULL, 'G100001', NULL, 0);
