INSERT INTO `t_mode` VALUES (3425, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_P-ZCFZ_P1>0&&(ZCFZ_P-ZCFZ_P1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_E-ZCFZ_E1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_L-ZCFZ_L1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_Q-ZCFZ_Q1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_W-ZCFZ_W1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_Y-ZCFZ_Y1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AB-ZCFZ_AB1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AF-ZCFZ_AF1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_P-ZCFZ_P1)-(ZCFZ_AL-ZCFZ_AL1)>0&&YBLFX_N>60&& CHKL_D+CHKL_E+CHKL_F>0', '本期总资产较上期有所增加，主要是因为存货的增加。本期末存货有所增加，考虑是否存在存货积压情况。建议管理层扩大销售渠道，增大销售额，同时合理安排原材料的采购时间和生产计划时间，通过设立安全库存等方式，尽量做到库存不积压，优化现金流管理。存货周转天数>60天，资金占用水平较高，流动性偏弱，存货转化为现金或应收帐款的速度就较慢，削弱了企业的短期偿债能力及获利能力。建议管理层关注存货管理中存在的问题，结合生产销售计划，尽可能降低存货的资金占用水平。期末存货中库龄超360日的存货有Rmb{(CHKL_D+CHKL_E+CHKL_F)/10000}万元。库龄超过1年的存货需引起管理层的重视，建议管理层查看该部分较长账龄的存货是否属于滞销产品和相关原材料，并确认其出售可能性，根据市场动态择优选择对自身最有利的方案，并进行相应账务处理。', '{(CHKL_D+CHKL_E+CHKL_F)/10000}', NULL, 'G100001', NULL, 0);
