INSERT INTO `t_mode` VALUES (3435, '1', '资产负债表首页预警', 'ZCFZ_AN-ZCFZ_AN1>0&&ZCFZ_Y-ZCFZ_Y1>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_A-ZCFZ_A1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_D-ZCFZ_D1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_E-ZCFZ_E1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_F-ZCFZ_F1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_G-ZCFZ_G1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_H-ZCFZ_H1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_L-ZCFZ_L1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_M-ZCFZ_M1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_N-ZCFZ_N1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_P-ZCFZ_P1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_Q-ZCFZ_Q1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_R-ZCFZ_R1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_S-ZCFZ_S1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_V-ZCFZ_V1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_W-ZCFZ_W1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_X-ZCFZ_X1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_Z-ZCFZ_Z1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AA-ZCFZ_AA1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AB-ZCFZ_AB1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AC-ZCFZ_AC1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AD-ZCFZ_AD1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AE-ZCFZ_AE1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AF-ZCFZ_AF1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AG-ZCFZ_AG1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AH-ZCFZ_AH1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AI-ZCFZ_AI1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AJ-ZCFZ_AJ1)>0&&(ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AK-ZCFZ_AK1)>0&& (ZCFZ_Y-ZCFZ_Y1)-(ZCFZ_AL-ZCFZ_AL1)>0', '由于长期股权投资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上年同期有所增加，需查找原因，同时需注意核算时点、计量金额是否会计准则要求。注意按收益法核算的长期股权投资在期末根据被投资企业的经营结果调整长期股权投资的账面价值。同时，需关注按成本法核算的长期股权投资是否存在减值情况。此外，如果长期股权投资金额的增加是因为债务重组或非货币性资产交换获得，建议考虑评估该部分资产未来可能产生的收益，以及对企业利润的影响。', '', NULL, 'G100001', NULL, 0);
