INSERT INTO `t_mode` VALUES (3452, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_F1-ZCFZ_F>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_F1-ZCFZ_F)-(ZCFZ_AL1-ZCFZ_AL)>0', '应收票据减少，企业应根据汇票的种类及规定及时行使提示承兑、提示付款等权利。否则，汇票未按照规定期限提示承兑的，持票人丧失对其前手的追索权；持票人超过提示付款期限提示付款的，持票人开户银行不予受理，此时企业需通过其他方式或途径追偿其应收款项。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3453, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_G1-ZCFZ_G>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_G1-ZCFZ_G)-(ZCFZ_AL1-ZCFZ_AL)>0&&YBLFX_L>90&& YSZKZL_D+YSZKZL_E+YSZKZL_F>0', '本期总资产较上期有所减少，主要是因为应收账款的减少。应收账款期末较上年同期有所减少，建议管理层查看营业收入模块中的应收收入趋势分析，如趋势一致，则较为健康，如趋势不一致，需与市场部查找不一致的原因，避免对企业未来经营产生重大影响的问题的发生。应收账款周转天数>90天，企业收账速度较慢、平均收账期较长，可能产生的坏账损失可能性较高。建议管理层需加强账款的催收，保障资产的流动性，有利于企业的正常生产运营。在应收账款中，账龄超过360日的应收账款余额为 Rmb{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}万元。针对账龄超1年的应收账款，建议管理层分析其回收可能性以及出售的可能性，择优选择对自身最有利的方案，并相应进行账务调整。同时，查看与相关客户的合同，针对合同提及的违约责任等，考虑是否追究其法律责任。', '{(YSZKZL_D+YSZKZL_E+YSZKZL_F)/10000}', NULL, 'G100001', NULL, 0);
