INSERT INTO `t_mode` VALUES (3457, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_H1-ZCFZ_H>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_H1-ZCFZ_H)-(ZCFZ_AL1-ZCFZ_AL)>0&&YFKXZL_D+YFKXZL_E+YFKXZL_F>0', '本期总资产较上期有所减少，主要是因为预付账款的减少。预付款项在期末较上年同期有所减少，建议管理层查看减少情况，考虑是否属于年底正常业务减少需求，若不属于，则建议管理层关注自身在采购及销售方面的谈判能力以及整个行业的采购及销售模式的变化。同时，注意预付账款对现金流带来的不利影响，建议管理层积极同供应商沟通，尽量在采购时减少预付形式。本期账龄超过360日的预付款项金额为Rmb{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}万元，建议管理层查看预付账款的账龄分析，对账龄超过1年的预付账款确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(YFKXZL_D+YFKXZL_E+YFKXZL_F)/10000}', NULL, 'G100001', NULL, 0);
