INSERT INTO `t_mode` VALUES (3459, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_L1-ZCFZ_L>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_L1-ZCFZ_L)-(ZCFZ_AL1-ZCFZ_AL)>0', '应收利息的减少，建议管理层结合债券的购买及到期情况做判断，如减少由债券购买的减少导致，或者因债券到期所导致，均属于正常情况，如出现相反趋势，建议管理层对其进行查询。建议针对债券进行专人专管，检查是否按要求设立备查薄，方便管理。可使用本系统在线咨询模块中的专项咨询服务，为企业设立完善的管理控制流程，提高管理效率。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3460, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_M1-ZCFZ_M>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_M1-ZCFZ_M)-(ZCFZ_AL1-ZCFZ_AL)>0', '应收股利减少，建议结合长期股权投资、可供出售金融资产等科目情况，关注是否与股权投资收益情况或处置股权资产相符。若因资产处置，则需重点关注处置原因、必要性及结果，以防不利于企业利益的情形出现。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3461, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_N1-ZCFZ_N>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_N1-ZCFZ_N)-(ZCFZ_AL1-ZCFZ_AL)>0&&QTYSZL_D+QTYSZL_E+QTYSZL_F>0', '本期总资产较上期有所减少，主要是因为其他应收款的减少。其他应收款在期末较上年同期有所减少，考虑是否因为资金回收、坏账处置引起。若因处置引起，则建议管理层重点关注处置的原因、必要性及结果，是否损害公司利益。同时，需关注剩余的其他应收款是否属于关联交易，若是，需考虑企业短期内是否有IPO计划，如有，则可能对企业的IPO造成不利影响。其他应收款中有Rmb{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}万元账龄已超360日，对账龄超过1年的其他应收款需引起管理层的重视，建议管理层查看该部分较长账龄的其他应收款是否属于关联交易，并确认其回收可能性以及处置的可能性，择优选择对自身最有利的方案，并进行相应账务处理。', '{(QTYSZL_D+QTYSZL_E+QTYSZL_F)/10000}', NULL, 'G100001', NULL, 0);
