INSERT INTO `t_mode` VALUES (3463, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_P1-ZCFZ_P>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_P1-ZCFZ_P)-(ZCFZ_AL1-ZCFZ_AL)>0&&YBLFX_N>60&& CHKL_D+CHKL_E+CHKL_F>0', '本期总资产较上期有所减少，主要是因为存货的减少。存货大幅度减少，考虑是否存在因销售额降低从而导致原材料的采购量降低或因销售额大增而导致产成品不足情形。若销售额降低，则建议管理层扩大销售渠道，增大销售额；若产成品不足，则建议管理层合理安排原材料的采购时间和生产计划时间，保障库存充足。存货周转天数>60天，资金占用水平较高，流动性偏弱，存货转化为现金或应收帐款的速度就较慢，削弱了企业的短期偿债能力及获利能力。建议管理层关注存货管理中存在的问题，结合生产销售计划，尽可能降低存货的资金占用水平。期末存货中库龄超360日的存货有Rmb{(CHKL_D+CHKL_E+CHKL_F)/10000}万元。账龄超过1年的存货需引起管理层的重视，建议管理层查看该部分较长账龄的存货是否属于滞销产品和相关原材料，并确认其出售可能性，根据市场动态择优选择对自身最有利的方案，并进行相应账务处理。', '{(CHKL_D+CHKL_E+CHKL_F)/10000}', NULL, 'G100001', NULL, 0);
