INSERT INTO `t_mode` VALUES (3472, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_X1-ZCFZ_X>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_X1-ZCFZ_X)-(ZCFZ_AL1-ZCFZ_AL)>0', '长期应收款在期末有所减少，考虑是因为资金回笼亦或是公司融资租赁业务的缩减。若因业务缩减引起长期应收款的期末减少，建议管理层联合市场部等相关部门，评判融资租赁业务对企业总体收益的影响，从而对融资租赁业务的发展做出合理规划。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3473, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_Y1-ZCFZ_Y>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AK1-ZCFZ_AK)>0&& (ZCFZ_Y1-ZCFZ_Y)-(ZCFZ_AL1-ZCFZ_AL)>0', '由于长期股权投资核算的类别较为特殊，且此类资产为非经营性活动类资产，因此，期末该科目余额比上年同期有所减少，需查找原因并关注已实现的减值额，同时需注意核算时点、计量金额等是否会计准则要求。注意按收益法核算的长期股权投资在期末根据被投资企业的经营结果调整长期股权投资的账面价值。同时，需关注按成本法核算的长期股权投资是否存在减值情况以及是否存在大量处置该资产情况，若存在处置资产情况，则需关注处置的原因、必要性及结果，以防不利于企业利益的情况发生。', '', NULL, 'G100001', NULL, 0);
