INSERT INTO `t_mode` VALUES (3485, '1', '资产负债表首页预警', 'ZCFZ_AN1-ZCFZ_AN>0&&ZCFZ_AK1-ZCFZ_AK>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_A1-ZCFZ_A)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_D1-ZCFZ_D)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_E1-ZCFZ_E)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_F1-ZCFZ_F)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_G1-ZCFZ_G)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_H1-ZCFZ_H)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_L1-ZCFZ_L)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_M1-ZCFZ_M)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_N1-ZCFZ_N)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_P1-ZCFZ_P)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_Q1-ZCFZ_Q)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_R1-ZCFZ_R)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_S1-ZCFZ_S)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_V1-ZCFZ_V)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_W1-ZCFZ_W)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_X1-ZCFZ_X)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_Y1-ZCFZ_Y)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_Z1-ZCFZ_Z)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AA1-ZCFZ_AA)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AB1-ZCFZ_AB)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AC1-ZCFZ_AC)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AD1-ZCFZ_AD)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AE1-ZCFZ_AE)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AF1-ZCFZ_AF)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AG1-ZCFZ_AG)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AH1-ZCFZ_AH)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AI1-ZCFZ_AI)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AJ1-ZCFZ_AJ)>0&& (ZCFZ_AK1-ZCFZ_AK)-(ZCFZ_AL1-ZCFZ_AL)>0', '递延所得税资产的产生，是因为资产的账面价值大于计税基础，或负债的账面价值小于计税基础，导致会计确认的所得税小于税法确认的所得税，从而产生递延所得税资产。递延所得税资产减少，需关注其确认条件、计量金额是否符合会计准则。建议管理层使用在线顾问模块中的专项顾问功能，为企业进行整体税收筹划，进行合理避税，减少企业利润不必要的损耗。同时，建议管理层检查是否已按要求设立备查薄。', '', NULL, 'G100001', NULL, 0);
