INSERT INTO `t_mode` VALUES (3488, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AS-ZCFZ_AS1>0&&(ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AS-ZCFZ_AS1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于以公允价值计量且其变动计入当期损益的金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3489, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AT-ZCFZ_AT1>0&&(ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AT-ZCFZ_AT1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于衍生金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3490, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AU-ZCFZ_AU1>0&&(ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AU-ZCFZ_AU1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于银行承兑汇票的付款期限最长为6个月，因此，使用票据实际上对企业来说可实现短期融资的目的，在短期现金流较为紧张的情况下，可考虑采取使用开具应付票据的方式减轻企业现金负担。然而，需注意以下可能产生的问题及风险：应付商业票据是购买企业在正常商业活动中向供应商承诺在将来特定时日、支付一笔固定货款的票据。与应付账款相比，应付商业票据由于提出了付款的书面承诺，因而更具有法律上的约束力。此外，企业应于汇票到期前将票款足额交存其开户银行，以免银行对企业进行计收利息及引起相关法律诉讼纠纷。同时建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3491, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AV-ZCFZ_AV1>0&&(ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BW-ZCFZ_BW1)>0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '本期总负债较上期有所增加，主要是因为应付账款的增加。应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层相对提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。但要留意，过度集中的采购，对企业存在风险，管理层需在两者之间取得平衡。在应付账款中，账龄超360日的应付账款余额为 Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}万元。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任及确认违约时间点等问题，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3492, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AV-ZCFZ_AV1>0&&(ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BW-ZCFZ_BW1)>0&&YBLFX_O<60&& YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '本期总负债较上期有所增加，主要是因为应付账款的增加。应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层相对提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。但要留意，过度集中的采购，对企业存在风险，管理层需在两者之间取得平衡。', '', NULL, 'G100001', NULL, 0);
