INSERT INTO `t_mode` VALUES (3494, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AV-ZCFZ_AV1>0&&(ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AV-ZCFZ_AV1)-(ZCFZ_BW-ZCFZ_BW1)>0&&YBLFX_O>=60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '本期总负债较上期有所增加，主要是因为应付账款的增加。应付账款有所增加，管理层需关注增加原因及后期还款压力。建议管理层结合货币资金中的资金预警，评估应付账款增加对未来现金流产生的影响。管理层可选用本系统中顾问咨询模块的企业咨询功能，由专家顾问为企业设计方案。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3495, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AW-ZCFZ_AW1>0&&(ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BW-ZCFZ_BW1)>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F>0', '总负债较上期有所增长，主要是因为预收款项的增加。预收款项有所增加，建议管理层结合本系统的收入分析及应收账款分析等模块，如呈反趋势增长，需与销售部门分析预收账款增加的原因，是否有合同条款的调整，同时分析调整收款条件对维护客户关系可能产生的影响。此外，在同等销售规模前提下，改应收为预收，实际上对企业现金流有良性作用，建议管理层在不影响客户关系的前提下，适当增加销售预收。在预收账款中，账龄超360日的预收账款余额为Rmb{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}万元。针对账龄超1年的预收账款，建议管理层结合销售合同，关注是否存在收入核算时点、计量金额不准确的问题。此外，建议管理层评估款该部分账龄较长之应收款项是否仍需发货或支付返还，并进行相应的账务处理。', '{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3496, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AW-ZCFZ_AW1>0&&(ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AW-ZCFZ_AW1)-(ZCFZ_BW-ZCFZ_BW1)>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F==0', '总负债较上期有所增长，主要是因为预收款项的增加。预收款项有所增加，建议管理层结合本系统的收入分析及应收账款分析等模块，如呈反趋势增长，需与销售部门分析预收账款增加的原因，是否有合同条款的调整，同时分析调整收款条件对维护客户关系可能产生的影响。此外，在同等销售规模前提下，改应收为预收，实际上对企业现金流有良性作用，建议管理层在不影响客户关系的前提下，适当增加销售预收。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3497, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_AZ-ZCFZ_AZ1>0&&(ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_AZ-ZCFZ_AZ1)-(ZCFZ_BW-ZCFZ_BW1)>0', '应付职工薪酬大幅度增加，考虑是否因正常人员增加所引起的。若员工大量增加，需关注企业的人工成本、人工效率。同时，若计划进行资本运作，则还需关注员工五险一金的缴纳是否按照相关规定执行，否则可能面临被主管单位要求补缴和处罚的情形。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3498, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BA-ZCFZ_BA1>0&&(ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BA-ZCFZ_BA1)-(ZCFZ_BW-ZCFZ_BW1)>0', '应交税费的大幅度增加，主要考虑是否因业务的增长造成。若与业务不匹配，则考虑是否存在税收政策变化等特殊情况。建议使用本系统顾问咨询中的专项咨询，由专业顾问为企业进行税收筹划，达到合理避税，利润最大化的目的。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3499, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BB-ZCFZ_BB1>0&&(ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BB-ZCFZ_BB1)-(ZCFZ_BW-ZCFZ_BW1)>0', '针对应付利息，提请管理层关注以下方面的问题：1、需查看借款合同，核查应付利息的确认时间和计量金额是否符合会计准则；2、关注付款期限及已支付金额，考虑自身资金压力；3、关注逾期未支付的违约责任及违约时间点。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3500, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BC-ZCFZ_BC1>0&&(ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BC-ZCFZ_BC1)-(ZCFZ_BW-ZCFZ_BW1)>0', '关注该科目的变动是否与企业宣告派发的股利相符合，同时需考虑支付能力，结合企业未来的生产经营计划关注资金压力问题。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3501, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BD-ZCFZ_BD1>0&&(ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BW-ZCFZ_BW1)>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F>0', '本期总负债较上期有所增加，主要是因为其他应付款的增加。其他应付款的有所增加，需考虑对未来偿还款项的资金风险。建议管理层查看增长幅度较大的其他应付款的合同，留意其中的偿还条款，根据本系统货币资金模块中的货币资金预警分析未来期间内是否会对资金造成影响。如为关联企业之间的资金拆借，需与企业未来发展相结合，如在短期内有上市计划，则需对其进行清理，如无，则需考虑关联企业之间的资金拆解是否符合相关的法律及监管条例的约束，例如：借款利率是否符合法律法规的要求；如为无息贷款，是否符合税法的要求。其他应付款中，账龄超360日的其他应付款余额为Rmb{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}万元。针对账龄超1年的其他应付款，建议管理层分析其是否属于关联方往来，并预估需付款的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流等方式，择优选择对自身最有利的方案，以防出现现金断流情况。', '{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3502, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BD-ZCFZ_BD1>0&&(ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BD-ZCFZ_BD1)-(ZCFZ_BW-ZCFZ_BW1)>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F==0', '本期总负债较上期有所增加，主要是因为其他应付款的增加。其他应付款的有所增加，需考虑对未来偿还款项的资金风险。建议管理层查看增长幅度较大的其他应付款的合同，留意其中的偿还条款，根据本系统货币资金模块中的货币资金预警分析未来期间内是否会对资金造成影响。如为关联企业之间的资金拆借，需与企业未来发展相结合，如在短期内有上市计划，则需对其进行清理，如无，则需考虑关联企业之间的资金拆解是否符合相关的法律及监管条例的约束，例如：借款利率是否符合法律法规的要求；如为无息贷款，是否符合税法的要求。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3503, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BI-ZCFZ_BI1>0&&(ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BI-ZCFZ_BI1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于持有待售的负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的增加提请管理层关注进行该负债增加的原因以及具体值，注重风险控制。同时，需注意新增负债的利率、归还期限、担保情况等，评估企业未来的现金流情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3504, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BJ-ZCFZ_BJ1>0&&(ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BJ-ZCFZ_BJ1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于一年内到期的非流动负债主要为从长期借款转入的负债，长期借款即将到期，需考虑是否需要对长期借款进行续借或新借。建议分析未来5年资金需求，合理规划贷款金额。同时，如需新增长期借款，需考虑企业固定资产等是否有足够的抵押物进行抵押借款，或是否有足够的资信可进行其他类型的贷款。', '', NULL, 'G100001', NULL, 0);
