INSERT INTO `t_mode` VALUES (3506, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BM-ZCFZ_BM1>0&&(ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BM-ZCFZ_BM1)-(ZCFZ_BW-ZCFZ_BW1)>0', '长期借款的增加，需关注未来还本付息对现金流的影响，除此之外，建议管理层整理贷款明细表对贷款情况进行归纳统计，关注合同中对贷款使用的限定，并责成专人负责对资金使用情况等进行追踪，规避因违规使用资金可能产生的风险。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3507, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BN-ZCFZ_BN1>0&&(ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BN-ZCFZ_BN1)-(ZCFZ_BW-ZCFZ_BW1)>0', '应付债券的增加，需关注未来还本付息对现金流的影响以及如未能按期支付利息或本金可能产生的法律风险。除此之外，提请管理层关注债券的募集说明书中赋予投资者的权利，避免因投资者根据募集说明书行使权利时双方可能产生的分歧。另外，建议管理层对债券设专人管理及专门的登记本，记录债券相关情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3508, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BQ-ZCFZ_BQ1>0&&(ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BQ-ZCFZ_BQ1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于一般性经营较少使用此科目，建议管理层查看此科目核算的内容，关注发生的原因及合理性，看是否存在因记账错误导致的余额变动。如非上述原因，则需根据科目核算的性质，考虑未来分期付款或融资租赁时支付款项对现金流的影响。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3509, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BS-ZCFZ_BS1>0&&(ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BS-ZCFZ_BS1)-(ZCFZ_BW-ZCFZ_BW1)>0', '由于此科目的特殊性，建议管理层设置专人管理此科目的变动情况，并且针对用款进行专项审核及登记，做到专款专用，详细记录转款的增减情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3510, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BT-ZCFZ_BT1>0&&(ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BT-ZCFZ_BT1)-(ZCFZ_BW-ZCFZ_BW1)>0', '预计负债大幅度增加，企业需提高警惕，关于增加的原因。同时由于预计负债的特殊性，建议管理层针对预计负债专门进行实现程度的可能性分析，针对风险较高，较可能需要实际支付的预计负债，除考虑对现金流的影响外，还要考虑负债产生同时可能伴随的法律责任或风险，以及如未能承担负债偿还的情况下可能产生的法律责任及风险。尤其在股权转让中，受让方更应重视目标公司的预计负债问题。当发生债务追索时，将严重影响受让方的股份转让合同的利益和预期的收益。预计债务的承担问题建议列入风险负担条款在股权转让合同中予以约定。同时注意股权的转移并不影响到追索的对象，受让方在成为目标公司股东后，目标公司仍需对外承担相应责任，受让方再根据股权转让合同向出让方追偿。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3511, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BU-ZCFZ_BU1>0&&(ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BV-ZCFZ_BV1)>0&& (ZCFZ_BU-ZCFZ_BU1)-(ZCFZ_BW-ZCFZ_BW1)>0', '递延收益的增加，需关注增加的原因及递延收益确认的条件是否合规。若为政府补贴产生的递延收益，则建议管理层重点关注补贴收入实现的相关条件，确保项目的开展符合政府相关规定。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3512, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BV-ZCFZ_BV1>0&&(ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BV-ZCFZ_BV1)-(ZCFZ_BW-ZCFZ_BW1)>0', '递延所得税负债的产生，是因为资产的账面价值小于计税基础，或负债的账面价值大于计税基础而，导致会计确认的所得税大于税法确认的所得税，从而产生递延所得税负债。递延所得税负债大幅度增加，需关注其确认条件、计量金额是否符合会计准则。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3513, '1', '资产负债表首页预警', 'ZCFZ_BY-ZCFZ_BY1>0&& ZCFZ_BW-ZCFZ_BW1>0&&(ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AO-ZCFZ_AO1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AS-ZCFZ_AS1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AT-ZCFZ_AT1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AU-ZCFZ_AU1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AV-ZCFZ_AV1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AW-ZCFZ_AW1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_AZ-ZCFZ_AZ1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BA-ZCFZ_BA1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BB-ZCFZ_BB1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BC-ZCFZ_BC1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BD-ZCFZ_BD1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BI-ZCFZ_BI1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BJ-ZCFZ_BJ1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BK-ZCFZ_BK1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BM-ZCFZ_BM1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BN-ZCFZ_BN1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BQ-ZCFZ_BQ1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BS-ZCFZ_BS1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BT-ZCFZ_BT1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BU-ZCFZ_BU1)>0&& (ZCFZ_BW-ZCFZ_BW1)-(ZCFZ_BV-ZCFZ_BV1)>0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3514, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AO1-ZCFZ_AO>0&&(ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AO1-ZCFZ_AO)-(ZCFZ_BW1-ZCFZ_BW)>0', '短期借款大幅度减少，考虑该借款是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，合理规划资金安排，控制资金压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3515, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AS1-ZCFZ_AS>0&&(ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AS1-ZCFZ_AS)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于以公允价值计量且其变动计入当期损益的金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3516, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AT1-ZCFZ_AT>0&&(ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AT1-ZCFZ_AT)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于衍生金融负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3517, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AU1-ZCFZ_AU>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AU1-ZCFZ_AU)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于银行承兑汇票的付款期限最长为6个月，因此，使用票据实际上对企业来说可实现短期融资的目的，在短期现金流较为紧张的情况下，可考虑采取使用开具应付票据的方式减轻企业现金负担。然而，需注意以下可能产生的问题及风险：应付商业票据是购买企业在正常商业活动中向供应商承诺在将来特定时日、支付一笔固定货款的票据。与应付账款相比，应付商业票据由于提出了付款的书面承诺，因而更具有法律上的约束力。此外，企业应于汇票到期前将票款足额交存其开户银行，以免银行对企业进行计收利息及引起相关法律诉讼纠纷。同时建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3518, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AV1-ZCFZ_AV>0&&  (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BW1-ZCFZ_BW)>0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F>0', '本期总负债较上期有所减少，主要是因为应付账款的减少。应付账款有所减少，管理层需关注减少原因及还款后企业现金流是否充足。此外，建议管理层与采购部查看针对主要供应商的付款数期变化，如应付账款的减少是因为数期缩短导致，管理层需考虑与供应商就数期问题进行协商，尽量延长付款周期。同时，建议管理层检查是否按要求设立备查薄，方便管理。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。在应付账款中，账龄超360日的应收账款余额为Rmb{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}。针对账龄超1年的应付账款，建议管理层分析其需偿还的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流或同供应商谈判延后付款等方式，择优选择对自身最有利的方案，以防出现现金断流情况。同时，查看与相关供应商的合同，针对合同提及的违约责任等，考虑企业可能需承担的法律责任和违约赔偿。', '{(YFZKZL_D+YFZKZL_E+YFZKZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3519, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AV1-ZCFZ_AV>0&&  (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BW1-ZCFZ_BW)>0&&YBLFX_O<60&&YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '本期总负债较上期有所减少，主要是因为应付账款的减少。应付账款有所减少，管理层需关注减少原因及还款后企业现金流是否充足。此外，建议管理层与采购部查看针对主要供应商的付款数期变化，如应付账款的减少是因为数期缩短导致，管理层需考虑与供应商就数期问题进行协商，尽量延长付款周期。同时，建议管理层检查是否按要求设立备查薄，方便管理。应付账款周转天数<60天，企业付款速度较高、资金占有率低，建议企业对比应收账款的周转天数，如果应付账款周转天数少于应收账款的周转天数，企业流动资金不充足的可能性较高，需要通过融资等手段解决资金缺口。建议管理层提高采购的集中度从而加大对供应商的话语权，延长付款期限，便于企业资金运转。', '', NULL, 'G100001', NULL, 0);
