INSERT INTO `t_mode` VALUES (3521, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AV1-ZCFZ_AV>0&&  (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AV1-ZCFZ_AV)-(ZCFZ_BW1-ZCFZ_BW)>0&&YBLFX_O>=60&& YFZKZL_D+YFZKZL_E+YFZKZL_F==0', '本期总负债较上期有所减少，主要是因为应付账款的减少。应付账款有所减少，管理层需关注减少原因及还款后企业现金流是否充足。此外，建议管理层与采购部查看针对主要供应商的付款数期变化，如应付账款的减少是因为数期缩短导致，管理层需考虑与供应商就数期问题进行协商，尽量延长付款周期。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3522, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AW1-ZCFZ_AW>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BW1-ZCFZ_BW)>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F>0', '本期总负债较上期有所减少，主要是因为预收款项的下降。预收款项有所减少，首先需考虑是否与收入变动趋势一致，在不一致的情况下，需重点分析其减少原因。建议管理层与销售部门查看销售合同，并结合市场大环境，考虑预收款项的减少是否因产业经济环境下滑导致下游客户转嫁资金时间成本，合同收款条款进行了修改引起。在预收款项中，账龄超360日的预收款项余额为Rmb{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}万元。针对账龄超1年的预收款项，建议管理层结合销售合同，关注是否存在收入核算时点、计量金额不准确的问题。若不存在核算问题，则建议管理层关注是否因逾期1年的预收账款减少导致预收账款整体减少。若是，则建议继续跟进逾期1年预收账款减少是因转入收入还是因我司无法发货导致退款，若因我司无法发货导致退款，则需重点关注违约风险以及退款对我司资金流的影响。若否，则建议管理层重点关注逾期1年预收账款涉及的销售合同中收款方式、发货时点、违约责任等相关条款，若我司存在收到预收款后违约发货问题，则需评估违约风险对公司的不利影响。', '{(YSKXZL_D+YSKXZL_E+YSKXZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3523, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AW1-ZCFZ_AW>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AW1-ZCFZ_AW)-(ZCFZ_BW1-ZCFZ_BW)>0&&YSKXZL_D+YSKXZL_E+YSKXZL_F==0', '本期总负债较上期有所减少，主要是因为预收款项的下降。预收款项有所减少，首先需考虑是否与收入变动趋势一致，在不一致的情况下，需重点分析其减少原因。建议管理层与销售部门查看销售合同，并结合市场大环境，考虑预收款项的减少是否因产业经济环境下滑导致下游客户转嫁资金时间成本，合同收款条款进行了修改引起。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3524, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_AZ1-ZCFZ_AZ>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_AZ1-ZCFZ_AZ)-(ZCFZ_BW1-ZCFZ_BW)>0', '应付职工薪酬大幅度减少，考虑是否因正常人员减少引起的。若员工大量减少，需关注核心技术人员是否离职，人员减少后是否会对企业运营产生影响，需注意企业生产运营的稳定性。同时，若计划进行资本运作，则还需关注员工五险一金的缴纳是否按照相关规定执行，可能面临被主管单位要求补缴和处罚的情形。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3525, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BA1-ZCFZ_BA>0&&  (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BA1-ZCFZ_BA)-(ZCFZ_BW1-ZCFZ_BW)>0', '应交税费的大幅度减少，主要考虑是否因业务的减少造成。若与业务不匹配，则考虑是否存在税收政策变化等特殊情况。建议使用本系统顾问咨询中的专项咨询，由专业顾问为企业进行税收筹划，达到合理避税，利润最大化的目的。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3526, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BB1-ZCFZ_BB>0&&  (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BB1-ZCFZ_BB)-(ZCFZ_BW1-ZCFZ_BW)>0', '针对应付利息，提请管理层关注以下方面的问题：1、需查看借款合同，核查应付利息的确认时间和计量金额是否符合会计准则；2、关注付款期限及已支付金额，考虑自身资金压力；3、关注逾期未支付的违约责任及违约时间点。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3527, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BC1-ZCFZ_BC>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BC1-ZCFZ_BC)-(ZCFZ_BW1-ZCFZ_BW)>0', '关注该科目的变动是否与企业宣告派发的股利相符合，同时需考虑支付能力，结合企业未来的生产经营计划关注资金压力问题。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3528, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BD1-ZCFZ_BD>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BW1-ZCFZ_BW)>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F>0', '本期总负债较上期有所减少，主要是因为其他应付款的减少。其他应付款有所减少，需关注当前的资金状况是否充裕。此外，其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。在其他应付账款中，账龄超360日的其他应付款余额为Rmb{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}万元。针对账龄超1年的其他应付款，建议管理层分析其是否属于关联交易，并预估需付款的最快时间和最小金额，再结合企业自身资金情况，通过扩大销售增大现金流等方式，择优选择对自身最有利的方案，以防出现现金断流情况。', '{(QTYFZL_D+QTYFZL_E+QTYFZL_F)/10000}', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3529, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BD1-ZCFZ_BD>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BD1-ZCFZ_BD)-(ZCFZ_BW1-ZCFZ_BW)>0&&QTYFZL_D+QTYFZL_E+QTYFZL_F==0', '本期总负债较上期有所减少，主要是因为其他应付款的减少。其他应付款有所减少，需关注当前的资金状况是否充裕。此外，其他应付款为年度审计，上市审计的重点关注对象，建议管理层了解其构成，针对关联方往来，及时进行清理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3530, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BI1-ZCFZ_BI>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BI1-ZCFZ_BI)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于持有待售的负债核算的类别较为特殊，且此类资产为非经营类负债，因此期末值的减少提请管理层考虑该负债减少的原因及金额，关注该变动金额的不确定性。若金额减少是因偿还债务，则还需考虑是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3531, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BJ1-ZCFZ_BJ>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BJ1-ZCFZ_BJ)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于一年内到期的非流动负债主要为一年内到期的长期借款等，对于企业来说，由于之前的资金需求产生的贷款在近期内需进行偿还，因此需分析资金状况在未来一年内是否可以满足其偿还需求。若资金紧张，则需考虑通过借款、延长支付期限等方式缓解资金压力。', '', NULL, 'G100001', NULL, 0);
