INSERT INTO `t_mode` VALUES (3533, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BM1-ZCFZ_BM>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BM1-ZCFZ_BM)-(ZCFZ_BW1-ZCFZ_BW)>0', '长期借款的减少，考虑该借款是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3534, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BN1-ZCFZ_BN>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BN1-ZCFZ_BN)-(ZCFZ_BW1-ZCFZ_BW)>0', '应付债券的大幅度减少，考虑该债券是以自有资金还是以新增贷款偿还。若因自有资金偿还，则还需关注目前的资金余额；若以新增贷款偿还，则需考虑新增贷款的利率及期限、企业自身的现金流情况，重点注意新增短期贷款可能带来近期较大的还本付息压力。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3535, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BQ1-ZCFZ_BQ>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BQ1-ZCFZ_BQ)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于一般性经营较少使用此科目，建议管理层查看此科目核算的内容，关注发生的原因及合理性，看是否存在因记账错误导致的余额变动。如非上述原因，则需根据科目核算的性质，考虑未来分期付款或融资租赁时支付款项对现金流的影响。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3536, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BS1-ZCFZ_BS>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BS1-ZCFZ_BS)-(ZCFZ_BW1-ZCFZ_BW)>0', '由于此科目的特殊性，建议管理层设置专人管理此科目的变动情况，并且针对用款进行专项审核及登记，做到专款专用，详细记录转款的增减情况。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3537, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BT1-ZCFZ_BT>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BT1-ZCFZ_BT)-(ZCFZ_BW1-ZCFZ_BW)>0', '预计负债大额减少，需关注已支付负债的原因及数值，同时评估企业现有资金情况。同时由于预计负债的特殊性，建议管理层针对剩余预计负债专门进行实现程度的可能性分析，针对风险较高，较可能需要实际支付的预计负债，除考虑对现金流的影响外，还要考虑负债产生同时可能伴随的法律责任或风险，以及如未能承担负债偿还的情况下可能产生的法律责任及风险。尤其在股权转让中，受让方更应重视目标公司的预计负债问题。当发生债务追索时，将严重影响受让方的股份转让合同的利益和预期的收益。预计债务的承担问题建议列入风险负担条款在股权转让合同中予以约定。同时注意股权的转移并不影响到追索的对象，受让方在成为目标公司股东后，目标公司仍需对外承担相应责任，受让方再根据股权转让合同向出让方追偿。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3538, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BU1-ZCFZ_BU>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BV1-ZCFZ_BV)>0&& (ZCFZ_BU1-ZCFZ_BU)-(ZCFZ_BW1-ZCFZ_BW)>0', '递延收益的减少，需关注减少的原因及转入收益的条件是否合规。特别是政府补贴产生的递延收益，管理层需重点关注补贴收入实现的相关条件，确保项目的开展符合政府相关规定。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3539, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BV1-ZCFZ_BV>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BV1-ZCFZ_BV)-(ZCFZ_BW1-ZCFZ_BW)>0', '递延所得税负债的产生，是因为资产的账面价值小于计税基础，或负债的账面价值大于计税基础而，导致会计确认的所得税大于税法确认的所得税，从而产生递延所得税负债。递延所得税负债大幅度减少，需关注其确认条件、计量金额是否符合会计准则。同时，建议管理层检查是否按要求设立备查薄，方便管理。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3540, '1', '资产负债表首页预警', 'ZCFZ_BY1-ZCFZ_BY>0&& ZCFZ_BW1-ZCFZ_BW>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AO1-ZCFZ_AO)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AS1-ZCFZ_AS)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AT1-ZCFZ_AT)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AU1-ZCFZ_AU)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AV1-ZCFZ_AV)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AW1-ZCFZ_AW)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_AZ1-ZCFZ_AZ)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BA1-ZCFZ_BA)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BB1-ZCFZ_BB)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BC1-ZCFZ_BC)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BD1-ZCFZ_BD)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BI1-ZCFZ_BI)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BJ1-ZCFZ_BJ)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BK1-ZCFZ_BK)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BM1-ZCFZ_BM)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BN1-ZCFZ_BN)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BQ1-ZCFZ_BQ)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BS1-ZCFZ_BS)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BT1-ZCFZ_BT)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BU1-ZCFZ_BU)>0&& (ZCFZ_BW1-ZCFZ_BW)-(ZCFZ_BV1-ZCFZ_BV)>0', '其他非流动负债属于非经常性科目，若在期末发生大幅度的变动，建议管理层关注该变化的原因。', '', NULL, 'G100001', NULL, 0);
INSERT INTO `t_mode` VALUES (3651, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&&LR_A1!=0&& LR_A-LR_A1>0&&(LR_A-LR_A1)-(LR_F1-LR_F)>0&& (LR_A-LR_A1)-(LR_O1-LR_O)>0&&(LR_A-LR_A1)-(LR_P1-LR_P)>0&&(LR_A-LR_A1)-(LR_Q1-LR_Q)>0&&(LR_A-LR_A1)-(LR_R1-LR_R)>0&&(LR_A-LR_A1)-(LR_S1-LR_S)>0&&(LR_A-LR_A1)-(LR_T-LR_T1)>0&&(LR_A-LR_A1)-(LR_U-LR_U1)>0&& (LR_A-LR_A1)-(LR_W-LR_W1)>0&& (LR_A-LR_A1)-(LR_X-LR_X1)>0&& (LR_A-LR_A1)-(LR_Z-LR_Z1)>0&& (LR_A-LR_A1)-(LR_AB1-LR_AB)>0&& (LR_A-LR_A1)-(LR_AE1-LR_AE)>0&&LR_A/XSSL_A-LR_A1/XSSL_A1>0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '净利润本期比上期有所增加，主要是因为营业收入的增加。营业收入本期比上年同期增长{(LR_A-LR_A1)/LR_A1*100}%，主要是因为平均销售单价的上升。建议管理层与销售部分析销售单价上涨的产品及地区，评估产品群对价格上涨的接受程度，考虑是否所有产品均可涨价，抑或存在一定的局限性。如果单价上涨主要由于针对某一大产品，需考虑单价上涨对双方长期合作关系可能产生的影响。评估竞争对手的价格与企业相比是否具有较强的价格竞争力，企业的涨价行为是否会因此造成客源的流失。', '{(LR_A-LR_A1)/LR_A1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3652, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&&LR_A-LR_A1>0&& LR_A1!=0&&(LR_A-LR_A1)-(LR_F1-LR_F)>0&& (LR_A-LR_A1)-(LR_O1-LR_O)>0&&(LR_A-LR_A1)-(LR_P1-LR_P)>0&&(LR_A-LR_A1)-(LR_Q1-LR_Q)>0&&(LR_A-LR_A1)-(LR_R1-LR_R)>0&&(LR_A-LR_A1)-(LR_S1-LR_S)>0&&(LR_A-LR_A1)-(LR_T-LR_T1)>0&&(LR_A-LR_A1)-(LR_U-LR_U1)>0&& (LR_A-LR_A1)-(LR_W-LR_W1)>0&& (LR_A-LR_A1)-(LR_X-LR_X1)>0&& (LR_A-LR_A1)-(LR_Z-LR_Z1)>0&& (LR_A-LR_A1)-(LR_AB1-LR_AB)>0&& (LR_A-LR_A1)-(LR_AE1-LR_AE)>0&&XSSL_A-XSSL_A1>0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)>0', '净利润本期比上期有所增加，主要是因为营业收入的增加。营业收入本期比上年同期增长{(LR_A-LR_A1)/LR_A1*100}%，主要是因为销售量的大幅度增加。建议管理层与销售部分析销售量增长幅度最大的区域及产品，与市场部研究其增长模式是否可以在其他区域或产品中进行复制。同时，考虑销售量的增长是否具有可持续性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长。', '{(LR_A-LR_A1)/LR_A1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3653, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&&LR_A1==0&& LR_A-LR_A1>0&&(LR_A-LR_A1)-(LR_F1-LR_F)>0&& (LR_A-LR_A1)-(LR_O1-LR_O)>0&&(LR_A-LR_A1)-(LR_P1-LR_P)>0&&(LR_A-LR_A1)-(LR_Q1-LR_Q)>0&&(LR_A-LR_A1)-(LR_R1-LR_R)>0&&(LR_A-LR_A1)-(LR_S1-LR_S)>0&&(LR_A-LR_A1)-(LR_T-LR_T1)>0&&(LR_A-LR_A1)-(LR_U-LR_U1)>0&& (LR_A-LR_A1)-(LR_W-LR_W1)>0&& (LR_A-LR_A1)-(LR_X-LR_X1)>0&& (LR_A-LR_A1)-(LR_Z-LR_Z1)>0&& (LR_A-LR_A1)-(LR_AB1-LR_AB)>0&& (LR_A-LR_A1)-(LR_AE1-LR_AE)>0&&LR_A/XSSL_A-LR_A1/XSSL_A1>0&&(LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1>0', '净利润本期比上期有所增加，主要是因为营业收入的增加。营业收入本期比上年同期增长-%，主要是因为平均销售单价的上升。建议管理层与销售部分析销售单价上涨的产品及地区，评估产品群对价格上涨的接受程度，考虑是否所有产品均可涨价，抑或存在一定的局限性。如果单价上涨主要由于针对某一大产品，需考虑单价上涨对双方长期合作关系可能产生的影响。评估竞争对手的价格与企业相比是否具有较强的价格竞争力，企业的涨价行为是否会因此造成客源的流失。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3654, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&&LR_A-LR_A1>0&& LR_A1==0&&(LR_A-LR_A1)-(LR_F1-LR_F)>0&& (LR_A-LR_A1)-(LR_O1-LR_O)>0&&(LR_A-LR_A1)-(LR_P1-LR_P)>0&&(LR_A-LR_A1)-(LR_Q1-LR_Q)>0&&(LR_A-LR_A1)-(LR_R1-LR_R)>0&&(LR_A-LR_A1)-(LR_S1-LR_S)>0&&(LR_A-LR_A1)-(LR_T-LR_T1)>0&&(LR_A-LR_A1)-(LR_U-LR_U1)>0&& (LR_A-LR_A1)-(LR_W-LR_W1)>0&& (LR_A-LR_A1)-(LR_X-LR_X1)>0&& (LR_A-LR_A1)-(LR_Z-LR_Z1)>0&& (LR_A-LR_A1)-(LR_AB1-LR_AB)>0&& (LR_A-LR_A1)-(LR_AE1-LR_AE)>0&&XSSL_A-XSSL_A1>0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)>0', '净利润本期比上期有所增加，主要是因为营业收入的增加。营业收入本期比上年同期增长-%，主要是因为销售量的大幅度增加。建议管理层与销售部分析销售量增长幅度最大的区域及产品，与市场部研究其增长模式是否可以在其他区域或产品中进行复制。同时，考虑销售量的增长是否具有可持续性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3655, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&&LR_A1==0&&LR_A-LR_A1>0&&(LR_A-LR_A1)-(LR_F1-LR_F)>0&& (LR_A-LR_A1)-(LR_O1-LR_O)>0&&(LR_A-LR_A1)-(LR_P1-LR_P)>0&&(LR_A-LR_A1)-(LR_Q1-LR_Q)>0&& (LR_A-LR_A1)-(LR_R1-LR_R)>0&&(LR_A-LR_A1)-(LR_S1-LR_S)>0&&(LR_A-LR_A1)-(LR_T-LR_T1)>0&&(LR_A-LR_A1)-(LR_U-LR_U1)>0&& (LR_A-LR_A1)-(LR_W-LR_W1)>0&& (LR_A-LR_A1)-(LR_X-LR_X1)>0&& (LR_A-LR_A1)-(LR_Z-LR_Z1)>0&& (LR_A-LR_A1)-(LR_AB1-LR_AB)>0&& (LR_A-LR_A1)-(LR_AE1-LR_AE)>0&&XSSL_A-XSSL_A1>0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)>0&&XSSL_A1==0', '净利润本期比上期有所增加，主要是因为营业收入的增加。营业收入本期比上年同期增长-%。由于上期数据缺失，导致无法分析收入变动的主要驱动因素。建议管理层补充系统数据以便进行分析。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3656, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_A1-LR_A>0&& LR_A1!=0&&(LR_A1-LR_A)-(LR_F-LR_F1)>0&& (LR_A1-LR_A)-(LR_O-LR_O1)>0&& (LR_A1-LR_A)-(LR_P-LR_P1)>0&&(LR_A1-LR_A)-(LR_Q-LR_Q1)>0&& (LR_A1-LR_A)-(LR_R-LR_R1)>0&& (LR_A1-LR_A)-(LR_S-LR_S1)>0&& (LR_A1-LR_A)-(LR_T1-LR_T)>0&&(LR_A1-LR_A)-(LR_U1-LR_U)>0&& (LR_A1-LR_A)-(LR_W1-LR_W)>0&& (LR_A1-LR_A)-(LR_X1-LR_X)>0&& (LR_A1-LR_A)-(LR_Z1-LR_Z)>0&& (LR_A1-LR_A)-(LR_AB-LR_AB1)>0&& (LR_A1-LR_A)-(LR_AE-LR_AE1)>0&&LR_A/XSSL_A-LR_A1/XSSL_A1<0&& (LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '净利润本期比上期有所减少，主要是因为营业收入的减少。营业收入本期比上年同期减少{(LR_A1-LR_A)/LR_A1*100}%，主要是因为平均销售单价的降低。建议管理层与销售部分析销售单价降低的产品及地区，评估产品群对价格的敏感性，考虑是否所有产品均可适当涨价，提高企业利润。如果单价降低主要由于针对某一大产品，需考虑单价降低对双方长期合作关系可能产生的影响及评估该措施的利弊。同时，评估竞争对手的价格与企业相比是否具有较强的价格竞争力，后期企业的涨价行为是否会因此造成客源的流失。', '{(LR_A1-LR_A)/LR_A1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3657, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_A1-LR_A>0&&LR_A1!=0&&(LR_A1-LR_A)-(LR_F-LR_F1)>0&& (LR_A1-LR_A)-(LR_O-LR_O1)>0&& (LR_A1-LR_A)-(LR_P-LR_P1)>0&&(LR_A1-LR_A)-(LR_Q-LR_Q1)>0&& (LR_A1-LR_A)-(LR_R-LR_R1)>0&& (LR_A1-LR_A)-(LR_S-LR_S1)>0&& (LR_A1-LR_A)-(LR_T1-LR_T)>0&&(LR_A1-LR_A)-(LR_U1-LR_U)>0&& (LR_A1-LR_A)-(LR_W1-LR_W)>0&& (LR_A1-LR_A)-(LR_X1-LR_X)>0&& (LR_A1-LR_A)-(LR_Z1-LR_Z)>0&& (LR_A1-LR_A)-(LR_AB-LR_AB1)>0&& (LR_A1-LR_A)-(LR_AE-LR_AE1)>0&&XSSL_A-XSSL_A1<0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)<0', '净利润本期比上期有所减少，主要是因为营业收入的减少。营业收入本期比上年同期减少{(LR_A1-LR_A)/LR_A1*100}%，主要是因为销售量的大幅度降低。建议管理层与销售部分析销售量降低幅度最大的区域及产品，与市场部研究其降低原因，考虑销售量的降低是否具有不可逆转性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长，维持市场份额。', '{(LR_A1-LR_A)/LR_A1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3658, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_A1-LR_A>0&& LR_A1==0&&(LR_A1-LR_A)-(LR_F-LR_F1)>0&& (LR_A1-LR_A)-(LR_O-LR_O1)>0&& (LR_A1-LR_A)-(LR_P-LR_P1)>0&&(LR_A1-LR_A)-(LR_Q-LR_Q1)>0&& (LR_A1-LR_A)-(LR_R-LR_R1)>0&& (LR_A1-LR_A)-(LR_S-LR_S1)>0&& (LR_A1-LR_A)-(LR_T1-LR_T)>0&&(LR_A1-LR_A)-(LR_U1-LR_U)>0&& (LR_A1-LR_A)-(LR_W1-LR_W)>0&& (LR_A1-LR_A)-(LR_X1-LR_X)>0&& (LR_A1-LR_A)-(LR_Z1-LR_Z)>0&& (LR_A1-LR_A)-(LR_AB-LR_AB1)>0&& (LR_A1-LR_A)-(LR_AE-LR_AE1)>0&&LR_A/XSSL_A-LR_A1/XSSL_A1<0&& (LR_A/XSSL_A)/(LR_A1/XSSL_A1)-XSSL_A/XSSL_A1<0', '净利润本期比上期有所减少，主要是因为营业收入的减少。营业收入本期比上年同期减少-%，主要是因为平均销售单价的降低。建议管理层与销售部分析销售单价降低的产品及地区，评估产品群对价格的敏感性，考虑是否所有产品均可适当涨价，提高企业利润。如果单价降低主要由于针对某一大产品，需考虑单价降低对双方长期合作关系可能产生的影响及评估该措施的利弊。同时，评估竞争对手的价格与企业相比是否具有较强的价格竞争力，后期企业的涨价行为是否会因此造成客源的流失。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3659, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_A1-LR_A>0&&LR_A1==0&&(LR_A1-LR_A)-(LR_F-LR_F1)>0&& (LR_A1-LR_A)-(LR_O-LR_O1)>0&& (LR_A1-LR_A)-(LR_P-LR_P1)>0&& (LR_A1-LR_A)-(LR_Q-LR_Q1)>0&& (LR_A1-LR_A)-(LR_R-LR_R1)>0&& (LR_A1-LR_A)-(LR_S-LR_S1)>0&& (LR_A1-LR_A)-(LR_T1-LR_T)>0&&(LR_A1-LR_A)-(LR_U1-LR_U)>0&& (LR_A1-LR_A)-(LR_W1-LR_W)>0&& (LR_A1-LR_A)-(LR_X1-LR_X)>0&& (LR_A1-LR_A)-(LR_Z1-LR_Z)>0&& (LR_A1-LR_A)-(LR_AB-LR_AB1)>0&& (LR_A1-LR_A)-(LR_AE-LR_AE1)>0&&XSSL_A-XSSL_A1<0&&XSSL_A/XSSL_A1-(LR_A/XSSL_A)/(LR_A1/XSSL_A1)<0', '净利润本期比上期有所减少，主要是因为营业收入的减少。营业收入本期比上年同期减少-%，主要是因为销售量的大幅度降低。建议管理层与销售部分析销售量降低幅度最大的区域及产品，与市场部研究其降低原因，考虑销售量的降低是否具有不可逆转性，如为偶发行为，则需考虑促销、广告宣传等措施刺激销售增长，维持市场份额。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3660, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& (CLCB_A/CLCB_B-CLCB_A1/CLCB_B1)>0&&  (CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)-CLCB_B/CLCB_B1>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为原材料单价的上涨。建议管理层考虑：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 考虑原材料单价变动趋势是否与市场趋势相一致；3. 与供应商商讨原材料议价空间，同时加强成本控制管理，降低成本，提高利润。此外，建议管理层咨询市场部及采购部相关人员，如短期内原材料采购成本无法降低，则由市场部评估价格调整的可能性，以及产品对价格上升空间的接纳程度。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3661, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& CLCB_B-CLCB_B1>0&&                CLCB_B/CLCB_B1-(CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为材料耗用数量的增加。建议管理层考虑耗用数量增长幅度及趋势是否与订单一致，如与订单趋势不一致，进一步分析其原因：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 是否生产流程管理不善导致的材料损耗上升，管理层应考虑加强生产管理，减少损耗和质量事故，改善生产工艺；3. 是否采购部采购过程的材料不达标造成的材料损耗增大，管理层应考虑加强原材料入库前检测并对采购部进行相关考核；4. 耗用量增加可能导致原来的安全库存达不到生产的要求。管理层需考虑调整或优化安全库存的必要性，对原材料进行有效管理。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3662, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&ZJCB_A-ZJCB_A1>0&& (ZJCB_A-ZJCB_A1)-(CLCB_C-CLCB_C1)>0&& (ZJCB_A-ZJCB_A1)-(SDCB_A-SDCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(RGCB_A-RGCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(QTCB_A-QTCB_A1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为折旧成本的大幅度上涨。建议管理层查看设备投入以及设备运作情况，加大适用效率，与生产部及市场部讨论产量与销量的最合适配比，以达到利润最大化。同时，做好设备维护，减少大修及设备修理的支出，以达到控制成本的目的。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3663, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&SDCB_A-SDCB_A1>0&& (SDCB_A-SDCB_A1)-(CLCB_C-CLCB_C1)>0&& (SDCB_A-SDCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (SDCB_A-SDCB_A1)-(RGCB_A-RGCB_A1)>0&& (SDCB_A-SDCB_A1)-(QTCB_A-QTCB_A1)>0 ', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为水电成本的大幅度上涨。建议管理层关注水电成本的增长是因为水电单价的增长亦或因水电耗量增大而导致成本的增长，同时做好设备检修维护以及提高人工效率，确保设备在更低的耗电量中输出更大功率，从而控制成本。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3664, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&RGCB_A-RGCB_A1>0&& (RGCB_A-RGCB_A1)-(CLCB_C-CLCB_C1)>0&& (RGCB_A-RGCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (RGCB_A-RGCB_A1)-(SDCB_A-SDCB_A1)>0&& (RGCB_A-RGCB_A1)-(QTCB_A-QTCB_A1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为人工成本及费用的上涨。建议管理层考虑通过绩效改革，控制加班时间等措施，尽量减低人工成本上涨对总成本造成的压力。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3665, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1!=0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&QTCB_A-QTCB_A1>0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)>0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)>0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层咨询专业机构或采用企业咨询服务模块，对可能存在或延续的问题咨询专家意见。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3666, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1==0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& (CLCB_A/CLCB_B-CLCB_A1/CLCB_B1)>0&&  (CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)-CLCB_B/CLCB_B1>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长-%，主要是因为原材料单价的上涨。建议管理层考虑：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 考虑原材料单价变动趋势是否与市场趋势相一致；3. 与供应商商讨原材料议价空间，同时加强成本控制管理，降低成本，提高利润。此外，建议管理层咨询市场部及采购部相关人员，如短期内原材料采购成本无法降低，则由市场部评估价格调整的可能性，以及产品对价格上升空间的接纳程度。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3667, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1==0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& CLCB_B-CLCB_B1>0&&                CLCB_B/CLCB_B1-(CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长-%，主要是因为材料耗用数量的增加。建议管理层考虑耗用数量增长幅度及趋势是否与订单一致，如与订单趋势不一致，进一步分析其原因：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 是否生产流程管理不善导致的材料损耗上升，管理层应考虑加强生产管理，减少损耗和质量事故，改善生产工艺；3. 是否采购部采购过程的材料不达标造成的材料损耗增大，管理层应考虑加强原材料入库前检测并对采购部进行相关考核；4. 耗用量增加可能导致原来的安全库存达不到生产的要求。管理层需考虑调整或优化安全库存的必要性，对原材料进行有效管理。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3668, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1==0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&ZJCB_A-ZJCB_A1>0&& (ZJCB_A-ZJCB_A1)-(CLCB_C-CLCB_C1)>0&& (ZJCB_A-ZJCB_A1)-(SDCB_A-SDCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(RGCB_A-RGCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(QTCB_A-QTCB_A1)>0', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长-%，主要是因为折旧成本的大幅度上涨。建议管理层查看设备投入以及设备运作情况，加大适用效率，与生产部及市场部讨论产量与销量的最合适配比，以达到利润最大化。同时，做好设备维护，减少大修及设备修理的支出，以达到控制成本的目的。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3669, '2', '利润表首页预警', 'LR_AF-LR_AF1<0&&LR_F-LR_F1>0&&LR_F1==0&&(LR_F-LR_F1)-(LR_A1-LR_A)>0&&(LR_F-LR_F1)-(LR_O-LR_O1)>0&&(LR_F-LR_F1)-(LR_P-LR_P1)>0&&(LR_F-LR_F1)-(LR_Q-LR_Q1)>0&&(LR_F-LR_F1)-(LR_R-LR_R1)>0&&(LR_F-LR_F1)-(LR_S-LR_S1)>0&&(LR_F-LR_F1)-(LR_T1-LR_T)>0&&(LR_F-LR_F1)-(LR_U1-LR_U)>0&&  (LR_F-LR_F1)-(LR_W1-LR_W)>0&&  (LR_F-LR_F1)-(LR_X1-LR_X)>0&&  (LR_F-LR_F1)-(LR_Z1-LR_Z)>0&&  (LR_F-LR_F1)-(LR_AB-LR_AB1)>0&&  (LR_F-LR_F1)-(LR_AE-LR_AE1)>0&&SDCB_A-SDCB_A1>0&& (SDCB_A-SDCB_A1)-(CLCB_C-CLCB_C1)>0&& (SDCB_A-SDCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (SDCB_A-SDCB_A1)-(RGCB_A-RGCB_A1)>0&& (SDCB_A-SDCB_A1)-(QTCB_A-QTCB_A1)>0 ', '净利润本期比上期有所减少，主要是因为营业成本的增加。营业成本本期比上年同期增长-%，主要是因为水电成本的大幅度上涨。建议管理层关注水电成本的增长是因为水电单价的增长亦或因水电耗量增大而导致成本的增长，同时做好设备检修维护以及提高人工效率，确保设备在更低的耗电量中输出更大功率，从而控制成本。', '', NULL, 'G200001', NULL, 0);
