INSERT INTO `t_mode` VALUES (3683, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_F1-LR_F>0&& LR_F1==0&&(LR_F1-LR_F)-(LR_A-LR_A1)>0&& (LR_F1-LR_F)-(LR_O1-LR_O)>0&& (LR_F1-LR_F)-(LR_P1-LR_P)>0&& (LR_F1-LR_F)-(LR_Q1-LR_Q)>0&& (LR_F1-LR_F)-(LR_R1-LR_R)>0&& (LR_F1-LR_F)-(LR_S1-LR_S)>0&& (LR_F1-LR_F)-(LR_T-LR_T1)>0&& (LR_F1-LR_F)-(LR_U-LR_U1)>0&& (LR_F1-LR_F)-(LR_W-LR_W1)>0&& (LR_F1-LR_F)-(LR_X-LR_X1)>0&& (LR_F1-LR_F)-(LR_Z-LR_Z1)>0&& (LR_F1-LR_F)-(LR_AB1-LR_AB)>0&& (LR_F1-LR_F)-(LR_AE1-LR_AE)>0&& QTCB_A-QTCB_A1<0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)<0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)<0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)<0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)<0', '净利润本期比上期有所增加，主要是因为营业成本的减少。营业成本本期比上年同期减少-%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出减少导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后营业成本增长。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3684, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_O-LR_O1>0&&  LR_O1!=0&&(LR_O-LR_O1)-(LR_A1-LR_A)>0&&  (LR_O-LR_O1)-(LR_F-LR_F1)>0&&  (LR_O-LR_O1)-(LR_P-LR_P1)>0&&  (LR_O-LR_O1)-(LR_Q-LR_Q1)>0&&  (LR_O-LR_O1)-(LR_R-LR_R1)>0&&  (LR_O-LR_O1)-(LR_S-LR_S1)>0&&  (LR_O-LR_O1)-(LR_T1-LR_T)>0&&  (LR_O-LR_O1)-(LR_U1-LR_U)>0&&  (LR_O-LR_O1)-(LR_W1-LR_W)>0&&  (LR_O-LR_O1)-(LR_X1-LR_X)>0&&  (LR_O-LR_O1)-(LR_Z1-LR_Z)>0&&  (LR_O-LR_O1)-(LR_AB-LR_AB1)>0&&  (LR_O-LR_O1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为税金及附加的增加。税金及附加本期比上期增长{(LR_O-LR_O1)/LR_O1*100}%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收政策变化、进一步核查本期可抵扣税额，查看是否存在税率调增、不再享有免税政策以及大量发票不可抵扣的情况，从而规范发票管理及排查税务风险。', '{(LR_O-LR_O1)/LR_O1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3685, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_O-LR_O1>0&&  LR_O1==0&&(LR_O-LR_O1)-(LR_A1-LR_A)>0&&  (LR_O-LR_O1)-(LR_F-LR_F1)>0&&  (LR_O-LR_O1)-(LR_P-LR_P1)>0&&  (LR_O-LR_O1)-(LR_Q-LR_Q1)>0&&  (LR_O-LR_O1)-(LR_R-LR_R1)>0&&  (LR_O-LR_O1)-(LR_S-LR_S1)>0&&  (LR_O-LR_O1)-(LR_T1-LR_T)>0&&  (LR_O-LR_O1)-(LR_U1-LR_U)>0&&  (LR_O-LR_O1)-(LR_W1-LR_W)>0&&  (LR_O-LR_O1)-(LR_X1-LR_X)>0&&  (LR_O-LR_O1)-(LR_Z1-LR_Z)>0&&  (LR_O-LR_O1)-(LR_AB-LR_AB1)>0&&  (LR_O-LR_O1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为税金及附加的增加。税金及附加本期比上期增长-%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收政策变化、进一步核查本期可抵扣税额，查看是否存在税率调增、不再享有免税政策以及大量发票不可抵扣的情况，从而规范发票管理及排查税务风险。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3686, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_O1-LR_O>0&& LR_O1!=0&&(LR_O1-LR_O)-(LR_A-LR_A1)>0&& (LR_O1-LR_O)-(LR_F1-LR_F)>0&& (LR_O1-LR_O)-(LR_P1-LR_P)>0&& (LR_O1-LR_O)-(LR_Q1-LR_Q)>0&& (LR_O1-LR_O)-(LR_R1-LR_R)>0&& (LR_O1-LR_O)-(LR_S1-LR_S)>0&& (LR_O1-LR_O)-(LR_T-LR_T1)>0&& (LR_O1-LR_O)-(LR_U-LR_U1)>0&& (LR_O1-LR_O)-(LR_W-LR_W1)>0&& (LR_O1-LR_O)-(LR_X-LR_X1)>0&& (LR_O1-LR_O)-(LR_Z-LR_Z1)>0&& (LR_O1-LR_O)-(LR_AB1-LR_AB)>0&& (LR_O1-LR_O)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为税金及附加的减少。税金及附加本期比上期下降{(LR_O1-LR_O)/LR_O1*100}%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收是否存在税率调减、享有免税政策的情况，确保税负降低的合理性。', '{(LR_O1-LR_O)/LR_O1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3687, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_O1-LR_O>0&& LR_O1==0&&(LR_O1-LR_O)-(LR_A-LR_A1)>0&& (LR_O1-LR_O)-(LR_F1-LR_F)>0&& (LR_O1-LR_O)-(LR_P1-LR_P)>0&& (LR_O1-LR_O)-(LR_Q1-LR_Q)>0&& (LR_O1-LR_O)-(LR_R1-LR_R)>0&& (LR_O1-LR_O)-(LR_S1-LR_S)>0&& (LR_O1-LR_O)-(LR_T-LR_T1)>0&& (LR_O1-LR_O)-(LR_U-LR_U1)>0&& (LR_O1-LR_O)-(LR_W-LR_W1)>0&& (LR_O1-LR_O)-(LR_X-LR_X1)>0&& (LR_O1-LR_O)-(LR_Z-LR_Z1)>0&& (LR_O1-LR_O)-(LR_AB1-LR_AB)>0&& (LR_O1-LR_O)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为税金及附加的减少。税金及附加本期比上期下降-%，税金及附加同营业收入关联性较强，比较分析两期的税金及附加/营业收入，同时关注税收是否存在税率调减、享有免税政策的情况，确保税负降低的合理性。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3688, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1!=0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_RG-XSFY_RG1>0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为销售人工成本的增加。建议管理层查看人工成本增加的原因。如为员工人数增加导致的总体人工金额增加，需考虑销售团队人员数量与销售计划的匹配性；如为销售人员工资构成的调整等因素引起的人工成本的增加，需考虑销售人员的薪酬机制是否合理，是否与市场水平挂钩，薪酬的增加是否达到预期的市场开拓效果。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3689, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1!=0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_CL-XSFY_CL1>0&& (XSFY_CL-XSFY_CL1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_CL-XSFY_CL1)-(XSFY_QT-XSFY_QT1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为差旅费用的大幅度增加。建议管理层查看差旅费用增加幅度与人工成本、销售收入等的总体趋势是否一致，考虑是否需要加强成本费用的控制。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3690, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1!=0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_TG-XSFY_TG1>0&& (XSFY_TG-XSFY_TG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_TG-XSFY_TG1)-(XSFY_QT-XSFY_QT1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为广告费、促销费、推广费、设计费支出的增加。建议管理层查看广告及促销费用增加的趋势与销售收入的变动趋势是否一致，评估费用增加对收入的影响，是否带来了预期的市场效果，从而考虑是否需要调整市场开拓方针。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3691, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1!=0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_ZD-XSFY_ZD1>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_RG-XSFY_RG1)>0&& (XSFY_ZD-XSFY_ZD1)-(XSFY_QT-XSFY_QT1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要是因为业务招待费的增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3692, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1!=0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_QT-XSFY_QT1>0&& (XSFY_QT-XSFY_QT1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_QT-XSFY_QT1)-(XSFY_RG-XSFY_RG1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长{(LR_P-LR_P1)/LR_P1*100}%，主要由除人工、差旅、市场推广、业务招待等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后的费用增长。', '{(LR_P-LR_P1)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3693, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_P-LR_P1>0&&  LR_P1==0&&(LR_P-LR_P1)-(LR_A1-LR_A)>0&&  (LR_P-LR_P1)-(LR_F-LR_F1)>0&&  (LR_P-LR_P1)-(LR_O-LR_O1)>0&&  (LR_P-LR_P1)-(LR_Q-LR_Q1)>0&&  (LR_P-LR_P1)-(LR_R-LR_R1)>0&&(LR_P-LR_P1)-(LR_S-LR_S1)>0&&(LR_P-LR_P1)-(LR_T1-LR_T)>0&&(LR_P-LR_P1)-(LR_U1-LR_U)>0&&  (LR_P-LR_P1)-(LR_W1-LR_W)>0&&  (LR_P-LR_P1)-(LR_X1-LR_X)>0&&  (LR_P-LR_P1)-(LR_Z1-LR_Z)>0&&  (LR_P-LR_P1)-(LR_AB-LR_AB1)>0&&  (LR_P-LR_P1)-(LR_AE-LR_AE1)>0&&XSFY_RG-XSFY_RG1>0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)>0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)>0', '净利润本期比上期有所减少，主要是因为销售费用的增加。销售费用本期比上年同期增长-%，主要是因为销售人工成本的增加。建议管理层查看人工成本增加的原因。如为员工人数增加导致的总体人工金额增加，需考虑销售团队人员数量与销售计划的匹配性；如为销售人员工资构成的调整等因素引起的人工成本的增加，需考虑销售人员的薪酬机制是否合理，是否与市场水平挂钩，薪酬的增加是否达到预期的市场开拓效果。', '', NULL, 'G200001', NULL, 0);
