INSERT INTO `t_mode` VALUES (3702, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_P1-LR_P>0&& LR_P1!=0&&(LR_P1-LR_P)-(LR_A-LR_A1)>0&& (LR_P1-LR_P)-(LR_F1-LR_F)>0&& (LR_P1-LR_P)-(LR_O1-LR_O)>0&& (LR_P1-LR_P)-(LR_Q1-LR_Q)>0&& (LR_P1-LR_P)-(LR_R1-LR_R)>0&& (LR_P1-LR_P)-(LR_S1-LR_S)>0&& (LR_P1-LR_P)-(LR_T-LR_T1)>0&& (LR_P1-LR_P)-(LR_U-LR_U1)>0&& (LR_P1-LR_P)-(LR_W-LR_W1)>0&& (LR_P1-LR_P)-(LR_X-LR_X1)>0&& (LR_P1-LR_P)-(LR_Z-LR_Z1)>0&& (LR_P1-LR_P)-(LR_AB1-LR_AB)>0&& (LR_P1-LR_P)-(LR_AE1-LR_AE)>0&&XSFY_QT-XSFY_QT1<0&& (XSFY_QT-XSFY_QT1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_QT-XSFY_QT1)-(XSFY_RG-XSFY_RG1)<0', '净利润本期比上期有所增加，主要是因为销售费用的减少。销售费用本期比上年同期减少{(LR_P1-LR_P)/LR_P1*100}%，主要由除人工、差旅、市场推广、业务招待等主要项目外的剩余支出减少所导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后的费用减少。', '{(LR_P1-LR_P)/LR_P1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3703, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_P1-LR_P>0&& LR_P1==0&&(LR_P1-LR_P)-(LR_A-LR_A1)>0&& (LR_P1-LR_P)-(LR_F1-LR_F)>0&& (LR_P1-LR_P)-(LR_O1-LR_O)>0&& (LR_P1-LR_P)-(LR_Q1-LR_Q)>0&& (LR_P1-LR_P)-(LR_R1-LR_R)>0&& (LR_P1-LR_P)-(LR_S1-LR_S)>0&& (LR_P1-LR_P)-(LR_T-LR_T1)>0&& (LR_P1-LR_P)-(LR_U-LR_U1)>0&& (LR_P1-LR_P)-(LR_W-LR_W1)>0&& (LR_P1-LR_P)-(LR_X-LR_X1)>0&& (LR_P1-LR_P)-(LR_Z-LR_Z1)>0&& (LR_P1-LR_P)-(LR_AB1-LR_AB)>0&& (LR_P1-LR_P)-(LR_AE1-LR_AE)>0&&XSFY_RG-XSFY_RG1<0&& (XSFY_RG-XSFY_RG1)-(XSFY_CL-XSFY_CL1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_TG-XSFY_TG1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_ZD-XSFY_ZD1)<0&& (XSFY_RG-XSFY_RG1)-(XSFY_QT-XSFY_QT1)<0', '净利润本期比上期有所增加，主要是因为销售费用的减少。销售费用本期比上年同期减少-%，主要是因为销售人工成本的减少。建议管理层查看人工成本减少的原因。如为员工人数减少导致的总体人工金额减少，需考虑销售团队人员的调整对销售计划已经未来销售收入的总体影响；如为销售人员工资构成的调整等因素引起的人工成本的减少，需考虑销售人员对薪酬机制的满意程度以及可能引起的人员流动，从而评估销售人员流动对销售收入及增长可能产生的影响。', '', NULL, 'G200001', NULL, 0);
