INSERT INTO `t_mode` VALUES (3710, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_Q-LR_Q1>0&& LR_Q1!=0&&(LR_Q-LR_Q1)-(LR_A1-LR_A)>0&& (LR_Q-LR_Q1)-(LR_F-LR_F1)>0&& (LR_Q-LR_Q1)-(LR_O-LR_O1)>0&& (LR_Q-LR_Q1)-(LR_P-LR_P1)>0&& (LR_Q-LR_Q1)-(LR_R-LR_R1)>0&& (LR_Q-LR_Q1)-(LR_S-LR_S1)>0&& (LR_Q-LR_Q1)-(LR_T1-LR_T)>0&& (LR_Q-LR_Q1)-(LR_U1-LR_U)>0&& (LR_Q-LR_Q1)-(LR_W1-LR_W)>0&& (LR_Q-LR_Q1)-(LR_X1-LR_X)>0&& (LR_Q-LR_Q1)-(LR_Z1-LR_Z)>0&& (LR_Q-LR_Q1)-(LR_AB-LR_AB1)>0&& (LR_Q-LR_Q1)-(LR_AE-LR_AE1)>0&&GLFY_ZD-GLFY_ZD1>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_ZD-GLFY_ZD1)-(GLFY_QT-GLFY_QT1)>0', '净利润本期比上期有所减少，主要是因为管理费用的增加。管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是因为业务招待费增加。建议管理层关注业务招待费增长的主要原因，防范出现员工大量不合理费用支出情形。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3711, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_Q-LR_Q1>0&& LR_Q1!=0&&(LR_Q-LR_Q1)-(LR_A1-LR_A)>0&& (LR_Q-LR_Q1)-(LR_F-LR_F1)>0&& (LR_Q-LR_Q1)-(LR_O-LR_O1)>0&& (LR_Q-LR_Q1)-(LR_P-LR_P1)>0&& (LR_Q-LR_Q1)-(LR_R-LR_R1)>0&& (LR_Q-LR_Q1)-(LR_S-LR_S1)>0&& (LR_Q-LR_Q1)-(LR_T1-LR_T)>0&& (LR_Q-LR_Q1)-(LR_U1-LR_U)>0&& (LR_Q-LR_Q1)-(LR_W1-LR_W)>0&& (LR_Q-LR_Q1)-(LR_X1-LR_X)>0&& (LR_Q-LR_Q1)-(LR_Z1-LR_Z)>0&& (LR_Q-LR_Q1)-(LR_AB-LR_AB1)>0&& (LR_Q-LR_Q1)-(LR_AE-LR_AE1)>0&&GLFY_QT-GLFY_QT1>0&& (GLFY_QT-GLFY_QT1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZD-GLFY_ZD1)>0', '净利润本期比上期有所减少，主要是因为管理费用的增加。管理费用本期比上年同期增长{(LR_Q-LR_Q1)/LR_Q1*100}%，主要是由于除人工、折旧、业务招待外的剩余支出的增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层采用本系统在线顾问服务模块中的顾问咨询功能，对可能存在或延续的问题咨询专家意见。', '{(LR_Q-LR_Q1)/LR_Q1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3712, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_Q-LR_Q1>0&& LR_Q1==0&&(LR_Q-LR_Q1)-(LR_A1-LR_A)>0&& (LR_Q-LR_Q1)-(LR_F-LR_F1)>0&& (LR_Q-LR_Q1)-(LR_O-LR_O1)>0&& (LR_Q-LR_Q1)-(LR_P-LR_P1)>0&& (LR_Q-LR_Q1)-(LR_R-LR_R1)>0&& (LR_Q-LR_Q1)-(LR_S-LR_S1)>0&& (LR_Q-LR_Q1)-(LR_T1-LR_T)>0&& (LR_Q-LR_Q1)-(LR_U1-LR_U)>0&& (LR_Q-LR_Q1)-(LR_W1-LR_W)>0&& (LR_Q-LR_Q1)-(LR_X1-LR_X)>0&& (LR_Q-LR_Q1)-(LR_Z1-LR_Z)>0&& (LR_Q-LR_Q1)-(LR_AB-LR_AB1)>0&& (LR_Q-LR_Q1)-(LR_AE-LR_AE1)>0&&GLFY_RG-GLFY_RG1>0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZJ-GLFY_ZJ1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_RG-GLFY_RG1)-(GLFY_QT-GLFY_QT1)>0', '净利润本期比上期有所减少，主要是因为管理费用的增加。管理费用本期比上年同期增长-%，主要是因为管理人员人工成本增加。建议管理层查看工资上涨的原因，与人力资源部门讨论控制工资上涨的方式。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3713, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_Q-LR_Q1>0&& LR_Q1==0&&(LR_Q-LR_Q1)-(LR_A1-LR_A)>0&& (LR_Q-LR_Q1)-(LR_F-LR_F1)>0&& (LR_Q-LR_Q1)-(LR_O-LR_O1)>0&& (LR_Q-LR_Q1)-(LR_P-LR_P1)>0&& (LR_Q-LR_Q1)-(LR_R-LR_R1)>0&& (LR_Q-LR_Q1)-(LR_S-LR_S1)>0&& (LR_Q-LR_Q1)-(LR_T1-LR_T)>0&& (LR_Q-LR_Q1)-(LR_U1-LR_U)>0&& (LR_Q-LR_Q1)-(LR_W1-LR_W)>0&& (LR_Q-LR_Q1)-(LR_X1-LR_X)>0&& (LR_Q-LR_Q1)-(LR_Z1-LR_Z)>0&& (LR_Q-LR_Q1)-(LR_AB-LR_AB1)>0&& (LR_Q-LR_Q1)-(LR_AE-LR_AE1)>0&&GLFY_ZJ-GLFY_ZJ1>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_RG-GLFY_RG1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_ZD-GLFY_ZD1)>0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_QT-GLFY_QT1)>0', '净利润本期比上期有所减少，主要是因为管理费用的增加。管理费用本期比上年同期增长-%，主要是因为办公用固定资产大幅度增加，导致折旧金额相应增加，建议管理层做好固定资产管理，包括固定资产卡片，台账等的管理等。此外，建议管理层评估大幅度增加管理用固定资产的必要性，做好支出管理。', '', NULL, 'G200001', NULL, 0);
