INSERT INTO `t_mode` VALUES (3717, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_Q1-LR_Q>0&& LR_Q1!=0&&(LR_Q1-LR_Q)-(LR_A-LR_A1)>0&& (LR_Q1-LR_Q)-(LR_F1-LR_F)>0&& (LR_Q1-LR_Q)-(LR_O1-LR_O)>0&& (LR_Q1-LR_Q)-(LR_P1-LR_P)>0&& (LR_Q1-LR_Q)-(LR_R1-LR_R)>0&& (LR_Q1-LR_Q)-(LR_S1-LR_S)>0&& (LR_Q1-LR_Q)-(LR_T-LR_T1)>0&& (LR_Q1-LR_Q)-(LR_U-LR_U1)>0&& (LR_Q1-LR_Q)-(LR_W-LR_W1)>0&& (LR_Q1-LR_Q)-(LR_X-LR_X1)>0&& (LR_Q1-LR_Q)-(LR_Z-LR_Z1)>0&& (LR_Q1-LR_Q)-(LR_AB1-LR_AB)>0&& (LR_Q1-LR_Q)-(LR_AE1-LR_AE)>0&&GLFY_ZJ-GLFY_ZJ1<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_RG-GLFY_RG1)<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_ZD-GLFY_ZD1)<0&& (GLFY_ZJ-GLFY_ZJ1)-(GLFY_QT-GLFY_QT1)<0', '净利润本期比上期有所增加，主要是因为管理费用的减少。管理费用本期比上年同期减少{(LR_Q1-LR_Q)/LR_Q1*100}%，主要是因为折旧减少。建议管理层查看折旧减少原因，如本年内大量报废办公设备，需考虑未来的固定资产购置计划，以及办公设备的购置对现金流以及净利润的影响。', '{(LR_Q1-LR_Q)/LR_Q1*100}', NULL, 'G200001', NULL, 0);
