INSERT INTO `t_mode` VALUES (3723, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_Q1-LR_Q>0&& LR_Q1==0&&(LR_Q1-LR_Q)-(LR_A-LR_A1)>0&& (LR_Q1-LR_Q)-(LR_F1-LR_F)>0&& (LR_Q1-LR_Q)-(LR_O1-LR_O)>0&& (LR_Q1-LR_Q)-(LR_P1-LR_P)>0&& (LR_Q1-LR_Q)-(LR_R1-LR_R)>0&& (LR_Q1-LR_Q)-(LR_S1-LR_S)>0&& (LR_Q1-LR_Q)-(LR_T-LR_T1)>0&& (LR_Q1-LR_Q)-(LR_U-LR_U1)>0&& (LR_Q1-LR_Q)-(LR_W-LR_W1)>0&& (LR_Q1-LR_Q)-(LR_X-LR_X1)>0&& (LR_Q1-LR_Q)-(LR_Z-LR_Z1)>0&& (LR_Q1-LR_Q)-(LR_AB1-LR_AB)>0&& (LR_Q1-LR_Q)-(LR_AE1-LR_AE)>0&&GLFY_QT-GLFY_QT1<0&& (GLFY_QT-GLFY_QT1)-(GLFY_RG-GLFY_RG1)<0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZJ-GLFY_ZJ1)<0&& (GLFY_QT-GLFY_QT1)-(GLFY_ZD-GLFY_ZD1)<0', '净利润本期比上期有所增加，主要是因为管理费用的减少。管理费用本期比上年同期减少-%，主要是由于除人工、折旧、业务招待外的剩余支出的减少导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，应扣除这一事项后进行分析。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3724, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_R-LR_R1>0&& LR_R1!=0&&(LR_R-LR_R1)-(LR_A1-LR_A)>0&& (LR_R-LR_R1)-(LR_F-LR_F1)>0&& (LR_R-LR_R1)-(LR_O-LR_O1)>0&& (LR_R-LR_R1)-(LR_P-LR_P1)>0&& (LR_R-LR_R1)-(LR_Q-LR_Q1)>0&& (LR_R-LR_R1)-(LR_S-LR_S1)>0&& (LR_R-LR_R1)-(LR_T1-LR_T)>0&& (LR_R-LR_R1)-(LR_U1-LR_U)>0&& (LR_R-LR_R1)-(LR_W1-LR_W)>0&& (LR_R-LR_R1)-(LR_X1-LR_X)>0&& (LR_R-LR_R1)-(LR_Z1-LR_Z)>0&& (LR_R-LR_R1)-(LR_AB-LR_AB1)>0&& (LR_R-LR_R1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为财务费用的增加。财务费用本期比上期增长{(LR_R-LR_R1)/LR_R1*100}%，财务费用大幅度增加，成为净利润减少的主因。财务费用的大幅度增加，主要是因为本期贷款金额的增加。建议管理层结合资金情况，贷款情况，做好资金用途的管理，同时评估未来还款付息对资金流产生的压力，评估资金状况是否足以承受未来的还本付息所需的现金流。', '{(LR_R-LR_R1)/LR_R1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3725, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_R-LR_R1>0&& LR_R1==0&&(LR_R-LR_R1)-(LR_A1-LR_A)>0&& (LR_R-LR_R1)-(LR_F-LR_F1)>0&& (LR_R-LR_R1)-(LR_O-LR_O1)>0&& (LR_R-LR_R1)-(LR_P-LR_P1)>0&& (LR_R-LR_R1)-(LR_Q-LR_Q1)>0&& (LR_R-LR_R1)-(LR_S-LR_S1)>0&& (LR_R-LR_R1)-(LR_T1-LR_T)>0&& (LR_R-LR_R1)-(LR_U1-LR_U)>0&& (LR_R-LR_R1)-(LR_W1-LR_W)>0&& (LR_R-LR_R1)-(LR_X1-LR_X)>0&& (LR_R-LR_R1)-(LR_Z1-LR_Z)>0&& (LR_R-LR_R1)-(LR_AB-LR_AB1)>0&& (LR_R-LR_R1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为财务费用的增加。财务费用本期比上期增长-%，财务费用大幅度增加，成为净利润减少的主因。财务费用的大幅度增加，主要是因为本期贷款金额的增加。建议管理层结合资金情况，贷款情况，做好资金用途的管理，同时评估未来还款付息对资金流产生的压力，评估资金状况是否足以承受未来的还本付息所需的现金流。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3726, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_R1-LR_R>0&& LR_R1!=0&&(LR_R1-LR_R)-(LR_A-LR_A1)>0&& (LR_R1-LR_R)-(LR_F1-LR_F)>0&& (LR_R1-LR_R)-(LR_O1-LR_O)>0&& (LR_R1-LR_R)-(LR_P1-LR_P)>0&& (LR_R1-LR_R)-(LR_Q1-LR_Q)>0&& (LR_R1-LR_R)-(LR_S1-LR_S)>0&& (LR_R1-LR_R)-(LR_T-LR_T1)>0&& (LR_R1-LR_R)-(LR_U-LR_U1)>0&& (LR_R1-LR_R)-(LR_W-LR_W1)>0&& (LR_R1-LR_R)-(LR_X-LR_X1)>0&& (LR_R1-LR_R)-(LR_Z-LR_Z1)>0&& (LR_R1-LR_R)-(LR_AB1-LR_AB)>0&& (LR_R1-LR_R)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为财务费用的减少。财务费用本期比上期减少{(LR_R1-LR_R)/LR_R1*100}%，本期财务费用大幅度减少，主要是因为利息支出的减少。建议管理层结合贷款及现金流情况，考虑是否需要更新融资计划或进行增资，如需进行股权或债权融资，需考虑未来换本付息等对现金流的压力。', '{(LR_R1-LR_R)/LR_R1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3727, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_R1-LR_R>0&& LR_R1==0&&(LR_R1-LR_R)-(LR_A-LR_A1)>0&& (LR_R1-LR_R)-(LR_F1-LR_F)>0&& (LR_R1-LR_R)-(LR_O1-LR_O)>0&& (LR_R1-LR_R)-(LR_P1-LR_P)>0&& (LR_R1-LR_R)-(LR_Q1-LR_Q)>0&& (LR_R1-LR_R)-(LR_S1-LR_S)>0&& (LR_R1-LR_R)-(LR_T-LR_T1)>0&& (LR_R1-LR_R)-(LR_U-LR_U1)>0&& (LR_R1-LR_R)-(LR_W-LR_W1)>0&& (LR_R1-LR_R)-(LR_X-LR_X1)>0&& (LR_R1-LR_R)-(LR_Z-LR_Z1)>0&& (LR_R1-LR_R)-(LR_AB1-LR_AB)>0&& (LR_R1-LR_R)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为财务费用的减少。财务费用本期比上期减少-%，本期财务费用大幅度减少，主要是因为利息支出的减少。建议管理层结合贷款及现金流情况，考虑是否需要更新融资计划或进行增资，如需进行股权或债权融资，需考虑未来换本付息等对现金流的压力。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3728, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_S-LR_S1>0&& LR_S1!=0&&(LR_S-LR_S1)-(LR_A1-LR_A)>0&& (LR_S-LR_S1)-(LR_F-LR_F1)>0&& (LR_S-LR_S1)-(LR_O-LR_O1)>0&& (LR_S-LR_S1)-(LR_P-LR_P1)>0&& (LR_S-LR_S1)-(LR_Q-LR_Q1)>0&& (LR_S-LR_S1)-(LR_R-LR_R1)>0&& (LR_S-LR_S1)-(LR_T1-LR_T)>0&& (LR_S-LR_S1)-(LR_U1-LR_U)>0&& (LR_S-LR_S1)-(LR_W1-LR_W)>0&& (LR_S-LR_S1)-(LR_X1-LR_X)>0&& (LR_S-LR_S1)-(LR_Z1-LR_Z)>0&& (LR_S-LR_S1)-(LR_AB-LR_AB1)>0&& (LR_S-LR_S1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为资产减值损失的增加。资产减值损失本期比上期增长{(LR_S-LR_S1)/LR_S1*100}%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施减少损失，同时，特别警惕因技术变革、行业创新导致公司资产大幅度减值的情况。', '{(LR_S-LR_S1)/LR_S1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3729, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_S-LR_S1>0&& LR_S1==0&&(LR_S-LR_S1)-(LR_A1-LR_A)>0&& (LR_S-LR_S1)-(LR_F-LR_F1)>0&& (LR_S-LR_S1)-(LR_O-LR_O1)>0&& (LR_S-LR_S1)-(LR_P-LR_P1)>0&& (LR_S-LR_S1)-(LR_Q-LR_Q1)>0&& (LR_S-LR_S1)-(LR_R-LR_R1)>0&& (LR_S-LR_S1)-(LR_T1-LR_T)>0&& (LR_S-LR_S1)-(LR_U1-LR_U)>0&& (LR_S-LR_S1)-(LR_W1-LR_W)>0&& (LR_S-LR_S1)-(LR_X1-LR_X)>0&& (LR_S-LR_S1)-(LR_Z1-LR_Z)>0&& (LR_S-LR_S1)-(LR_AB-LR_AB1)>0&& (LR_S-LR_S1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为资产减值损失的增加。资产减值损失本期比上期增长-%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施减少损失，同时，特别警惕因技术变革、行业创新导致公司资产大幅度减值的情况。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3730, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_S1-LR_S>0&& LR_S1!=0&&(LR_S1-LR_S)-(LR_A-LR_A1)>0&& (LR_S1-LR_S)-(LR_F1-LR_F)>0&& (LR_S1-LR_S)-(LR_O1-LR_O)>0&& (LR_S1-LR_S)-(LR_P1-LR_P)>0&& (LR_S1-LR_S)-(LR_Q1-LR_Q)>0&& (LR_S1-LR_S)-(LR_R1-LR_R)>0&& (LR_S1-LR_S)-(LR_T-LR_T1)>0&& (LR_S1-LR_S)-(LR_U-LR_U1)>0&& (LR_S1-LR_S)-(LR_W-LR_W1)>0&& (LR_S1-LR_S)-(LR_X-LR_X1)>0&& (LR_S1-LR_S)-(LR_Z-LR_Z1)>0&& (LR_S1-LR_S)-(LR_AB1-LR_AB)>0&& (LR_S1-LR_S)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为资产减值损失的减少。资产减值损失本期比上期减少{(LR_S1-LR_S)/LR_S1*100}%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施进一步降低损失，提升利润空间，同时，需防范因技术变革、行业创新初步导致公司资产减值的情形。', '{(LR_S1-LR_S)/LR_S1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3731, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_S1-LR_S>0&& LR_S1==0&&(LR_S1-LR_S)-(LR_A-LR_A1)>0&& (LR_S1-LR_S)-(LR_F1-LR_F)>0&& (LR_S1-LR_S)-(LR_O1-LR_O)>0&& (LR_S1-LR_S)-(LR_P1-LR_P)>0&& (LR_S1-LR_S)-(LR_Q1-LR_Q)>0&& (LR_S1-LR_S)-(LR_R1-LR_R)>0&& (LR_S1-LR_S)-(LR_T-LR_T1)>0&& (LR_S1-LR_S)-(LR_U-LR_U1)>0&& (LR_S1-LR_S)-(LR_W-LR_W1)>0&& (LR_S1-LR_S)-(LR_X-LR_X1)>0&& (LR_S1-LR_S)-(LR_Z-LR_Z1)>0&& (LR_S1-LR_S)-(LR_AB1-LR_AB)>0&& (LR_S1-LR_S)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为资产减值损失的减少。资产减值损失本期比上期减少-%，建议管理层关注资产减值损失的明细，了解减值原因和具体金额，考虑是否可采取相应措施进一步降低损失，提升利润空间，同时，需防范因技术变革、行业创新初步导致公司资产减值的情形。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3732, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_T-LR_T1>0&& LR_T1!=0&&(LR_T-LR_T1)-(LR_F1-LR_F)>0&& (LR_T-LR_T1)-(LR_O1-LR_O)>0&& (LR_T-LR_T1)-(LR_P1-LR_P)>0&& (LR_T-LR_T1)-(LR_Q1-LR_Q)>0&& (LR_T-LR_T1)-(LR_R1-LR_R)>0&& (LR_T-LR_T1)-(LR_S1-LR_S)>0&& (LR_T-LR_T1)-(LR_A-LR_A1)>0&& (LR_T-LR_T1)-(LR_U-LR_U1)>0&& (LR_T-LR_T1)-(LR_W-LR_W1)>0&& (LR_T-LR_T1)-(LR_X-LR_X1)>0&& (LR_T-LR_T1)-(LR_Z-LR_Z1)>0&& (LR_T-LR_T1)-(LR_AB1-LR_AB)>0&& (LR_T-LR_T1)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为公允价值变动的增加。公允价值变动本期比上期增长{(LR_T-LR_T1)/LR_T1*100}%，由于公允价值变动为非经常性收益，剔除后，营业利润将下降。建议管理层考虑公允价值变动的性质，具体分析其增加原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_T-LR_T1)/LR_T1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3733, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_T-LR_T1>0&& LR_T1==0&&(LR_T-LR_T1)-(LR_F1-LR_F)>0&& (LR_T-LR_T1)-(LR_O1-LR_O)>0&& (LR_T-LR_T1)-(LR_P1-LR_P)>0&& (LR_T-LR_T1)-(LR_Q1-LR_Q)>0&& (LR_T-LR_T1)-(LR_R1-LR_R)>0&& (LR_T-LR_T1)-(LR_S1-LR_S)>0&& (LR_T-LR_T1)-(LR_A-LR_A1)>0&& (LR_T-LR_T1)-(LR_U-LR_U1)>0&& (LR_T-LR_T1)-(LR_W-LR_W1)>0&& (LR_T-LR_T1)-(LR_X-LR_X1)>0&& (LR_T-LR_T1)-(LR_Z-LR_Z1)>0&& (LR_T-LR_T1)-(LR_AB1-LR_AB)>0&& (LR_T-LR_T1)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为公允价值变动的增加。公允价值变动本期比上期增长-%，由于公允价值变动为非经常性收益，剔除后，营业利润将下降。建议管理层考虑公允价值变动的性质，具体分析其增加原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3734, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_T1-LR_T>0&& LR_T1!=0&&(LR_T1-LR_T)-(LR_F-LR_F1)>0&& (LR_T1-LR_T)-(LR_O-LR_O1)>0&& (LR_T1-LR_T)-(LR_P-LR_P1)>0&& (LR_T1-LR_T)-(LR_Q-LR_Q1)>0&& (LR_T1-LR_T)-(LR_R-LR_R1)>0&& (LR_T1-LR_T)-(LR_S-LR_S1)>0&& (LR_T1-LR_T)-(LR_A1-LR_A)>0&& (LR_T1-LR_T)-(LR_U1-LR_U)>0&& (LR_T1-LR_T)-(LR_W1-LR_W)>0&& (LR_T1-LR_T)-(LR_X1-LR_X)>0&& (LR_T1-LR_T)-(LR_Z1-LR_Z)>0&& (LR_T1-LR_T)-(LR_AB-LR_AB1)>0&& (LR_T1-LR_T)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为公允价值变动的减少。公允价值变动本期比上期减少{(LR_T1-LR_T)/LR_T1*100}%，本期公允价值变动大幅度下降，管理层需关注变动原因，评估现有投资风险。由于公允价值变动为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑公允价值变动的性质及原因，减少公允价值变动对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '{(LR_T1-LR_T)/LR_T1*100}', NULL, 'G200001', NULL, 0);
