INSERT INTO `t_mode` VALUES (3747, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_X1-LR_X>0&& LR_X1==0&&(LR_X1-LR_X)-(LR_F-LR_F1)>0&& (LR_X1-LR_X)-(LR_O-LR_O1)>0&& (LR_X1-LR_X)-(LR_P-LR_P1)>0&& (LR_X1-LR_X)-(LR_Q-LR_Q1)>0&& (LR_X1-LR_X)-(LR_R-LR_R1)>0&& (LR_X1-LR_X)-(LR_S-LR_S1)>0&& (LR_X1-LR_X)-(LR_A1-LR_A)>0&& (LR_X1-LR_X)-(LR_T1-LR_T)>0&& (LR_X1-LR_X)-(LR_U1-LR_U)>0&& (LR_X1-LR_X)-(LR_W1-LR_W)>0&& (LR_X1-LR_X)-(LR_Z1-LR_Z)>0&& (LR_X1-LR_X)-(LR_AB-LR_AB1)>0&& (LR_X1-LR_X)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为其他收益的减少。其他收益本期比上期减少-%，本期其他收益大幅度下降。由于其他收益为非经常性收益，剔除后，营业利润将大幅度下降。建议管理层考虑其他收益的性质，具体分析其减少原因，减少其他收益对净利润的影响金额，从而增强投资者对企业业务经营的信心。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3748, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_Z-LR_Z1>0&& LR_Z1!=0&&(LR_Z-LR_Z1)-(LR_F1-LR_F)>0&& (LR_Z-LR_Z1)-(LR_O1-LR_O)>0&& (LR_Z-LR_Z1)-(LR_P1-LR_P)>0&& (LR_Z-LR_Z1)-(LR_Q1-LR_Q)>0&& (LR_Z-LR_Z1)-(LR_R1-LR_R)>0&& (LR_Z-LR_Z1)-(LR_S1-LR_S)>0&& (LR_Z-LR_Z1)-(LR_A-LR_A1)>0&& (LR_Z-LR_Z1)-(LR_T-LR_T1)>0&& (LR_Z-LR_Z1)-(LR_U-LR_U1)>0&& (LR_Z-LR_Z1)-(LR_W-LR_W1)>0&& (LR_Z-LR_Z1)-(LR_X-LR_X1)>0&& (LR_Z-LR_Z1)-(LR_AB1-LR_AB)>0&& (LR_Z-LR_Z1)-(LR_AE1-LR_AE)>0', '净利润本期比上期有所增加，主要是因为营业外收入的增加。营业外收入本期比上期增长{(LR_Z-LR_Z1)/LR_Z1*100}%，由于营业外收入为非经营性收入，不具有持续性，在融资、上市等接受尽调或者审计时，均将作为模拟调整的对象，因此，建议管理层查看以前年度营业外收入的性质，并剔除历史数据中营业外收入对净利润的影响后，再分析净利润的变动原因。', '{(LR_Z-LR_Z1)/LR_Z1*100}', NULL, 'G200001', NULL, 0);
