INSERT INTO `t_mode` VALUES (3750, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_Z1-LR_Z>0&& LR_Z1!=0&&(LR_Z1-LR_Z)-(LR_F-LR_F1)>0&& (LR_Z1-LR_Z)-(LR_O-LR_O1)>0&& (LR_Z1-LR_Z)-(LR_P-LR_P1)>0&& (LR_Z1-LR_Z)-(LR_Q-LR_Q1)>0&& (LR_Z1-LR_Z)-(LR_R-LR_R1)>0&& (LR_Z1-LR_Z)-(LR_S-LR_S1)>0&& (LR_Z1-LR_Z)-(LR_A1-LR_A)>0&& (LR_Z1-LR_Z)-(LR_T1-LR_T)>0&& (LR_Z1-LR_Z)-(LR_U1-LR_U)>0&& (LR_Z1-LR_Z)-(LR_W1-LR_W)>0&& (LR_Z1-LR_Z)-(LR_X1-LR_X)>0&& (LR_Z1-LR_Z)-(LR_AB-LR_AB1)>0&& (LR_Z1-LR_Z)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为营业外收入的减少。营业外收入本期比上期减少{(LR_Z1-LR_Z)/LR_Z1*100}%，营业外收入的减少，管理层需警惕。由于营业外收入非经营性收入，不具有持续性，在融资、上市等接受尽调或者审计时，均将作为模拟调整的对象，因此，建议管理层查看以前年度营业外收入的性质，考虑主营业务的发展是否足以支撑企业未来的需求。', '{(LR_Z1-LR_Z)/LR_Z1*100}', NULL, 'G200001', NULL, 0);
