INSERT INTO `t_mode` VALUES (3752, '2', '利润表首页预警', 'LR_AF1-LR_AF>0&& LR_AB-LR_AB1>0&& LR_AB1!=0&&(LR_AB-LR_AB1)-(LR_A1-LR_A)>0&& (LR_AB-LR_AB1)-(LR_O-LR_O1)>0&& (LR_AB-LR_AB1)-(LR_P-LR_P1)>0&& (LR_AB-LR_AB1)-(LR_Q-LR_Q1)>0&& (LR_AB-LR_AB1)-(LR_R-LR_R1)>0&& (LR_AB-LR_AB1)-(LR_S-LR_S1)>0&& (LR_AB-LR_AB1)-(LR_T1-LR_T)>0&& (LR_AB-LR_AB1)-(LR_U1-LR_U)>0&& (LR_AB-LR_AB1)-(LR_W1-LR_W)>0&& (LR_AB-LR_AB1)-(LR_X1-LR_X)>0&& (LR_AB-LR_AB1)-(LR_Z1-LR_Z)>0&& (LR_AB-LR_AB1)-(LR_F-LR_F1)>0&& (LR_AB-LR_AB1)-(LR_AE-LR_AE1)>0', '净利润本期比上期有所减少，主要是因为营业外支出的增加。营业外支出本期比上期增长{(LR_AB-LR_AB1)/LR_AB1*100}%，营业外支出大幅增加，建议管理层关注是否发生了大额的资产处置损失，资产处置是否履行了审批制度并关注大额资产处置的原因。另外，营业外支出为非经营性支出，不具有持续性。建议管理层剔除两期营业外支出后，重新评估净利润的变动情况及趋势，并相应做出管理决策。', '{(LR_AB-LR_AB1)/LR_AB1*100}', NULL, 'G200001', NULL, 0);
