INSERT INTO `t_mode` VALUES (3758, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_AE1-LR_AE>0&& LR_AE1!=0&&(LR_AE1-LR_AE)-(LR_A-LR_A1)>0&& (LR_AE1-LR_AE)-(LR_O1-LR_O)>0&& (LR_AE1-LR_AE)-(LR_P1-LR_P)>0&& (LR_AE1-LR_AE)-(LR_Q1-LR_Q)>0&& (LR_AE1-LR_AE)-(LR_R1-LR_R)>0&& (LR_AE1-LR_AE)-(LR_S1-LR_S)>0&& (LR_AE1-LR_AE)-(LR_T-LR_T1)>0&& (LR_AE1-LR_AE)-(LR_U-LR_U1)>0&& (LR_AE1-LR_AE)-(LR_W-LR_W1)>0&& (LR_AE1-LR_AE)-(LR_X-LR_X1)>0&& (LR_AE1-LR_AE)-(LR_Z-LR_Z1)>0&& (LR_AE1-LR_AE)-(LR_F1-LR_F)>0&& (LR_AE1-LR_AE)-(LR_AB1-LR_AB)>0', '净利润本期比上期有所增加，主要是因为所得税费用的减少。所得税费用本期比上期减少{(LR_AE1-LR_AE)/LR_AE1*100}%，所得税费用的大幅度降低属于非经常性情况，建议管理层关注减少的原因，是否有享受优惠政策，注意优惠政策的可持续性。', '{(LR_AE1-LR_AE)/LR_AE1*100}', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3759, '2', '利润表首页预警', 'LR_AF-LR_AF1>0&& LR_AE1-LR_AE>0&& LR_AE1==0&&(LR_AE1-LR_AE)-(LR_A-LR_A1)>0&& (LR_AE1-LR_AE)-(LR_O1-LR_O)>0&& (LR_AE1-LR_AE)-(LR_P1-LR_P)>0&& (LR_AE1-LR_AE)-(LR_Q1-LR_Q)>0&& (LR_AE1-LR_AE)-(LR_R1-LR_R)>0&& (LR_AE1-LR_AE)-(LR_S1-LR_S)>0&& (LR_AE1-LR_AE)-(LR_T-LR_T1)>0&& (LR_AE1-LR_AE)-(LR_U-LR_U1)>0&& (LR_AE1-LR_AE)-(LR_W-LR_W1)>0&& (LR_AE1-LR_AE)-(LR_X-LR_X1)>0&& (LR_AE1-LR_AE)-(LR_Z-LR_Z1)>0&& (LR_AE1-LR_AE)-(LR_F1-LR_F)>0&& (LR_AE1-LR_AE)-(LR_AB1-LR_AB)>0', '净利润本期比上期有所增加，主要是因为所得税费用的减少。所得税费用本期比上期减少-%，所得税费用的大幅度降低属于非经常性情况，建议管理层关注减少的原因，是否有享受优惠政策，注意优惠政策的可持续性。', '', NULL, 'G200001', NULL, 0);
INSERT INTO `t_mode` VALUES (3760, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& (CLCB_A/CLCB_B-CLCB_A1/CLCB_B1)>0&&  (CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)-CLCB_B/CLCB_B1>0', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为原材料单价的上涨。建议管理层考虑：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 考虑原材料单价变动趋势是否与市场趋势相一致；3. 与供应商商讨原材料议价空间，同时加强成本控制管理，降低成本，提高利润。此外，建议管理层咨询市场部及采购部相关人员，如短期内原材料采购成本无法降低，则由市场部评估价格调整的可能性，以及产品对价格上升空间的接纳程度。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3761, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& CLCB_C-CLCB_C1>0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)>0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)>0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)>0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)>0&& CLCB_B-CLCB_B1>0&&                CLCB_B/CLCB_B1-(CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)>0', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为材料耗用数量的增加。建议管理层考虑耗用数量增长幅度及趋势是否与订单一致，如与订单趋势不一致，进一步分析其原因：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本增加；2. 是否生产流程管理不善导致的材料损耗上升，管理层应考虑加强生产管理，减少损耗和质量事故，改善生产工艺；3. 是否采购部采购过程的材料不达标造成的材料损耗增大，管理层应考虑加强原材料入库前检测并对采购部进行相关考核；4. 耗用量增加可能导致原来的安全库存达不到生产的要求。管理层需考虑调整或优化安全库存的必要性，对原材料进行有效管理。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3762, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& ZJCB_A-ZJCB_A1>0&& (ZJCB_A-ZJCB_A1)-(CLCB_C-CLCB_C1)>0&& (ZJCB_A-ZJCB_A1)-(SDCB_A-SDCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(RGCB_A-RGCB_A1)>0&& (ZJCB_A-ZJCB_A1)-(QTCB_A-QTCB_A1)>0', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为折旧成本的大幅度上涨。建议管理层查看设备投入以及设备运作情况，加大适用效率，与生产部及市场部讨论产量与销量的最合适配比，以达到利润最大化。同时，做好设备维护，减少大修及设备修理的支出，以达到控制成本的目的。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3763, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& SDCB_A-SDCB_A1>0&& (SDCB_A-SDCB_A1)-(CLCB_C-CLCB_C1)>0&& (SDCB_A-SDCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (SDCB_A-SDCB_A1)-(RGCB_A-RGCB_A1)>0&& (SDCB_A-SDCB_A1)-(QTCB_A-QTCB_A1)>0 ', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为水电成本的大幅度上涨。建议管理层关注水电成本的增长是因为水电单价的增长亦或因水电耗量增大而导致成本的增长，同时做好设备检修维护以及提高人工效率，确保设备在更低的耗电量中输出更大功率，从而控制成本。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3764, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& RGCB_A-RGCB_A1>0&& (RGCB_A-RGCB_A1)-(CLCB_C-CLCB_C1)>0&& (RGCB_A-RGCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (RGCB_A-RGCB_A1)-(SDCB_A-SDCB_A1)>0&& (RGCB_A-RGCB_A1)-(QTCB_A-QTCB_A1)>0', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要是因为人工成本及费用的上涨。建议管理层考虑通过绩效改革，控制加班时间等措施，尽量减低人工成本上涨对总成本造成的压力。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3765, '2', '营业成本预警', 'LR_F1!=0&&LR_F-LR_F1>0&& QTCB_A-QTCB_A1>0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)>0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)>0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)>0', '营业成本本期比上年同期增长{(LR_F-LR_F1)/LR_F1*100}%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层咨询专业机构或采用企业咨询服务模块，对可能存在或延续的问题咨询专家意见。', '{(LR_F-LR_F1)/LR_F1*100}', NULL, '20002', NULL, 0);
