INSERT INTO `t_mode` VALUES (3771, '2', '营业成本预警', 'LR_F1==0&&LR_F-LR_F1>0&& QTCB_A-QTCB_A1>0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)>0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)>0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)>0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)>0', '营业成本本期比上年同期增长-%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出增加导致。建议管理层与财务人员查看增长原因，如为特殊时点或时间导致，属于非经常性事项，可以忽略。对于可能对未来生产经营产生重大影响的事项，需进行进一步分析。建议管理层咨询专业机构或采用企业咨询服务模块，对可能存在或延续的问题咨询专家意见。', '', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3772, '2', '营业成本预警', 'LR_F-LR_F1<0&& CLCB_C-CLCB_C1<0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)<0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)<0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)<0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)<0&& (CLCB_A/CLCB_B-CLCB_A1/CLCB_B1)<0&&  (CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)-CLCB_B/CLCB_B1<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要是因为原材料单价的下降。建议管理层考虑：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本减少；2. 考虑原材料单价变动趋势是否与市场趋势相一致；3. 是否加强了供应商的管理，提升了对供应商的议价能力，以及成本控制管理取得成效，考虑成本进一步压缩的可能性以及如何在降低单价的同时保证原材料的质量。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3773, '2', '营业成本预警', 'LR_F-LR_F1<0&& CLCB_C-CLCB_C1<0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)<0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)<0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)<0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)<0&& CLCB_B-CLCB_B1<0&&                CLCB_B/CLCB_B1-(CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要是因为材料耗用数量的减少。建议管理层考虑耗用数量增长幅度及趋势是否与订单一致，如与订单趋势不一致，进一步分析其原因：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本减少；2. 材料耗用减少的幅度如接近或低于订单减少幅度，这种情况应考虑是否生产流程管理不善导致的材料损耗上升以及是否采购部采购过程的材料不达标造成的材料损耗增大，管理层应考虑采取措施改善生产管理及加强材料采购控制。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3774, '2', '营业成本预警', 'LR_F-LR_F1<0&& ZJCB_A-ZJCB_A1<0&& (ZJCB_A-ZJCB_A1)-(CLCB_C-CLCB_C1)<0&& (ZJCB_A-ZJCB_A1)-(SDCB_A-SDCB_A1)<0&& (ZJCB_A-ZJCB_A1)-(RGCB_A-RGCB_A1)<0&& (ZJCB_A-ZJCB_A1)-(QTCB_A-QTCB_A1)<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要是因为折旧成本的下降。建议管理层分析折旧成本下降的原因，考虑是否因工艺改进、人工效率提高所致，同时，评估利润进一步提升的可能性。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3775, '2', '营业成本预警', 'LR_F-LR_F1<0&& SDCB_A-SDCB_A1<0&& (SDCB_A-SDCB_A1)-(CLCB_C-CLCB_C1)<0&& (SDCB_A-SDCB_A1)-(ZJCB_A-ZJCB_A1)<0&& (SDCB_A-SDCB_A1)-(RGCB_A-RGCB_A1)<0&& (SDCB_A-SDCB_A1)-(QTCB_A-QTCB_A1)<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要是因为水电成本的大幅度降低。建议管理层关注水电单价是否统一降低或因工艺改进、人工效率提高所致，同时，评估利润进一步提升的可能性。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3776, '2', '营业成本预警', 'LR_F-LR_F1<0&& RGCB_A-RGCB_A1<0&& (RGCB_A-RGCB_A1)-(CLCB_C-CLCB_C1)<0&& (RGCB_A-RGCB_A1)-(ZJCB_A-ZJCB_A1)<0&& (RGCB_A-RGCB_A1)-(SDCB_A-SDCB_A1)<0&& (RGCB_A-RGCB_A1)-(QTCB_A-QTCB_A1)<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要是因为人工成本下降。建议管理层查看人工成本下降的原因，如为员工人数减少导致的人工成本总体金额的减少，要考虑人员的缩减是否与未来销售与生产计划相匹配；如为人工构成变化导致的下降，需与人力资源管理部门研究员工对人工构成的变化调整的接纳程度以及对人员稳定性的影响，从而评估人员流动性对未来销售及生产计划可能产生的影响。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3777, '2', '营业成本预警', 'LR_F-LR_F1<0&& QTCB_A-QTCB_A1<0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)<0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)<0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)<0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)<0', '营业成本本期比上年同期减少{(LR_F1-LR_F)/LR_F1*100}%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出减少导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后营业成本增长。', '{(LR_F1-LR_F)/LR_F1*100}', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3778, '2', '营业成本预警', 'LR_F1==0&&LR_F-LR_F1<0&& CLCB_C-CLCB_C1<0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)<0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)<0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)<0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)<0&& (CLCB_A/CLCB_B-CLCB_A1/CLCB_B1)<0&&  (CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)-CLCB_B/CLCB_B1<0', '营业成本本期比上年同期减少-%，主要是因为原材料单价的下降。建议管理层考虑：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本减少；2. 考虑原材料单价变动趋势是否与市场趋势相一致；3. 是否加强了供应商的管理，提升了对供应商的议价能力，以及成本控制管理取得成效，考虑成本进一步压缩的可能性以及如何在降低单价的同时保证原材料的质量。', '', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3779, '2', '营业成本预警', 'LR_F1==0&&LR_F-LR_F1<0&& CLCB_C-CLCB_C1<0&& (CLCB_C-CLCB_C1)-(ZJCB_A-ZJCB_A1)<0&& (CLCB_C-CLCB_C1)-(SDCB_A-SDCB_A1)<0&& (CLCB_C-CLCB_C1)-(RGCB_A-RGCB_A1)<0&& (CLCB_C-CLCB_C1)-(QTCB_A-QTCB_A1)<0&& CLCB_B-CLCB_B1<0&&                CLCB_B/CLCB_B1-(CLCB_A/CLCB_B)/(CLCB_A1/CLCB_B1)<0', '营业成本本期比上年同期减少-%，主要是因为材料耗用数量的减少。建议管理层考虑耗用数量增长幅度及趋势是否与订单一致，如与订单趋势不一致，进一步分析其原因：1. 是否因为进销存数据问题导致成本核算出现问题，从而引起本期结转的营业成本减少；2. 材料耗用减少的幅度如接近或低于订单减少幅度，这种情况应考虑是否生产流程管理不善导致的材料损耗上升以及是否采购部采购过程的材料不达标造成的材料损耗增大，管理层应考虑采取措施改善生产管理及加强材料采购控制。', '', NULL, '20002', NULL, 0);
