INSERT INTO `t_mode` VALUES (3783, '2', '营业成本预警', 'LR_F1==0&&LR_F-LR_F1<0&& QTCB_A-QTCB_A1<0&& (QTCB_A-QTCB_A1)-(CLCB_C-CLCB_C1)<0&& (QTCB_A-QTCB_A1)-(ZJCB_A-ZJCB_A1)<0&& (QTCB_A-QTCB_A1)-(SDCB_A-SDCB_A1)<0&& (QTCB_A-QTCB_A1)-(RGCB_A-RGCB_A1)<0', '营业成本本期比上年同期减少-%，主要由除人工、生产材料耗费、水电、折旧等主要项目外的剩余支出减少导致。建议管理层与财务人员查看减少原因，如为特殊时点或时间导致，属于非经常性事项，则需注意后续导致因素消失后营业成本增长。', '', NULL, '20002', NULL, 0);
INSERT INTO `t_mode` VALUES (3784, '2', '营业成本预警', 'LR_F-LR_F1==0', '与上年同期相比，本期营业成本金额与上年同期保持一致，此情况较为特殊，建议管理层：1. 与财务人员核查金额准确性；2. 与营业收入进行对比，查看营业成本的维持不变是否合理；3. 通过与供应商谈判降低采购单价，调整产能利用率，通过绩效考核促进成本降低，或者调整人员结构等方式，降低成本，从而达到节流的目的，增大企业利润。', '', NULL, '20002', NULL, 0);
